This project combines three peripherals on separate buses so they don't conflict: GPS on UART2, LoRa on SPI, and the OLED on I2C.

**Wiring Table**

| Module | Pin | Connects to ESP32 |
|---|---|---|
| NEO-6M GPS | VCC | 3.3V |
| NEO-6M GPS | GND | GND |
| NEO-6M GPS | TX | GPIO16 (RX2) |
| NEO-6M GPS | RX | GPIO17 (TX2) |
| SX1278 LoRa | VCC | 3.3V |
| SX1278 LoRa | GND | GND |
| SX1278 LoRa | SCK | GPIO18 |
| SX1278 LoRa | MISO | GPIO19 |
| SX1278 LoRa | MOSI | GPIO23 |
| SX1278 LoRa | NSS | GPIO5 |
| SX1278 LoRa | RST | GPIO14 |
| SX1278 LoRa | DIO0 | GPIO26 |
| SSD1306 OLED | VCC | 3.3V |
| SSD1306 OLED | GND | GND |
| SSD1306 OLED | SDA | GPIO21 |
| SSD1306 OLED | SCL | GPIO22 |

**Wiring Diagram**
```
                 +-------------+
                 |    ESP32    |
                 |             |
   NEO-6M GPS    |             |    SX1278 LoRa
  +---------+    |             |    +---------+
  |     VCC |----| 3.3V        |    |     VCC |---(3.3V, shared)
  |     GND |----| GND         |    |     GND |---(GND, shared)
  |      TX |----| GPIO16 (RX2)|    |     SCK |----| GPIO18
  |      RX |----| GPIO17 (TX2)|    |    MISO |----| GPIO19
  +---------+    |             |    |    MOSI |----| GPIO23
                 |             |    |     NSS |----| GPIO5
  SSD1306 OLED   |             |    |     RST |----| GPIO14
  +---------+    |             |    |    DIO0 |----| GPIO26
  |     VCC |----| 3.3V(shared)|    +---------+
  |     GND |----| GND (shared)|
  |     SDA |----| GPIO21      |
  |     SCL |----| GPIO22      |
  +---------+    +-------------+
```

Note: LoRa module is 3.3V only -- do not power it from 5V.

**Code**
```cpp
#include <TinyGPSPlus.h>
#include <HardwareSerial.h>
#include <SPI.h>
#include <LoRa.h>
#include <Wire.h>
#include <Adafruit_GFX.h>
#include <Adafruit_SSD1306.h>

HardwareSerial gpsSerial(2); // UART2: RX16, TX17
TinyGPSPlus gps;
Adafruit_SSD1306 display(128, 64, &Wire, -1);

#define LORA_NSS 5
#define LORA_RST 14
#define LORA_DIO0 26

void setup() {
  Serial.begin(115200);
  gpsSerial.begin(9600, SERIAL_8N1, 16, 17);

  Wire.begin(21, 22);
  display.begin(SSD1306_SWITCHCAPVCC, 0x3C);
  display.clearDisplay();

  LoRa.setPins(LORA_NSS, LORA_RST, LORA_DIO0);
  if (!LoRa.begin(915E6)) {
    Serial.println("LoRa init failed");
    while (1);
  }
}

void loop() {
  while (gpsSerial.available() > 0) {
    gps.encode(gpsSerial.read());
  }

  if (gps.location.isUpdated()) {
    float lat = gps.location.lat();
    float lng = gps.location.lng();

    LoRa.beginPacket();
    LoRa.print(lat, 6);
    LoRa.print(",");
    LoRa.print(lng, 6);
    LoRa.endPacket();

    display.clearDisplay();
    display.setCursor(0, 0);
    display.setTextSize(1);
    display.setTextColor(SSD1306_WHITE);
    display.printf("Lat: %.6f\nLng: %.6f\nSent via LoRa", lat, lng);
    display.display();
  }
}
```

**How it works:** The GPS feeds NMEA sentences into `gps.encode()` continuously on UART2. Once `gps.location.isUpdated()` returns true, we grab the latest coordinates, transmit them as a plain-text packet over LoRa, and refresh the OLED so you have local visual confirmation of what was just sent.

The Core2's internal I2C bus (GPIO21/22) is reserved for onboard power management and touch, so external sensors need to go on Port A instead.

**Wiring Table**

| BMP280 Pin | Connects to Core2 Port A |
|---|---|
| VCC | 3.3V |
| GND | GND |
| SDA | GPIO32 |
| SCL | GPIO33 |

**Wiring Diagram**
```
              +------------------+
              | M5Stack Core2    |
              |    (Port A)      |
  BMP280      |                  |
 +--------+   |                  |
 |    VCC |---| 3.3V             |
 |    GND |---| GND              |
 |    SDA |---| GPIO32           |
 |    SCL |---| GPIO33           |
 +--------+   +------------------+
```

**Code**
```cpp
#include <M5Core2.h>
#include <Adafruit_BMP280.h>

Adafruit_BMP280 bmp;

void setup() {
  M5.begin();
  Wire.begin(32, 33); // Port A SDA, SCL

  if (!bmp.begin(0x76)) {
    M5.Lcd.println("BMP280 not found");
    while (1);
  }
}

void loop() {
  M5.Lcd.setCursor(0, 0);
  M5.Lcd.printf("Temp: %.1f C\n", bmp.readTemperature());
  M5.Lcd.printf("Pressure: %.1f hPa\n", bmp.readPressure() / 100.0F);
  delay(1000);
  M5.Lcd.fillScreen(BLACK);
}
```

**How it works:** `Wire.begin(32, 33)` explicitly points the I2C bus at Port A's pins rather than the Core2's default internal bus -- without this line, the library would try to talk to the internal bus and never find the sensor.

The HC-SR04's ECHO pin outputs 5V logic, but ESP32 GPIOs are 3.3V-only, so this one needs a voltage divider to avoid damaging the board.

**Wiring Table**

| HC-SR04 Pin | Connects to ESP32 |
|---|---|
| VCC | 5V (VIN pin) |
| GND | GND |
| TRIG | GPIO5 |
| ECHO | GPIO18 (through voltage divider) |

**Wiring Diagram**
```
              +----------------+
              |     ESP32      |
              |                |
  HC-SR04     |                |
 +--------+   |                |
 |    VCC |---| VIN (5V)       |
 |    GND |---| GND            |
 |   TRIG |---| GPIO5          |
 |   ECHO |---[1k]--+--[2k]--- | GND
 +--------+         |
                     +----------| GPIO18
```

The 1k/2k resistor divider drops the ECHO pin's 5V signal down to roughly 3.3V before it reaches GPIO18 -- skipping this can degrade or damage the pin over time.

**Code**
```cpp
#define TRIG_PIN 5
#define ECHO_PIN 18

void setup() {
  Serial.begin(115200);
  pinMode(TRIG_PIN, OUTPUT);
  pinMode(ECHO_PIN, INPUT);
}

void loop() {
  digitalWrite(TRIG_PIN, LOW);
  delayMicroseconds(2);
  digitalWrite(TRIG_PIN, HIGH);
  delayMicroseconds(10);
  digitalWrite(TRIG_PIN, LOW);

  long duration = pulseIn(ECHO_PIN, HIGH);
  float distanceCm = duration * 0.0343 / 2;

  Serial.printf("Distance: %.1f cm\n", distanceCm);
  delay(500);
}
```

**How it works:** The sketch pulses TRIG high for 10 microseconds to fire an ultrasonic burst, then measures how long ECHO stays high with `pulseIn()`. That duration is proportional to round-trip travel time, so dividing by 2 and multiplying by the speed of sound gives one-way distance.

The DS18B20 uses Dallas Semiconductor's OneWire protocol, which -- like the DHT22 -- needs a pull-up resistor on the data line.

**Wiring Table**

| DS18B20 Wire | Connects to ESP32 |
|---|---|
| Red (VCC) | 3.3V |
| Black (GND) | GND |
| Yellow (DATA) | GPIO4 |

**Wiring Diagram**
```
              +----------------+
              |     ESP32      |
              |                |
  DS18B20     |                |
 +--------+   |                |
 |    VCC |---| 3.3V           |
 |    GND |---| GND            |
 |   DATA |---| GPIO4          |
 +--------+   +----------------+
       |
     [4.7k ohm pull-up resistor between DATA and VCC]
```

**Code**
```cpp
#include <OneWire.h>
#include <DallasTemperature.h>

#define ONE_WIRE_PIN 4

OneWire oneWire(ONE_WIRE_PIN);
DallasTemperature sensors(&oneWire);

void setup() {
  Serial.begin(115200);
  sensors.begin();
}

void loop() {
  sensors.requestTemperatures();
  float tempC = sensors.getTempCByIndex(0);
  Serial.printf("Temperature: %.2f C\n", tempC);
  delay(1000);
}
```

**How it works:** OneWire lets multiple DS18B20 probes share a single data line, each identified by a unique factory-burned address. `getTempCByIndex(0)` reads the first (or only) sensor found on the bus -- if you add more probes later, you'd enumerate their addresses instead of relying on index order.

The BME280 uses I2C with a default address of 0x76 (or 0x77 if SDO is pulled high), so it shares the ESP32's standard I2C bus on GPIO 21 (SDA) and GPIO 22 (SCL) without needing any extra pins.

**Wiring Table**

| Component Pin | Connects to ESP32 |
|---|---|
| VCC | 3.3V |
| GND | GND |
| SDA | GPIO 21 |
| SCL | GPIO 22 |
| SDO | GND (sets I2C address to 0x76) |
| CSB | 3.3V (forces I2C mode) |

**Wiring Diagram**
```
        +------------------+          +-------------------+
        |      ESP32       |          |      BME280       |
        |                  |          |                   |
        |       3.3V o-----+----------+o VCC              |
        |        GND o-----+----------+o GND              |
        |  GPIO21/SDA o----+----------+o SDA              |
        |  GPIO22/SCL o----+----------+o SCL              |
        |                  |          |o SDO o-- GND      |
        |                  |          |o CSB o-- 3.3V     |
        +------------------+          +-------------------+
```
The BME280 is a 3.3V-only device — do not connect VCC to 5V or you risk damaging the sensor.

**Code**
```cpp
#include <Wire.h>
#include <Adafruit_BME280.h>
#include <Adafruit_Sensor.h>

#define BME280_I2C_ADDR 0x76

Adafruit_BME280 bme;

void setup() {
  Serial.begin(115200);
  Wire.begin(21, 22); // SDA, SCL

  if (!bme.begin(BME280_I2C_ADDR, &Wire)) {
    Serial.println("Could not find a valid BME280 sensor, check wiring!");
    while (1);
  }

  Serial.println("BME280 sensor found!");
}

void loop() {
  float temperature = bme.readTemperature();         // Celsius
  float humidity    = bme.readHumidity();             // %RH
  float pressure    = bme.readPressure() / 100.0F;   // hPa

  Serial.print("Temperature: ");
  Serial.print(temperature);
  Serial.println(" °C");

  Serial.print("Humidity: ");
  Serial.print(humidity);
  Serial.println(" %");

  Serial.print("Pressure: ");
  Serial.print(pressure);
  Serial.println(" hPa");

  Serial.println("---");
  delay(2000);
}
```

**How it works:** Passing `&Wire` explicitly to `bme.begin()` ensures the library uses the correct I2C bus instance initialized with the ESP32's SDA/SCL pins, which matters on multi-bus capable boards. Dividing `readPressure()` by 100.0F converts the raw value from Pascals to the more human-readable hectopascals (hPa).

The MPU6050 uses I2C and runs on 3.3V, so it connects directly to the ESP32's hardware I2C bus (SDA/SCL) without any level shifting needed.

**Wiring Table**

| Component Pin | Connects to ESP32 |
|---|---|
| VCC | 3.3V |
| GND | GND |
| SDA | GPIO 21 (SDA) |
| SCL | GPIO 22 (SCL) |
| AD0 | GND (sets I2C address to 0x68) |
| INT | Not connected (optional) |

**Wiring Diagram**
```
        +----------------+          +-------------------+
        |   ESP32        |          |   MPU6050         |
        |                |          |                   |
        |   3.3V  o------+----------+o VCC              |
        |   GND   o------+----+-----+o GND              |
        |                |   |      |                   |
        |  GPIO21 o------+----(-----+o SDA              |
        |  GPIO22 o------+----(-----+o SCL              |
        |                |   |      |                   |
        |                |   +------+o AD0 (-> GND)     |
        +----------------+          +-------------------+
```

AD0 pulled to GND fixes the I2C address at 0x68; pulling it HIGH would change the address to 0x69, allowing two MPU6050s on the same bus.

**Code**
```cpp
#include <Arduino.h>
#include <Wire.h>

const uint8_t MPU6050_ADDR   = 0x68;
const uint8_t REG_PWR_MGMT_1 = 0x6B;
const uint8_t REG_ACCEL_XOUT = 0x3B;
const uint8_t REG_GYRO_XOUT  = 0x43;

// Sensitivity scale factors (default ±2g / ±250°/s full-scale ranges)
const float ACCEL_SCALE = 16384.0f; // LSB/g
const float GYRO_SCALE  = 131.0f;   // LSB/(°/s)

void writeByte(uint8_t reg, uint8_t value) {
  Wire.beginTransmission(MPU6050_ADDR);
  Wire.write(reg);
  Wire.write(value);
  Wire.endTransmission();
}

void readBytes(uint8_t reg, uint8_t count, uint8_t* dest) {
  Wire.beginTransmission(MPU6050_ADDR);
  Wire.write(reg);
  Wire.endTransmission(false); // repeated start keeps the bus active
  Wire.requestFrom(MPU6050_ADDR, count);
  for (uint8_t i = 0; i < count && Wire.available(); i++) {
    dest[i] = Wire.read();
  }
}

int16_t combineBytes(uint8_t high, uint8_t low) {
  return (int16_t)((high << 8) | low);
}

void setup() {
  Serial.begin(115200);
  Wire.begin(21, 22); // SDA=GPIO21, SCL=GPIO22

  // Wake the MPU6050 (clears the SLEEP bit in PWR_MGMT_1)
  writeByte(REG_PWR_MGMT_1, 0x00);
  delay(100);

  Serial.println("MPU6050 ready");
}

void loop() {
  uint8_t buf[6];

  // Read accelerometer (6 bytes: X_H, X_L, Y_H, Y_L, Z_H, Z_L)
  readBytes(REG_ACCEL_XOUT, 6, buf);
  float ax = combineBytes(buf[0], buf[1]) / ACCEL_SCALE;
  float ay = combineBytes(buf[2], buf[3]) / ACCEL_SCALE;
  float az = combineBytes(buf[4], buf[5]) / ACCEL_SCALE;

  // Read gyroscope (same layout)
  readBytes(REG_GYRO_XOUT, 6, buf);
  float gx = combineBytes(buf[0], buf[1]) / GYRO_SCALE;
  float gy = combineBytes(buf[2], buf[3]) / GYRO_SCALE;
  float gz = combineBytes(buf[4], buf[5]) / GYRO_SCALE;

  Serial.printf("Accel (g):  X=%.3f  Y=%.3f  Z=%.3f\n", ax, ay, az);
  Serial.printf("Gyro (°/s): X=%.3f  Y=%.3f  Z=%.3f\n\n", gx, gy, gz);

  delay(500);
}
```

**How it works:** Writing `0x00` to the PWR_MGMT_1 register is essential because the MPU6050 powers up in sleep mode and will return all zeros until explicitly woken. The `endTransmission(false)` call issues a repeated-start condition rather than a STOP, which is required by the MPU6050 datasheet for burst register reads to prevent the internal address pointer from resetting between the write and read phases.

The DS3231 uses I2C and operates at 3.3V, making it directly compatible with the ESP32's default I2C pins without any level shifting.

**Wiring Table**

| Component Pin | Connects to ESP32 |
|---|---|
| VCC | 3.3V |
| GND | GND |
| SDA | GPIO 21 |
| SCL | GPIO 22 |

**Wiring Diagram**
```
        +------------------+          +-------------------+
        |      ESP32       |          |   DS3231 RTC      |
        |                  |          |                   |
        |       3.3V |-----+----------| VCC               |
        |        GND |-----+----------| GND               |
        |  GPIO21 SDA|-----+----------| SDA               |
        |  GPIO22 SCL|-----+----------| SCL               |
        +------------------+          +-------------------+
```

The DS3231 module typically includes onboard pull-up resistors on SDA and SCL, so no external resistors are needed in most cases.

**Code**
```cpp
#include <Wire.h>
#include <RTClib.h>

RTC_DS3231 rtc;

void setup() {
  Serial.begin(115200);
  Wire.begin(21, 22); // SDA, SCL

  if (!rtc.begin()) {
    Serial.println("Could not find DS3231 RTC. Check wiring!");
    while (1);
  }

  // Uncomment the line below ONCE to set RTC to compile time, then re-comment
  // rtc.adjust(DateTime(F(__DATE__), F(__TIME__)));

  if (rtc.lostPower()) {
    Serial.println("RTC lost power, setting time to compile time.");
    rtc.adjust(DateTime(F(__DATE__), F(__TIME__)));
  }

  Serial.println("DS3231 RTC initialized.");
}

void loop() {
  DateTime now = rtc.now();

  Serial.print(now.year(), DEC);
  Serial.print('/');
  Serial.print(now.month(), DEC);
  Serial.print('/');
  Serial.print(now.day(), DEC);
  Serial.print(" ");
  Serial.print(now.hour(), DEC);
  Serial.print(':');
  Serial.print(now.minute(), DEC);
  Serial.print(':');
  Serial.print(now.second(), DEC);
  Serial.println();

  delay(1000);
}
```

**How it works:** The `rtc.lostPower()` check detects whether the DS3231's coin cell battery died or was never present, automatically re-syncing the clock to the firmware's compile timestamp as a fallback. The `DateTime(F(__DATE__), F(__TIME__))` macro pulls the build date and time directly from the compiler, so flashing the firmware is enough to get a reasonable starting time without hardcoding values.

The ADS1115 communicates over I2C and its ADDR pin can be tied to GND, VCC, SDA, or SCL to select one of four I2C addresses, making it easy to share the bus with other I2C peripherals.

**Wiring Table**

| Component Pin | Connects to ESP32 |
|---|---|
| VCC | 3.3V |
| GND | GND |
| SDA | GPIO 21 (SDA) |
| SCL | GPIO 22 (SCL) |
| ADDR | GND (sets address 0x48) |
| ALRT/RDY | (not connected) |

**Wiring Diagram**
```
        +----------------+          +-------------------+
        |   ADS1115      |          |      ESP32        |
        |                |          |                   |
        |   VCC  o-------+----------+ 3.3V              |
        |   GND  o-------+----------+ GND               |
        |   SDA  o-------+----------+ GPIO 21 (SDA)     |
        |   SCL  o-------+----------+ GPIO 22 (SCL)     |
        |   ADDR o-------+----------+ GND (addr 0x48)   |
        |                |          |                   |
        |   A0   o-- [signal in]    |                   |
        |   A1   o-- [optional]     |                   |
        |   A2   o-- [optional]     |                   |
        |   A3   o-- [optional]     +-------------------+
        +----------------+
```
The ADS1115 is a 3.3V-safe device; do not exceed 3.3V on its VCC or analog input pins when powered from the ESP32's 3.3V rail.

**Code**
```cpp
#include <Wire.h>
#include <Adafruit_ADS1X15.h>

Adafruit_ADS1115 ads;

void setup() {
  Serial.begin(115200);
  Wire.begin(21, 22); // SDA = GPIO21, SCL = GPIO22

  if (!ads.begin(0x48)) {
    Serial.println("Failed to initialize ADS1115. Check wiring!");
    while (1);
  }

  // Set gain to +/-4.096V range (1 bit = 0.125 mV)
  ads.setGain(GAIN_ONE);
  Serial.println("ADS1115 initialized.");
}

void loop() {
  // Read single-ended input on channel 0 (A0 vs GND)
  int16_t rawValue = ads.readADC_SingleEnded(0);

  // Convert raw value to voltage using the multiplier for GAIN_ONE
  float voltage = rawValue * 0.125 / 1000.0; // 0.125 mV per bit

  Serial.print("Raw ADC (A0): ");
  Serial.print(rawValue);
  Serial.print("  Voltage: ");
  Serial.print(voltage, 4);
  Serial.println(" V");

  delay(500);
}
```

**How it works:** The `ads.setGain(GAIN_ONE)` call configures the ADS1115's internal programmable gain amplifier to a ±4.096 V full-scale range, where each raw LSB corresponds to exactly 0.125 mV — this multiplier is what converts the 16-bit signed integer from `readADC_SingleEnded()` into a real voltage. Because the ADS1115 performs the conversion internally and returns a result over I2C, the ESP32's own ADC (which is noisy and nonlinear) is completely bypassed, giving true 16-bit resolution.

The NRF24L01 runs on 3.3V only and uses SPI with two extra control pins (CE and CSN), so all lines must stay within 3.3V logic — the ESP32's native 3.3V GPIO is a perfect match here.

**Wiring Table**

| Component Pin | Connects to ESP32 |
|---|---|
| VCC | 3.3V (NOT 5V — module will be damaged) |
| GND | GND |
| SCK | GPIO 18 (SPI SCK) |
| MISO | GPIO 19 (SPI MISO) |
| MOSI | GPIO 23 (SPI MOSI) |
| CSN | GPIO 5 (chip select) |
| CE | GPIO 4 (chip enable) |
| IRQ | (optional) GPIO 2, interrupt-capable |

**Wiring Diagram**
```
 +-------------------+          +-------------------+
 |       ESP32       |          |     NRF24L01      |
 |                   |          |                   |
 |       3.3V |------+----------| VCC               |
 |        GND |------+----------| GND               |
 |   GPIO18   |------+----------| SCK               |
 |   GPIO19   |------+----------| MISO              |
 |   GPIO23   |------+----------| MOSI              |
 |    GPIO5   |------+----------| CSN               |
 |    GPIO4   |------+----------| CE                |
 |    GPIO2   |------+----------| IRQ (optional)    |
 +-------------------+          +-------------------+
```
Never connect VCC to 5V — the NRF24L01 has no on-board regulator and will be permanently damaged; also add a 10µF capacitor across VCC/GND near the module to stabilize its notoriously noisy power draw.

**Code**
```cpp
#include <SPI.h>
#include <RF24.h>

// CE = GPIO4, CSN = GPIO5
RF24 radio(4, 5);

// A pipe address — both transmitter and receiver must use the same address
const uint64_t pipeAddress = 0xE8E8F0F0E1LL;

void setup() {
  Serial.begin(115200);

  if (!radio.begin()) {
    Serial.println("NRF24L01 not responding — check wiring!");
    while (true);
  }

  radio.setPALevel(RF24_PA_LOW);   // low power for bench testing
  radio.setDataRate(RF24_250KBPS); // best range at lowest data rate
  radio.openWritingPipe(pipeAddress);
  radio.stopListening();           // set module to transmit mode

  Serial.println("NRF24L01 transmitter ready.");
}

void loop() {
  const char message[] = "Hello from ESP32!";

  bool success = radio.write(&message, sizeof(message));

  if (success) {
    Serial.println("Message sent successfully.");
  } else {
    Serial.println("Transmission failed — no ACK received.");
  }

  delay(1000);
}
```

**How it works:** The `radio.begin()` call communicates with the module over SPI and returns `false` if it cannot read back expected register values, making it a reliable sanity-check for wiring problems. `radio.stopListening()` is the key call that switches the NRF24L01 into PTX (primary transmitter) mode — without it the module stays in listening mode and `write()` will always fail.

The MAX7219 uses hardware SPI but requires only a single CS line, and since it operates at 5V logic while the ESP32 outputs 3.3V, most MAX7219 modules will still accept 3.3V data lines reliably due to the chip's relatively low VIH threshold.

**Wiring Table**

| Component Pin | Connects to ESP32 |
|---|---|
| VCC | 5V |
| GND | GND |
| DIN | GPIO 23 (MOSI) |
| CLK | GPIO 18 (SCK) |
| CS (LOAD) | GPIO 5 |

**Wiring Diagram**
```
        +------------------+          +-------------------+
        |      ESP32       |          |  MAX7219 8x8 LED  |
        |                  |          |      Matrix       |
        |       5V o-------+----------+o VCC              |
        |      GND o-------+----------+o GND              |
        | GPIO23/MOSI o----+----------+o DIN              |
        |  GPIO18/SCK o----+----------+o CLK              |
        |      GPIO5 o-----+----------+o CS (LOAD)        |
        +------------------+          +-------------------+
```

A 10µF decoupling capacitor between VCC and GND close to the MAX7219 is recommended to suppress noise during LED switching transients.

**Code**
```cpp
#include <Arduino.h>
#include <SPI.h>
#include <MD_Parola.h>
#include <MD_MAX72XX.h>

// Hardware configuration
#define HARDWARE_TYPE MD_MAX72XX::FC16_HW
#define MAX_DEVICES   1
#define CS_PIN        5

// Create Parola object using hardware SPI
MD_Parola display(HARDWARE_TYPE, CS_PIN, MAX_DEVICES);

const char* scrollText = "Hello ESP32! ";

void setup() {
  Serial.begin(115200);

  // Initialize the display
  display.begin();
  display.setIntensity(5);       // Brightness 0-15
  display.displayClear();

  // Set up scrolling text
  display.displayScroll(
    scrollText,
    PA_LEFT,       // align left
    PA_SCROLL_LEFT,// scroll direction
    50             // scroll speed in ms per step
  );

  Serial.println("MAX7219 initialized, scrolling text...");
}

void loop() {
  // displayAnimate() returns true when the animation cycle completes
  if (display.displayAnimate()) {
    // Restart the scroll animation
    display.displayReset();
  }
}
```

**How it works:** `MD_Parola` wraps `MD_MAX72XX` to handle the SPI framing and double-buffered animation engine; calling `displayAnimate()` every loop tick advances the scroll by one pixel step only when the configured delay has elapsed, and returning `true` signals completion so `displayReset()` loops the message seamlessly. The `FC16_HW` hardware type constant corrects the column/row mapping for the most common cheap FC-16 module PCB layout, which wires the LED matrix in a non-default orientation.

The ST7735 runs on 3.3V SPI and uses a few extra control lines (DC, RST, CS) beyond the standard SPI bus, so all signals are kept within the ESP32's 3.3V logic levels without any level shifting.

**Wiring Table**

| Component Pin | Connects to ESP32 |
|---|---|
| VCC | 3.3V |
| GND | GND |
| SCL (SCK) | GPIO 18 (SPI SCK) |
| SDA (MOSI) | GPIO 23 (SPI MOSI) |
| CS | GPIO 5 |
| DC (A0) | GPIO 2 |
| RST | GPIO 4 |
| BL (backlight) | 3.3V (or GPIO for PWM control) |

**Wiring Diagram**
```
        +---------------------------+          +----------------------+
        |          ESP32            |          |  ST7735 1.8" TFT     |
        |                          |          |                      |
        |       GPIO 18 (SCK) -----+----------+ SCL                  |
        |      GPIO 23 (MOSI) -----+----------+ SDA                  |
        |            GPIO 5  ------+----------+ CS                   |
        |            GPIO 2  ------+----------+ DC                   |
        |            GPIO 4  ------+----------+ RST                  |
        |                          |          |                      |
        |              3.3V -------+----------+ VCC                  |
        |              3.3V -------+----------+ BL                   |
        |               GND -------+----------+ GND                  |
        +---------------------------+          +----------------------+
```

The ST7735 is NOT 5V tolerant — always use the ESP32's 3.3V rail for VCC and confirm all GPIO outputs are 3.3V (they are on ESP32 by default).

**Code**
```cpp
#include <Adafruit_GFX.h>
#include <Adafruit_ST7735.h>
#include <SPI.h>

// Pin definitions
#define TFT_CS   5
#define TFT_DC   2
#define TFT_RST  4

// Create display object using hardware SPI
Adafruit_ST7735 tft = Adafruit_ST7735(TFT_CS, TFT_DC, TFT_RST);

void setup() {
  Serial.begin(115200);

  // Initialize display with ST7735S 1.8" tab type (black tab is most common)
  tft.initR(INITR_BLACKTAB);

  // Rotate display if needed (0–3)
  tft.setRotation(1);

  // Fill background black
  tft.fillScreen(ST77XX_BLACK);

  // Draw a filled rectangle
  tft.fillRect(10, 10, 60, 40, ST77XX_BLUE);

  // Draw an outlined circle
  tft.drawCircle(120, 60, 30, ST77XX_GREEN);

  // Draw a filled triangle
  tft.fillTriangle(70, 100, 100, 60, 130, 100, ST77XX_RED);

  // Print text
  tft.setTextColor(ST77XX_WHITE);
  tft.setTextSize(2);
  tft.setCursor(10, 110);
  tft.println("ESP32 TFT");

  tft.setTextColor(ST77XX_YELLOW);
  tft.setTextSize(1);
  tft.setCursor(10, 130);
  tft.println("ST7735 via SPI");
}

void loop() {
  // Animate a moving dot across the top
  static int x = 0;
  tft.fillCircle(x, 5, 3, ST77XX_MAGENTA);
  delay(30);
  tft.fillCircle(x, 5, 3, ST77XX_BLACK); // erase
