**Code**
```cpp
#include <Arduino.h>

const int PIN_VRX = 34;   // X-axis analog input
const int PIN_VRY = 35;   // Y-axis analog input
const int PIN_SW  = 32;   // Joystick push-button

const int ADC_MAX = 4095;           // 12-bit ADC resolution on ESP32
const int CENTER  = ADC_MAX / 2;    // ~2047, resting position reference

void setup() {
  Serial.begin(115200);
  pinMode(PIN_SW, INPUT_PULLUP);    // Button pulls LOW when pressed
  analogReadResolution(12);         // Explicitly set 12-bit resolution (default on ESP32)
  analogSetAttenuation(ADC_11db);   // Full 0–3.3V input range
}

void loop() {
  int xRaw = analogRead(PIN_VRX);
  int yRaw = analogRead(PIN_VRY);
  bool buttonPressed = (digitalRead(PIN_SW) == LOW);

  // Map raw ADC values to -100..+100 range for convenience
  int xMapped = map(xRaw, 0, ADC_MAX, -100, 100);
  int yMapped = map(yRaw, 0, ADC_MAX, -100, 100);

  Serial.print("X: ");
  Serial.print(xMapped);
  Serial.print("  Y: ");
  Serial.print(yMapped);
  Serial.print("  Button: ");
  Serial.println(buttonPressed ? "PRESSED" : "released");

  delay(100);
}
```

**How it works:** `analogSetAttenuation(ADC_11db)` expands the ADC input range to the full 0–3.3V span so the joystick's potentiometer sweep maps cleanly across all 4096 steps; the button uses `INPUT_PULLUP` so no external resistor is needed — the pin reads HIGH at rest and goes LOW when the joystick is clicked.

