#include <Wire.h>
#include <Adafruit_BME280.h>
#include <Adafruit_MPU6050.h>
#include <Adafruit_Sensor.h>

#define BME280_ADDR 0x76
#define SDA_PIN 21
#define SCL_PIN 22

Adafruit_BME280 bme;
Adafruit_MPU6050 mpu;

void setup() {
  Serial.begin(115200);
  Wire.begin(SDA_PIN, SCL_PIN);

  // Initialize BME280
  if (!bme.begin(BME280_ADDR, &Wire)) {
    Serial.println("BME280 not found! Check wiring and address.");
    while (1);
  }
  Serial.println("BME280 initialized.");

  // Initialize MPU6050
  if (!mpu.begin()) {
    Serial.println("MPU6050 not found! Check wiring and AD0 pin.");
    while (1);
  }
  mpu.setAccelerometerRange(MPU6050_RANGE_8_G);
  mpu.setGyroRange(MPU6050_RANGE_500_DEG);
  mpu.setFilterBandwidth(MPU6050_BAND_21_HZ);
  Serial.println("MPU6050 initialized.");
}

void loop() {
  // --- BME280 readings ---
  float temperature = bme.readTemperature();
  float humidity    = bme.readHumidity();
  float pressure    = bme.readPressure() / 100.0F; // hPa

  Serial.println("=== BME280 ===");
  Serial.print("Temperature: "); Serial.print(temperature); Serial.println(" °C");
  Serial.print("Humidity:    "); Serial.print(humidity);    Serial.println(" %");
  Serial.print("Pressure:    "); Serial.print(pressure);    Serial.println(" hPa");

  // --- MPU6050 readings ---
  sensors_event_t accel, gyro, temp;
  mpu.getEvent(&accel, &gyro, &temp);

  Serial.println("=== MPU6050 ===");
  Serial.print("Accel X: "); Serial.print(accel.acceleration.x); Serial.println(" m/s^2");
  Serial.print("Accel Y: "); Serial.print(accel.acceleration.y); Serial.println(" m/s^2");
  Serial.print("Accel Z: "); Serial.print(accel.acceleration.z); Serial.println(" m/s^2");
  Serial.print("Gyro  X: "); Serial.print(gyro.gyro.x);         Serial.println(" rad/s");
  Serial.print("Gyro  Y: "); Serial.print(gyro.gyro.y);         Serial.println(" rad/s");
  Serial.print("Gyro  Z: "); Serial.print(gyro.gyro.z);         Serial.println(" rad/s");

  Serial.println();
  delay(1000);
}
```

**How it works:** Both sensor library instances share the same `Wire` object (passed explicitly to `bme.begin()` and used implicitly by `mpu.begin()`), so all I2C traffic flows over the same two pins without conflict — the bus arbitrates between devices using their distinct addresses (0x76 for BME280, 0x68 for MPU6050). Tying the MPU6050's AD0 pin to GND is critical: it locks the device address to 0x68 rather than 0x69, preventing an address collision if a second MPU6050 were ever added.

The ACS712 outputs an analog voltage centered at VCC/2 (nominally 2.5V at 5V supply), so the ESP32's ADC pin reads a ratiometric signal where deviation from the midpoint represents current flow in either direction.

**Wiring Table**

| Component Pin | Connects to ESP32 |
|---|---|
| VCC | 5V (Vin) |
| GND | GND |
| OUT | GPIO34 (ADC1_CH6) |

**Wiring Diagram**
```
+----------------+          +-------------------+
|   ACS712       |          |      ESP32        |
|                |          |                   |
|  VCC  o--------+----------+ 5V (Vin)          |
|                |          |                   |
|  GND  o--------+----------+ GND               |
|                |          |                   |
|  OUT  o--------+----------+ GPIO34 (ADC)      |
+----------------+          +-------------------+
```
Note: The ACS712 OUT pin produces ~2.5V at zero current (5V supply); GPIO34 is input-only and ADC-capable, but keep in mind the ESP32 ADC is rated for 0–3.3V max — at 5V supply the midpoint is 2.5V which is within range, but verify peak swing stays below 3.3V for your load.

**Code**
```cpp
#include <Arduino.h>

// ACS712 configuration
const int ADC_PIN = 34;           // GPIO34, ADC1_CH6
const float VREF = 3.3f;          // ESP32 ADC reference voltage
const int ADC_RESOLUTION = 4095;  // 12-bit ADC
const float SENSITIVITY = 0.185f; // 185 mV/A for ACS712-05B (use 0.100 for 20A, 0.066 for 30A)
const float VCC = 5.0f;           // Module supply voltage
const float ZERO_CURRENT_VOLTAGE = VCC / 2.0f; // 2.5V at zero current

// Number of samples to average for noise reduction
const int NUM_SAMPLES = 100;

void setup() {
  Serial.begin(115200);
  analogReadResolution(12); // Set ADC to 12-bit
  Serial.println("ACS712 Current Sensor Ready");
}

float readCurrentAmps() {
  long sum = 0;
  for (int i = 0; i < NUM_SAMPLES; i++) {
    sum += analogRead(ADC_PIN);
    delayMicroseconds(100);
  }
  float avgADC = sum / (float)NUM_SAMPLES;

  // Convert ADC reading to voltage (ESP32 ADC measures 0-3.3V)
  float measuredVoltage = (avgADC / ADC_RESOLUTION) * VREF;

  // The zero-current output of ACS712 is VCC/2 = 2.5V,
  // but we must scale it to what the ESP32 ADC would see.
  // Since we're reading the OUT pin directly, midpoint maps as:
  float zeroCurrentADCVoltage = ZERO_CURRENT_VOLTAGE * (VREF / VREF);
  // (2.5V is within 0-3.3V range, read directly)

  float deltaVoltage = measuredVoltage - ZERO_CURRENT_VOLTAGE;
  float current = deltaVoltage / SENSITIVITY;
  return current;
}

void loop() {
  float current = readCurrentAmps();
  Serial.print("Current: ");
  Serial.print(current, 3);
  Serial.println(" A");
  delay(500);
}
```

**How it works:** The key insight is subtracting the zero-current midpoint voltage (2.5V) from the measured voltage before dividing by the sensitivity — this converts the ratiometric ADC reading into a signed current value that can be positive or negative depending on current direction. Averaging 100 samples before converting reduces ADC noise, which is critical because the ACS712's small per-amp voltage change (185 mV/A) means even minor ADC jitter translates to visible current error.

The rain sensor module outputs both a digital threshold signal and an analog voltage proportional to rain/moisture level, so we connect the AO (analog out) pin to one of the ESP32's ADC-capable GPIOs for continuous readings.

**Wiring Table**

| Component Pin | Connects to ESP32 |
|---|---|
| VCC | 3.3V |
| GND | GND |
| AO (Analog Out) | GPIO34 (ADC1_CH6) |
| DO (Digital Out) | Not connected (optional: any free GPIO) |

**Wiring Diagram**
```
+-------------------------+          +-------------------+
|         ESP32           |          |  Rain Sensor Mod  |
|                         |          |                   |
|  3.3V |-----------------+----------| VCC               |
|  GND  |-----------------+----------| GND               |
|  GPIO34|----------------+----------| AO                |
|                         |          |                   |
+-------------------------+          +-------------------+
```

Use 3.3V supply only — the ESP32 ADC inputs are not 5V tolerant, and the rain sensor module operates correctly at 3.3V.

**Code**
```cpp
#include <Arduino.h>

const int RAIN_ANALOG_PIN = 34;  // ADC1_CH6, input-only GPIO safe for analog
const int ADC_MAX = 4095;        // ESP32 ADC is 12-bit

void setup() {
  Serial.begin(115200);
  // GPIO34 is input-only, no pinMode needed, but explicit doesn't hurt
  pinMode(RAIN_ANALOG_PIN, INPUT);
  Serial.println("Rain Sensor Analog Reader Ready");
}

void loop() {
  int rawValue = analogRead(RAIN_ANALOG_PIN);

  // Convert raw ADC value to a moisture percentage
  // Dry = high resistance = high voltage = high ADC value
  // Wet = low resistance = low voltage  = low ADC value
  int moisturePercent = map(rawValue, ADC_MAX, 0, 0, 100);
  moisturePercent = constrain(moisturePercent, 0, 100);

  float voltage = (rawValue / (float)ADC_MAX) * 3.3f;

  Serial.print("Raw ADC: ");
  Serial.print(rawValue);
  Serial.print("  |  Voltage: ");
  Serial.print(voltage, 2);
  Serial.print(" V  |  Moisture: ");
  Serial.print(moisturePercent);
  Serial.println("%");

  if (moisturePercent > 60) {
    Serial.println("  >> Rain detected!");
  } else {
    Serial.println("  >> Surface dry.");
  }

  delay(1000);
}
```

**How it works:** The `map()` call inverts the ADC range because the rain sensor's analog output voltage *decreases* as moisture increases (lower resistance path to GND), so a raw value near 4095 means dry and near 0 means fully wet. GPIO34 is chosen because it belongs to ADC1, which works reliably alongside Wi-Fi — ADC2 pins are unavailable when Wi-Fi is active on the ESP32.

