```

The HX711 and ESP32 both operate at 3.3V logic, so no level shifting is required.

**Code**
```cpp
#include <Arduino.h>

// HX711 pin definitions
const int DOUT_PIN = 21;  // Data output from HX711
const int SCK_PIN  = 22;  // Clock input to HX711

// Calibration: adjust this value after calibrating with a known weight
float calibration_factor = 2280.0f;

// Read raw 24-bit signed value from HX711
long hx711_read() {
  // Wait for HX711 to be ready (DOUT goes LOW)
  while (digitalRead(DOUT_PIN) == HIGH) {
    delay(1);
  }

  long value = 0;
  // Shift in 24 bits, MSB first
  for (int i = 0; i < 24; i++) {
    digitalWrite(SCK_PIN, HIGH);
    delayMicroseconds(1);
    value = (value << 1) | digitalRead(DOUT_PIN);
    digitalWrite(SCK_PIN, LOW);
    delayMicroseconds(1);
  }

  // 25th pulse sets gain=128, channel A for next reading
  digitalWrite(SCK_PIN, HIGH);
  delayMicroseconds(1);
  digitalWrite(SCK_PIN, LOW);
  delayMicroseconds(1);

  // Sign-extend from 24-bit to 32-bit
  if (value & 0x800000) {
    value |= 0xFF000000;
  }

  return value;
}

long tare_offset = 0;

void setup() {
  Serial.begin(115200);
  pinMode(DOUT_PIN, INPUT);
  pinMode(SCK_PIN, OUTPUT);
  digitalWrite(SCK_PIN, LOW);

  Serial.println("HX711 Load Cell Demo");
  Serial.println("Taring in 3 seconds — keep scale empty...");
  delay(3000);

  // Average 10 readings for tare
  long sum = 0;
  for (int i = 0; i < 10; i++) {
    sum += hx711_read();
    delay(100);
  }
  tare_offset = sum / 10;
  Serial.print("Tare offset: ");
  Serial.println(tare_offset);
  Serial.println("Place your load now.");
}

void loop() {
  long raw = hx711_read();
  long net = raw - tare_offset;
  float weight_kg = (float)net / calibration_factor;

  Serial.print("Raw: ");
  Serial.print(raw);
  Serial.print("  Net: ");
  Serial.print(net);
  Serial.print("  Weight: ");
  Serial.print(weight_kg, 3);
  Serial.println(" kg");

  delay(500);
}
```

**How it works:** The 25th clock pulse after reading 24 data bits is critical — it tells the HX711 to use Channel A with 128x gain for the *next* conversion, so omitting it would desynchronize all subsequent reads. The `calibration_factor` must be determined empirically by placing a known weight and dividing the net raw count by the known mass in kg.

The YF-S201 outputs a digital pulse train whose frequency is proportional to flow rate, so a single interrupt-capable GPIO is all that's needed — no special bus or level shifting required since the sensor's open-collector output is compatible with 3.3V logic when pulled up.

**Wiring Table**

| Component Pin | Connects to ESP32 |
|---|---|
| VCC (Red) | 5V |
| GND (Black) | GND |
| Signal (Yellow) | GPIO 18 (with 10kΩ pull-up to 3.3V) |

**Wiring Diagram**
```
        +------------------+          +-------------------+
        |      ESP32       |          |   YF-S201 Sensor  |
        |                  |          |                   |
        |           5V o---+----------+---o VCC (Red)     |
        |          GND o---+----------+---o GND (Black)   |
        |                  |          |                   |
        |        GPIO18 o--+----+-----+---o Signal (Yel.) |
        |                  |    |     |                   |
        |          3.3V o--+--[10kΩ]  +-------------------+
        |                  |    |                          
        +------------------+    | (pull-up resistor)       
```

The signal wire is pulled up to 3.3V (not 5V) via a 10kΩ resistor so the ESP32 GPIO never sees more than 3.3V on its input, even though the sensor itself runs on 5V.

**Code**
```cpp
#include <Arduino.h>

#define FLOW_SENSOR_PIN 18
#define CALIBRATION_FACTOR 7.5f  // Hz per L/min per YF-S201 datasheet

volatile uint32_t pulseCount = 0;
uint32_t lastMillis = 0;
float flowRate = 0.0f;
float totalLiters = 0.0f;

void IRAM_ATTR onPulse() {
  pulseCount++;
}

void setup() {
  Serial.begin(115200);
  pinMode(FLOW_SENSOR_PIN, INPUT_PULLUP);
  attachInterrupt(digitalPinToInterrupt(FLOW_SENSOR_PIN), onPulse, RISING);
  lastMillis = millis();
  Serial.println("YF-S201 Water Flow Sensor Ready");
}

void loop() {
  uint32_t currentMillis = millis();

  if (currentMillis - lastMillis >= 1000) {
    // Disable interrupt briefly to safely read shared variable
    detachInterrupt(digitalPinToInterrupt(FLOW_SENSOR_PIN));
    uint32_t count = pulseCount;
    pulseCount = 0;
    attachInterrupt(digitalPinToInterrupt(FLOW_SENSOR_PIN), onPulse, RISING);

    // Frequency in Hz = pulses per second (1-second window)
    float frequency = (float)count;

    // Flow rate in L/min
    flowRate = frequency / CALIBRATION_FACTOR;

    // Accumulate total volume (L/min / 60 = L/s, * 1s interval)
    totalLiters += flowRate / 60.0f;

    Serial.print("Flow Rate: ");
    Serial.print(flowRate, 2);
    Serial.print(" L/min  |  Total Volume: ");
    Serial.print(totalLiters, 3);
    Serial.println(" L");

    lastMillis = currentMillis;
  }
}
```

**How it works:** The ISR marked `IRAM_ATTR` (placing it in fast IRAM) increments a volatile counter on every rising edge, and once per second the main loop briefly detaches the interrupt to safely snapshot and reset that counter — converting the pulse frequency directly to L/min using the YF-S201's datasheet calibration factor of 7.5 pulses-per-second per litre-per-minute.

The MQ-2 outputs a varying analog voltage proportional to gas concentration, so it is routed to one of the ESP32's ADC-capable pins (GPIO34 is input-only and ADC1, making it a clean choice that avoids ADC2 conflicts with Wi-Fi).

