The MQ-2 heater draws up to 150 mA at 5V, so power it from the ESP32's Vin (connected to USB 5V) rather than the 3.3V rail to avoid overloading the onboard regulator.

**Code**
```cpp
#include <Arduino.h>

const int MQ2_ANALOG_PIN = 34;   // ADC1 channel, input-only GPIO
const int ADC_RESOLUTION  = 4095; // ESP32 ADC is 12-bit
const float VCC           = 3.3f; // ADC reference voltage

// Approximate threshold in raw ADC counts (~1.0 V) to flag elevated gas level
const int GAS_THRESHOLD = 1241;

void setup() {
  Serial.begin(115200);
  analogReadResolution(12); // explicitly set 12-bit resolution
  Serial.println("MQ-2 Gas Sensor Ready");
  Serial.println("Warming up sensor -- please wait 30 seconds...");
  delay(30000); // MQ-2 requires ~30 s preheat for stable readings
}

void loop() {
  int   rawValue  = analogRead(MQ2_ANALOG_PIN);
  float voltage   = (rawValue / (float)ADC_RESOLUTION) * VCC;
  float gasPercent = (rawValue / (float)ADC_RESOLUTION) * 100.0f;

  Serial.print("Raw ADC: ");
  Serial.print(rawValue);
  Serial.print("  |  Voltage: ");
  Serial.print(voltage, 3);
  Serial.print(" V  |  Approx. level: ");
  Serial.print(gasPercent, 1);
  Serial.print("%");

  if (rawValue > GAS_THRESHOLD) {
    Serial.print("  [WARNING: Elevated gas/smoke detected!]");
  }

  Serial.println();
  delay(1000);
}
```

**How it works:** `analogReadResolution(12)` ensures the ESP32 returns the full 0–4095 range instead of the Arduino-default 10-bit range, giving finer resolution on the gas concentration reading. The 30-second `delay` in `setup()` is critical — the MQ-2's internal heater coil must reach operating temperature before its electrochemical sensor produces meaningful output, so skipping it yields unreliable near-zero readings regardless of gas present.

