The flame sensor module operates at 3.3V and is safe to connect directly to ESP32 GPIO pins without a level shifter.

**Code**
```cpp
#include <Arduino.h>

const int FLAME_PIN = 25;     // Digital output from flame sensor
const int LED_PIN   = 2;      // Onboard LED as visual alert
const int BUZZER_PIN = 26;    // Optional buzzer for audible alert

void setup() {
  Serial.begin(115200);
  pinMode(FLAME_PIN, INPUT_PULLUP); // Module pulls DO LOW on detection
  pinMode(LED_PIN, OUTPUT);
  pinMode(BUZZER_PIN, OUTPUT);
  digitalWrite(LED_PIN, LOW);
  digitalWrite(BUZZER_PIN, LOW);
  Serial.println("Flame detection system ready.");
}

void loop() {
  int flameState = digitalRead(FLAME_PIN);

  // DO goes LOW when flame is detected
  if (flameState == LOW) {
    Serial.println("WARNING: Flame detected!");
    digitalWrite(LED_PIN, HIGH);
    digitalWrite(BUZZER_PIN, HIGH);
  } else {
    Serial.println("No flame detected.");
    digitalWrite(LED_PIN, LOW);
    digitalWrite(BUZZER_PIN, LOW);
  }

  delay(300);
}
```

**How it works:** The key detail is using `INPUT_PULLUP` on GPIO 25 and checking for `LOW` rather than `HIGH` — most flame sensor modules use an open-collector output that actively pulls the line to ground when fire is detected, so the logic is inverted relative to what you might expect.

