GPIO34 and GPIO35 are input-only pins on the ESP32 with no internal pull-up, making them ideal for clean analog reads; GPIO32 is configured with an internal pull-up so the button reads HIGH at rest and LOW when pressed.

**Code**
```cpp
#include <Arduino.h>

const int PIN_VRX = 34;  // X-axis analog input
const int PIN_VRY = 35;  // Y-axis analog input
const int PIN_SW  = 32;  // Joystick push-button

const int ADC_MAX = 4095;        // 12-bit ADC
const int CENTER  = ADC_MAX / 2; // ~2048, resting center value

void setup() {
  Serial.begin(115200);

  // GPIO34 and GPIO35 are input-only; no pinMode needed for analog reads,
  // but setting them explicitly documents intent.
  pinMode(PIN_VRX, INPUT);
  pinMode(PIN_VRY, INPUT);

  // Button: INPUT_PULLUP so it reads HIGH when not pressed, LOW when pressed.
  pinMode(PIN_SW, INPUT_PULLUP);

  // Use 12-bit ADC resolution (default on ESP32, but set explicitly).
  analogReadResolution(12);

  Serial.println("Analog Joystick Ready");
}

void loop() {
  int xRaw = analogRead(PIN_VRX);
  int yRaw = analogRead(PIN_VRY);
  bool buttonPressed = (digitalRead(PIN_SW) == LOW); // active-low

  // Map raw ADC values to -512..+511 range centered at 0.
  int xVal = xRaw - CENTER;
  int yVal = yRaw - CENTER;

  Serial.print("X: ");
  Serial.print(xVal);
  Serial.print("  Y: ");
  Serial.print(yVal);
  Serial.print("  Button: ");
  Serial.println(buttonPressed ? "PRESSED" : "released");

  delay(100);
}
```

**How it works:** The raw 12-bit ADC values (0–4095) are shifted by subtracting the midpoint (2048) so that the joystick center reads near zero and deflection in each direction produces a positive or negative value. The button is read as active-low because `INPUT_PULLUP` holds the pin HIGH until the switch shorts it to GND.

