```

The I2C backpack typically operates at 5V for the LCD contrast, though the I2C signal lines at 3.3V from the ESP32 are generally sufficient to drive the backpack's logic; no level shifting is usually needed in practice.

**Code**
```cpp
#include <Wire.h>
#include <LiquidCrystal_I2C.h>

// Common I2C address for LCD backpacks is 0x27 (some use 0x3F)
// Set the LCD address, columns, and rows
LiquidCrystal_I2C lcd(0x27, 16, 2);

void setup() {
  // Initialize the LCD
  lcd.init();

  // Turn on the backlight
  lcd.backlight();

  // Print to the first row
  lcd.setCursor(0, 0);
  lcd.print("Hello, ESP32!");

  // Print to the second row
  lcd.setCursor(0, 1);
  lcd.print("LCD I2C Ready");
}

void loop() {
  // Nothing needed here for static text
}
```

**How it works:** The `LiquidCrystal_I2C` library handles all the bit-banging over I2C to the PCF8574 I/O expander chip on the backpack, which then drives the LCD's parallel interface internally — so you only need `lcd.init()` and `lcd.print()` rather than managing the parallel bus yourself. If the display shows garbled characters or nothing at all, run an I2C scanner sketch to confirm the backpack's actual address (0x27 vs 0x3F are the two most common variants).

Both sensors operate at 3.3V and support I2C, so they share the same SDA/SCL lines with the ESP32's hardware I2C peripheral — they are distinguished by their different default addresses (BME280 at 0x76, MPU6050 at 0x68).

**Wiring Table**

| Component Pin | Connects to ESP32 |
|---|---|
| BME280 VCC | 3.3V |
| BME280 GND | GND |
| BME280 SDA | GPIO 21 |
| BME280 SCL | GPIO 22 |
| MPU6050 VCC | 3.3V |
| MPU6050 GND | GND |
| MPU6050 SDA | GPIO 21 |
| MPU6050 SCL | GPIO 22 |
| MPU6050 AD0 | GND (sets I2C address to 0x68) |

**Wiring Diagram**
```
        +--------------------+
        |       ESP32        |
        |                   |
        |  3.3V |--------+--+----> BME280 VCC
        |                |  |----> MPU6050 VCC
        |   GND |--------+--+----> BME280 GND
        |                |  |----> MPU6050 GND
        |                |  |----> MPU6050 AD0
        |                   |
        | GPIO21 (SDA) |----+----> BME280 SDA
        |                   |----> MPU6050 SDA
        |                   |
        | GPIO22 (SCL) |----+----> BME280 SCL
        |                   |----> MPU6050 SCL
        +--------------------+
```
Both SDA and SCL lines should have 4.7kΩ pull-up resistors to 3.3V if your modules do not already include them on-board.

**Code**
```cpp
#include <Wire.h>
#include <Adafruit_BME280.h>
#include <Adafruit_MPU6050.h>
#include <Adafruit_Sensor.h>

#define SDA_PIN 21
#define SCL_PIN 22

#define BME280_I2C_ADDR 0x76
#define MPU6050_I2C_ADDR 0x68

Adafruit_BME280 bme;
Adafruit_MPU6050 mpu;

void setup() {
  Serial.begin(115200);
  Wire.begin(SDA_PIN, SCL_PIN);

  // Initialize BME280
  if (!bme.begin(BME280_I2C_ADDR, &Wire)) {
    Serial.println("BME280 not found! Check wiring and I2C address.");
    while (1);
  }
  Serial.println("BME280 initialized.");

  // Initialize MPU6050
  if (!mpu.begin(MPU6050_I2C_ADDR, &Wire)) {
    Serial.println("MPU6050 not found! Check wiring and AD0 pin.");
    while (1);
  }
  mpu.setAccelerometerRange(MPU6050_RANGE_4_G);
  mpu.setGyroRange(MPU6050_RANGE_500_DEG);
  mpu.setFilterBandwidth(MPU6050_BAND_21_HZ);
  Serial.println("MPU6050 initialized.");
}

void loop() {
  // --- BME280 readings ---
  float temperature = bme.readTemperature();      // Celsius
  float humidity    = bme.readHumidity();          // %RH
  float pressure    = bme.readPressure() / 100.0F; // hPa

  Serial.println("=== BME280 ===");
  Serial.printf("  Temperature: %.2f C\n", temperature);
  Serial.printf("  Humidity:    %.2f %%\n", humidity);
  Serial.printf("  Pressure:    %.2f hPa\n", pressure);

  // --- MPU6050 readings ---
  sensors_event_t accel, gyro, temp;
  mpu.getEvent(&accel, &gyro, &temp);

  Serial.println("=== MPU6050 ===");
  Serial.printf("  Accel X: %.3f  Y: %.3f  Z: %.3f m/s^2\n",
    accel.acceleration.x, accel.acceleration.y, accel.acceleration.z);
  Serial.printf("  Gyro  X: %.3f  Y: %.3f  Z: %.3f rad/s\n",
    gyro.gyro.x, gyro.gyro.y, gyro.gyro.z);
  Serial.printf("  Temp (MPU): %.2f C\n", temp.temperature);

  Serial.println();
  delay(1000);
}
```

**How it works:** Both `bme.begin()` and `mpu.begin()` accept the same `&Wire` reference, which is how both sensors share a single I2C bus — the library manages addressing automatically using each device's distinct 7-bit address. Tying MPU6050's AD0 pin to GND is critical: it fixes the MPU6050 address at 0x68, preventing a collision with the BME280 at 0x76.

The ACS712 outputs a ratiometric analog voltage centered at VCC/2, so it's wired to one of the ESP32's ADC-capable GPIO pins for direct analog reading.

**Wiring Table**

| Component Pin | Connects to ESP32 |
|---|---|
| VCC | 5V (or 3.3V, match to module version) |
| GND | GND |
| OUT | GPIO34 (ADC1_CH6) |

**Wiring Diagram**
```
+----------------+          +-------------------+
|   ACS712       |          |       ESP32        |
|                |          |                    |
|  VCC  o--------+----------o 5V                 |
|  GND  o--------+----------o GND                |
|  OUT  o-------------------o GPIO34 (ADC1_CH6)  |
+----------------+          +-------------------+
```
The ACS712 OUT pin must not exceed 3.3V into the ESP32 ADC; if powering the module from 5V, add a voltage divider (e.g. 10kΩ + 20kΩ) on the OUT line to scale it down to ≤3.3V before connecting to GPIO34.

**Code**
```cpp
#include <Arduino.h>

// ACS712 wired to GPIO34 (ADC1 channel, input-only pin)
const int ACS_PIN = 34;

// ACS712-05B sensitivity: 185 mV/A
// ACS712-20A sensitivity: 100 mV/A
// ACS712-30A sensitivity: 66  mV/A
const float SENSITIVITY_MV_PER_A = 185.0f; // Change for your module variant

// ESP32 ADC: 12-bit (0-4095) over 0-3.3V
const float ADC_VOLTAGE_REF = 3.3f;
const int   ADC_RESOLUTION   = 4096;

// Midpoint voltage (sensor output with zero current)
// If VCC=5V, scaled to 3.3V by divider: 2.5V * (3.3/5.0) = 1.65V
// If VCC=3.3V directly: 1.65V
const float ZERO_CURRENT_VOLTAGE = 1.65f;

void setup() {
  Serial.begin(115200);
  analogReadResolution(12); // Ensure 12-bit ADC resolution
  pinMode(ACS_PIN, INPUT);
  Serial.println("ACS712 Current Sensor Ready");
}

float readCurrentAmps() {
  // Average multiple samples to reduce ADC noise
  const int NUM_SAMPLES = 100;
  long sum = 0;
  for (int i = 0; i < NUM_SAMPLES; i++) {
    sum += analogRead(ACS_PIN);
    delayMicroseconds(100);
  }
  float avgRaw = (float)sum / NUM_SAMPLES;

  // Convert raw ADC value to voltage
  float voltage = (avgRaw / ADC_RESOLUTION) * ADC_VOLTAGE_REF;

  // Calculate current from voltage offset from zero-current midpoint
  float current = (voltage - ZERO_CURRENT_VOLTAGE) / (SENSITIVITY_MV_PER_A / 1000.0f);
  return current;
}

void loop() {
  float current = readCurrentAmps();
  Serial.print("Current: ");
  Serial.print(current, 3);
  Serial.println(" A");
  delay(500);
}
```

**How it works:** Averaging 100 ADC samples before converting to voltage significantly reduces the ESP32's inherent ADC noise, which is critical for accurate current readings near zero. The zero-current offset subtraction is essential because the ACS712 outputs VCC/2 (not 0V) when no current flows, so any deviation from that midpoint voltage — divided by the sensitivity — gives the actual signed current in amps.

The rain sensor module outputs an analog voltage that varies with water coverage on the sensing pad, so it's wired to one of the ESP32's ADC-capable pins (avoid ADC2 pins if Wi-Fi is in use).

**Wiring Table**

| Component Pin | Connects to ESP32 |
|---|---|
| VCC | 3.3V |
| GND | GND |
| AO (Analog Out) | GPIO34 (ADC1_CH6) |
| DO (Digital Out) | not connected (optional: any free GPIO) |

**Wiring Diagram**
```
        +------------------+         +-------------------+
        |   Rain Sensor    |         |       ESP32       |
        |                  |         |                   |
        |  VCC  o----------+---------o 3.3V              |
        |  GND  o----------+---------o GND               |
        |  AO   o----------+---------o GPIO34 (ADC1_CH6) |
        |  DO   o  (n/c)             |                   |
        +------------------+         +-------------------+
```
The rain sensor module typically runs on 3.3V–5V; powering it from 3.3V keeps the analog output safely within the ESP32 ADC's 0–3.3V input range.

**Code**
```cpp
#include <Arduino.h>

const int RAIN_ANALOG_PIN = 34;   // ADC1_CH6, input-only GPIO safe for ADC
const int ADC_RESOLUTION   = 4095; // ESP32 ADC is 12-bit (0–4095)
const int DRY_THRESHOLD    = 3000; // values above this indicate dry conditions

void setup() {
  Serial.begin(115200);
  // GPIO34 is input-only; no pinMode call required, but explicit is fine
  pinMode(RAIN_ANALOG_PIN, INPUT);
  analogReadResolution(12); // ensure 12-bit resolution (default on ESP32)
  Serial.println("Rain Sensor Monitor Started");
}

void loop() {
  int rawValue = analogRead(RAIN_ANALOG_PIN);

  // Lower raw value = more water (more conductance = lower resistance = lower voltage)
  float voltage = (rawValue / (float)ADC_RESOLUTION) * 3.3f;
  int rainPercent = map(rawValue, 0, ADC_RESOLUTION, 100, 0);

  Serial.print("Raw ADC: ");
  Serial.print(rawValue);
  Serial.print("  Voltage: ");
  Serial.print(voltage, 2);
  Serial.print(" V  Rain intensity: ");
  Serial.print(rainPercent);
  Serial.print("%  Status: ");

  if (rawValue > DRY_THRESHOLD) {
    Serial.println("DRY");
  } else if (rawValue > 1500) {
    Serial.println("LIGHT RAIN");
  } else {
    Serial.println("HEAVY RAIN");
  }

  delay(1000);
}
```

**How it works:** The rain sensor's resistive pad lowers its output voltage as water bridges the traces, so a *lower* ADC reading corresponds to *more* rain — the `map(rawValue, 0, ADC_RESOLUTION, 100, 0)` call inverts the range to produce an intuitive 0–100% intensity value. GPIO34 is chosen because it belongs to ADC1, which remains functional even when Wi-Fi is active, unlike ADC2 pins.

The TTP223 outputs a simple HIGH/LOW digital signal on its I/O pin, so no special protocol library is needed — just a standard GPIO input read.

**Wiring Table**

| Component Pin | Connects to ESP32 |
|---|---|
| VCC | 3.3V |
| GND | GND |
| I/O (SIG) | GPIO4 |

**Wiring Diagram**
```
+----------------+          +----------------------+
|   TTP223       |          |        ESP32         |
|                |          |                      |
|  VCC  o--------+----------+ 3.3V                 |
|  GND  o--------+----------+ GND                  |
|  I/O  o--------+----------+ GPIO4                |
+----------------+          +----------------------+
```
The TTP223 runs on 3.3V and its output is 3.3V-logic compatible, so no level shifting is required when powering from the ESP32's 3.3V rail.

**Code**
```cpp
#include <Arduino.h>

const int TOUCH_PIN = 4;   // TTP223 I/O connected to GPIO4
bool lastState = LOW;

void setup() {
  Serial.begin(115200);
  pinMode(TOUCH_PIN, INPUT);  // TTP223 drives the line actively; no pull-up needed
  Serial.println("TTP223 Capacitive Touch Ready");
}

void loop() {
  bool currentState = digitalRead(TOUCH_PIN);

  if (currentState != lastState) {
    if (currentState == HIGH) {
      Serial.println("Touch detected!");
    } else {
      Serial.println("Touch released.");
    }
    lastState = currentState;
  }

  delay(20);  // small debounce delay
}
```

**How it works:** The TTP223 actively drives its I/O pin HIGH when a touch is detected and LOW otherwise, so `pinMode(TOUCH_PIN, INPUT)` (without `INPUT_PULLUP`) is used since the sensor itself provides a clean driven signal. Edge detection by comparing `currentState` to `lastState` ensures the serial message prints only once per touch/release transition rather than flooding the output every loop iteration.

A small vibration motor draws more current than the ESP32 GPIO can safely supply, so an NPN transistor (e.g. 2N2222 or PN2222) is used as a low-side switch between the GPIO and the motor, with a flyback diode across the motor to suppress inductive spikes.

**Wiring Table**

| Component Pin | Connects to ESP32 |
|---|---|
| Motor (+) | 5V (or 3.3V) |
| Motor (–) | Transistor Collector |
| Transistor Emitter | GND |
| Transistor Base | 330Ω resistor → GPIO 18 |
| Flyback diode anode | Motor (–) / Collector |
| Flyback diode cathode | Motor (+) / 5V |

**Wiring Diagram**
```
        +5V
         │
         ├──[cathode]──┐
         │            [1N4148]
    [Vib Motor]        │
         │        [anode]──┤
         └──────────────────── Collector
                              [2N2222 NPN]
                              Base ──[330Ω]──── GPIO18
                              Emitter ──────── GND

 ┌─────────────┐
 │    ESP32    │
 │             │
 │      GPIO18 ├──────[330Ω]──── Base
 │         GND ├──────────────── Emitter / GND rail
 │          5V ├──────────────── Motor(+) / Diode cathode
 └─────────────┘
```
Always place a flyback (freewheeling) diode in reverse-parallel across the motor terminals to protect the transistor from back-EMF when the motor is switched off.

**Code**
```cpp
#include <Arduino.h>

const int MOTOR_PIN = 18;  // GPIO driving the transistor base via 330Ω

void setup() {
  pinMode(MOTOR_PIN, OUTPUT);
  digitalWrite(MOTOR_PIN, LOW);  // ensure motor is off at startup
  Serial.begin(115200);
}

void loop() {
  // Buzz on for 500 ms
  Serial.println("Motor ON");
  digitalWrite(MOTOR_PIN, HIGH);
  delay(500);

  // Buzz off for 1000 ms
  Serial.println("Motor OFF");
  digitalWrite(MOTOR_PIN, LOW);
  delay(1000);

  // PWM-style pulsing: rapid on/off for a weaker buzz effect
  Serial.println("Pulsing...");
  for (int i = 0; i < 20; i++) {
    digitalWrite(MOTOR_PIN, HIGH);
    delay(30);
    digitalWrite(MOTOR_PIN, LOW);
    delay(30);
  }
  delay(1000);
}
```

**How it works:** Setting GPIO 18 HIGH saturates the NPN transistor, pulling the motor's negative terminal to near-GND and completing the circuit so current flows through the motor; setting it LOW cuts the transistor off and stops the motor. The rapid on/off loop in the pulsing section mimics PWM to reduce average motor speed without needing the LEDC peripheral.

The PN532 supports multiple interfaces (UART, SPI, I2C) selected via DIP switches or solder jumpers on the module — set both SEL0 and SEL1 to HIGH (or solder the I2C pads) before wiring to the ESP32's default I2C bus.

**Wiring Table**

| Component Pin | Connects to ESP32 |
|---|---|
| VCC | 3.3V |
| GND | GND |
| SDA | GPIO 21 |
| SCL | GPIO 22 |
| IRQ | GPIO 4 |
| RSTO | GPIO 5 |

**Wiring Diagram**
```
+----------------+          +-------------------+
|     ESP32      |          |   PN532 NFC Module |
|                |          |                   |
|   3.3V (3V3) o-+----------+o VCC              |
|          GND o-+----------+o GND              |
|    SDA (G21) o-+----------+o SDA              |
|    SCL (G22) o-+----------+o SCL              |
|         G4   o-+----------+o IRQ              |
|         G5   o-+----------+o RSTO             |
+----------------+          +-------------------+
```
The PN532 operates at 3.3V only on most breakout boards — double-check your module's silkscreen before powering, as applying 5V may damage it.

**Code**
```cpp
#include <Wire.h>
#include <Adafruit_PN532.h>

// IRQ and RESET pins for I2C mode
#define PN532_IRQ   4
#define PN532_RESET 5

// Instantiate with IRQ and RESET for I2C
Adafruit_PN532 nfc(PN532_IRQ, PN532_RESET);

void setup() {
  Serial.begin(115200);
  Serial.println("PN532 NFC Reader - I2C Mode");

  Wire.begin(21, 22); // SDA=21, SCL=22
  nfc.begin();

  uint32_t versiondata = nfc.getFirmwareVersion();
  if (!versiondata) {
    Serial.println("Didn't find PN532 board. Check wiring and I2C mode selection.");
    while (1); // halt
  }

  Serial.print("Found PN532 chip, firmware version: ");
  Serial.print((versiondata >> 16) & 0xFF, DEC);
  Serial.print('.');
  Serial.println((versiondata >> 8) & 0xFF, DEC);

  // Configure to read MiFare cards
  nfc.SAMConfig();
  Serial.println("Waiting for an NFC tag...");
}

void loop() {
  uint8_t uid[7];       // UID buffer (up to 7 bytes for MiFare)
  uint8_t uidLength;    // Actual UID length returned

  // Wait up to 1 second for a card, non-blocking via IRQ
  bool success = nfc.readPassiveTargetID(PN532_MIFARE_ISO14443A, uid, &uidLength, 1000);

  if (success) {
    Serial.print("NFC Tag detected! UID: ");
    for (uint8_t i = 0; i < uidLength; i++) {
      if (uid[i] < 0x10) Serial.print("0"); // leading zero
      Serial.print(uid[i], HEX);
      if (i < uidLength - 1) Serial.print(":");
    }
    Serial.println();
    Serial.print("UID Length: ");
    Serial.print(uidLength);
    Serial.println(" bytes");
    delay(1000); // debounce: wait before scanning again
  }
}
```

**How it works:** The `Adafruit_PN532` constructor's two-argument form (IRQ, RESET) automatically selects I2C mode, using the IRQ pin for interrupt-driven card detection rather than polling — this is why `readPassiveTargetID` with a timeout is efficient rather than busy-waiting. Calling `SAMConfig()` in setup puts the PN532's Secure Access Module into normal mode, which is required before any tag reading operations will succeed.

The ESP32's LEDC peripheral generates PWM on any GPIO, so both servo signals are routed to dedicated output-capable pins while sharing a common ground to avoid noise-induced jitter.

**Wiring Table**

| Component Pin | Connects to ESP32 |
|---|---|
| Pan Servo – Signal (orange) | GPIO 18 |
| Pan Servo – VCC (red) | 5V (VIN or external 5V) |
| Pan Servo – GND (brown) | GND |
| Tilt Servo – Signal (orange) | GPIO 19 |
| Tilt Servo – VCC (red) | 5V (VIN or external 5V) |
| Tilt Servo – GND (brown) | GND |

**Wiring Diagram**
```
+-------------------------+          +------------------+
|          ESP32          |          |   Pan SG90 Servo |
|                         |          |                  |
|  GPIO18 (PWM) ----------|----------| Signal (orange)  |
|  5V/VIN  ---------------|-+--------| VCC    (red)     |
|  GND     ---------------|-+--+-----| GND    (brown)   |
|                         |    |     +------------------+
|                         |    |
|                         |    |     +------------------+
|  GPIO19 (PWM) ----------|----+-----| Signal (orange)  |
|                         |    +-----| VCC    (red)     |
|                         |    +-----| GND    (brown)   |
+-------------------------+          | Tilt SG90 Servo  |
                                     +------------------+
```
Power the servos from an external 5 V supply sharing a common GND with the ESP32 if both servos are under mechanical load — drawing stall current through the ESP32's onboard regulator can cause brownouts.

**Code**
```cpp
#include <Arduino.h>

// LEDC channel assignments
#define PAN_CHANNEL   0
#define TILT_CHANNEL  1

// GPIO pins
#define PAN_PIN   18
#define TILT_PIN  19

// PWM parameters for SG90
#define PWM_FREQ      50        // 50 Hz = 20 ms period
#define PWM_RESOLUTION 16       // 16-bit resolution (0-65535)

// SG90 pulse widths in microseconds
// 0 deg = ~544 us, 180 deg = ~2400 us
#define SERVO_MIN_US  544
#define SERVO_MAX_US  2400

// Convert microseconds to 16-bit duty count for 50 Hz
uint32_t usToDuty(uint32_t us) {
  // Period = 1,000,000 us / 50 = 20,000 us
  return (uint32_t)((us * 65535UL) / 20000UL);
}

// Write an angle (0-180) to a given LEDC channel
void setServoAngle(uint8_t channel, int angle) {
  angle = constrain(angle, 0, 180);
  uint32_t pulseUs = map(angle, 0, 180, SERVO_MIN_US, SERVO_MAX_US);
  ledcWrite(channel, usToDuty(pulseUs));
}

void setup() {
  Serial.begin(115200);

  // Configure LEDC channels
  ledcSetup(PAN_CHANNEL,  PWM_FREQ, PWM_RESOLUTION);
  ledcSetup(TILT_CHANNEL, PWM_FREQ, PWM_RESOLUTION);

  // Attach pins to channels
  ledcAttachPin(PAN_PIN,  PAN_CHANNEL);
  ledcAttachPin(TILT_PIN, TILT_CHANNEL);

  // Centre both servos on startup
  setServoAngle(PAN_CHANNEL,  90);
  setServoAngle(TILT_CHANNEL, 90);
  delay(500);
}

void loop() {
  // Sweep pan 0->180, tilt 180->0 simultaneously
  for (int angle = 0; angle <= 180; angle++) {
    setServoAngle(PAN_CHANNEL,  angle);
    setServoAngle(TILT_CHANNEL, 180 - angle);
    delay(12);
  }

  // Sweep back
  for (int angle = 180; angle >= 0; angle--) {
    setServoAngle(PAN_CHANNEL,  angle);
    setServoAngle(TILT_CHANNEL, 180 - angle);
    delay(12);
  }
}
```

**How it works:** The `usToDuty()` function scales the SG90's microsecond pulse width into a 16-bit LEDC count proportional to the 20 ms (50 Hz) period, giving finer resolution than the 8-bit Arduino `Servo` library. Using two separate LEDC channels on independent timers means pan and tilt PWM signals are generated in hardware simultaneously without any CPU timing dependency.

The L298N uses two digital direction pins plus a PWM-capable enable pin per motor channel, so we assign IN1/IN2 to plain GPIOs and ENA to a PWM-capable GPIO on the ESP32.

**Wiring Table**

| Component Pin | Connects to ESP32 |
|---|---|
| ENA | GPIO 14 (PWM) |
| IN1 | GPIO 27 |
| IN2 | GPIO 26 |
| GND | GND |
| +5V (logic) | 5V (VIN) |
| OUT1 | DC Motor terminal A |
| OUT2 | DC Motor terminal B |
| 12V | External 12V supply (+) |
| GND (power) | External 12V supply (−) & ESP32 GND |

**Wiring Diagram**
```
        +---------------------+
        |        ESP32        |
        |                     |
        |  GPIO14 (PWM) ------+-----------> ENA
        |  GPIO27       ------+-----------> IN1
        |  GPIO26       ------+-----------> IN2
        |  5V (VIN)     ------+-----------> +5V (logic)
        |  GND          ------+----+------> GND (logic)
        +---------------------+   |
                                   |
   +12V Supply(+) -----------------> 12V
   +12V Supply(-) ------------+----> GND (power)
                              |
                             GND (common)

        +---------------------+
        |       L298N         |
        |  OUT1 ---------------------> DC Motor (+)
        |  OUT2 ---------------------> DC Motor (−)
        +---------------------+
```
Make sure all GND rails (ESP32, L298N logic, and external power supply) share a common ground, and never feed the motor's 12V supply into the ESP32.

**Code**
```cpp
#include <Arduino.h>

// Pin definitions
const int ENA_PIN = 14;  // PWM enable for motor channel A
const int IN1_PIN = 27;  // Direction control 1
const int IN2_PIN = 26;  // Direction control 2

// PWM configuration (ESP32 LEDC)
const int PWM_CHANNEL  = 0;
const int PWM_FREQ     = 1000;   // 1 kHz
const int PWM_RES_BITS = 8;      // 8-bit resolution (0-255)

void motorForward(uint8_t speed) {
  digitalWrite(IN1_PIN, HIGH);
  digitalWrite(IN2_PIN, LOW);
  ledcWrite(PWM_CHANNEL, speed);
}

void motorBackward(uint8_t speed) {
  digitalWrite(IN1_PIN, LOW);
  digitalWrite(IN2_PIN, HIGH);
  ledcWrite(PWM_CHANNEL, speed);
}

void motorStop() {
  digitalWrite(IN1_PIN, LOW);
  digitalWrite(IN2_PIN, LOW);
  ledcWrite(PWM_CHANNEL, 0);
}

void setup() {
  Serial.begin(115200);

  pinMode(IN1_PIN, OUTPUT);
  pinMode(IN2_PIN, OUTPUT);

  // Attach LEDC PWM to ENA pin
  ledcSetup(PWM_CHANNEL, PWM_FREQ, PWM_RES_BITS);
  ledcAttachPin(ENA_PIN, PWM_CHANNEL);

  motorStop();  // Ensure motor is idle on boot
}

void loop() {
  Serial.println("Forward at 75% speed...");
  motorForward(191);   // 191/255 ≈ 75%
  delay(3000);

  Serial.println("Stopping...");
  motorStop();
  delay(1000);

  Serial.println("Backward at 50% speed...");
  motorBackward(127);  // 127/255 ≈ 50%
  delay(3000);

  Serial.println("Stopping...");
  motorStop();
  delay(1000);
}
```

**How it works:** The ESP32's LEDC peripheral generates a hardware PWM signal on ENA to control motor speed — writing 0 to 255 maps linearly to 0–100% duty cycle. The IN1/IN2 logic level combination determines direction: HIGH/LOW spins forward while LOW/HIGH reverses it, and both LOW coasts the motor to a stop.

Each HC-SR04 needs its own dedicated TRIG and ECHO GPIO pair since the sensors operate independently over a simple digital pulse protocol with no shared bus.

**Wiring Table**

| Component Pin | Connects to ESP32 |
|---|---|
| Sensor 1 VCC | 5V |
| Sensor 1 GND | GND |
| Sensor 1 TRIG | GPIO 5 |
| Sensor 1 ECHO | GPIO 18 |
| Sensor 2 VCC | 5V |
| Sensor 2 GND | GND |
| Sensor 2 TRIG | GPIO 19 |
| Sensor 2 ECHO | GPIO 21 |

**Wiring Diagram**
```
 +-------------------------+
 | ESP32 |
 | |
 | 5V |---+---------> HC-SR04 #1 VCC
 | GND |---+---------> HC-SR04 #1 GND
 | GPIO5 (TRIG1)|---------> HC-SR04 #1 TRIG
 | GPIO18 (ECHO1)|<--------- HC-SR04 #1 ECHO
 | |
 | 5V |---+---------> HC-SR04 #2 VCC
 | GND |---+---------> HC-SR04 #2 GND
 | GPIO19 (TRIG2)|---------> HC-SR04 #2 TRIG
 | GPIO21 (ECHO2)|<--------- HC-SR04 #2 ECHO
 +-------------------------+
```

The HC-SR04 ECHO pin outputs 5V logic, but ESP32 GPIO is only 3.3V tolerant — consider a voltage divider (1kΩ + 2kΩ) on each ECHO line in production use.

**Code**
```cpp
#define TRIG1 5
#define ECHO1 18
#define TRIG2 19
#define ECHO2 21

long readDistanceCm(int trigPin, int echoPin) {
 digitalWrite(trigPin, LOW);
 delayMicroseconds(2);
 digitalWrite(trigPin, HIGH);
 delayMicroseconds(10);
 digitalWrite(trigPin, LOW);

 long duration = pulseIn(echoPin, HIGH, 30000); // timeout 30ms
 if (duration == 0) return -1; // no echo received
 return duration * 0.034 / 2;
}

void setup() {
 Serial.begin(115200);

 pinMode(TRIG1, OUTPUT);
 pinMode(ECHO1, INPUT);
 pinMode(TRIG2, OUTPUT);
 pinMode(ECHO2, INPUT);
}

void loop() {
 long dist1 = readDistanceCm(TRIG1, ECHO1);
 delay(10); // brief pause between sensors to avoid acoustic crosstalk
 long dist2 = readDistanceCm(TRIG2, ECHO2);

 Serial.print("Sensor 1: ");
 if (dist1 < 0) Serial.println("No echo");
 else { Serial.print(dist1); Serial.println(" cm"); }

 Serial.print("Sensor 2: ");
 if (dist2 < 0) Serial.println("No echo");
 else { Serial.print(dist2); Serial.println(" cm"); }

 Serial.println("---");
 delay(200);
}
```

**How it works:** The `pulseIn()` call measures how long the ECHO pin stays HIGH after the 10µs trigger pulse, and dividing by 2 accounts for the round-trip travel of the sound wave; the 30ms timeout prevents the code from hanging indefinitely if an object is out of range. The small `delay(10)` between firing each sensor reduces the risk of one sensor's ultrasonic burst being picked up by the other sensor's ECHO pin.

The e-paper display uses SPI along with dedicated busy, reset, and data/command control pins, so five GPIOs total are needed beyond the shared SPI bus lines.

**Wiring Table**

| Component Pin | Connects to ESP32 |
|---|---|
| VCC | 3.3V |
| GND | GND |
| SCK | GPIO 18 (SPI SCK) |
| MOSI | GPIO 23 (SPI MOSI) |
| CS | GPIO 5 |
| RST | GPIO 17 |
| DC | GPIO 16 |
| BUSY | GPIO 4 |

**Wiring Diagram**
```
+-------------------+          +-------------------------+
|       ESP32       |          |   2.9" e-Paper Display  |
|                   |          |                         |
|       3.3V  ------+----------+-- VCC                   |
|        GND  ------+----------+-- GND                   |
|  GPIO18/SCK ------+----------+-- SCK                   |
| GPIO23/MOSI ------+----------+-- MOSI                  |
|      GPIO5  ------+----------+-- CS                    |
|     GPIO17  ------+----------+-- RST                   |
|     GPIO16  ------+----------+-- DC                    |
|      GPIO4  ------+----------+-- BUSY                  |
+-------------------+          +-------------------------+
```

Do not connect the display to 5V — the e-paper controller is 3.3V only and will be damaged by higher voltage.

**Code**
```cpp
#include <Arduino.h>
#include <SPI.h>
#include <GxEPD2_BW.h>
#include <Fonts/FreeMonoBold9pt7b.h>

// Pin definitions
#define EPD_CS   5
#define EPD_RST  17
#define EPD_DC   16
#define EPD_BUSY 4

// GxEPD2 driver for common 2.9" 296x128 display (GDEH029A1 / SSD1680)
GxEPD2_BW<GxEPD2_290_T94, GxEPD2_290_T94::HEIGHT> display(
    GxEPD2_290_T94(EPD_CS, EPD_DC, EPD_RST, EPD_BUSY));

void setup() {
    Serial.begin(115200);

    // Initialize SPI with explicit pins (SCK=18, MOSI=23, MISO=19)
    SPI.begin(18, 19, 23, EPD_CS);

    display.init(115200);
    display.setRotation(1);  // Landscape orientation
    display.setFont(&FreeMonoBold9pt7b);
    display.setTextColor(GxEPD_BLACK);

    // Use paged drawing to fit within RAM limits
    display.setFullWindow();
    display.firstPage();
    do {
        display.fillScreen(GxEPD_WHITE);

        display.setCursor(10, 30);
        display.print("Hello, ESP32!");

        display.setCursor(10, 60);
        display.print("e-Paper SPI Demo");

        display.setCursor(10, 90);
        display.print("2.9 inch display");
    } while (display.nextPage());

    Serial.println("Display update complete.");
}

void loop() {
    // e-paper retains image without power; nothing needed in loop
    delay(10000);
}
```

**How it works:** The `do { ... } while (display.nextPage())` paged drawing loop is essential because the 2.9" display's full frame buffer (296×128 pixels) is too large to hold in ESP32 RAM all at once, so GxEPD2 renders it in horizontal strips automatically. The BUSY pin is polled internally by the library after each SPI command to block until the slow e-paper panel finishes its electrophoretic refresh before proceeding.

A common cathode RGB LED has three separate LED anodes sharing one ground, so each color channel is driven independently through a current-limiting resistor and assigned its own PWM-capable GPIO.

**Wiring Table**

| Component Pin | Connects to ESP32 |
|---|---|
| Red Anode (R) | 220Ω resistor → GPIO 25 |
| Green Anode (G) | 220Ω resistor → GPIO 26 |
| Blue Anode (B) | 220Ω resistor → GPIO 27 |
| Common Cathode (GND) | GND |

**Wiring Diagram**
```
        +---------------------+
        |        ESP32        |
        |                     |
        |  GPIO25 (R PWM) o---+---[220Ω]---+
        |                     |             |
        |  GPIO26 (G PWM) o---+---[220Ω]---+
        |                     |             |
        |  GPIO27 (B PWM) o---+---[220Ω]---+
        |                     |        +----+----+----+
        |             GND o---+        | R  | G  | B  |
        +---------------------+        |  RGB LED     |
                                       |  (common     |
                                       |  cathode)    |
                                       +------+-------+
                                              |
                                             GND
```
Use 220Ω resistors on each anode to limit current to a safe ~15mA per channel; omitting them risks damaging both the LED and the ESP32 GPIO.

**Code**
```cpp
#include <Arduino.h>

// GPIO pins for each color channel
const int PIN_RED   = 25;
const int PIN_GREEN = 26;
const int PIN_BLUE  = 27;

// LEDC PWM channels (ESP32 has 16; pick any three unused ones)
const int CH_RED   = 0;
const int CH_GREEN = 1;
const int CH_BLUE  = 2;

const int PWM_FREQ       = 5000;  // Hz
const int PWM_RESOLUTION = 8;     // bits → 0-255

void setupPWM() {
  ledcSetup(CH_RED,   PWM_FREQ, PWM_RESOLUTION);
  ledcSetup(CH_GREEN, PWM_FREQ, PWM_RESOLUTION);
  ledcSetup(CH_BLUE,  PWM_FREQ, PWM_RESOLUTION);

  ledcAttachPin(PIN_RED,   CH_RED);
  ledcAttachPin(PIN_GREEN, CH_GREEN);
  ledcAttachPin(PIN_BLUE,  CH_BLUE);
}

void setColor(uint8_t r, uint8_t g, uint8_t b) {
  ledcWrite(CH_RED,   r);
  ledcWrite(CH_GREEN, g);
  ledcWrite(CH_BLUE,  b);
}

void setup() {
  Serial.begin(115200);
  setupPWM();
}

void loop() {
  // Cycle through some colors
  Serial.println("Red");
  setColor(255, 0, 0);
  delay(1000);

  Serial.println("Green");
  setColor(0, 255, 0);
  delay(1000);

  Serial.println("Blue");
  setColor(0, 0, 255);
  delay(1000);

  Serial.println("Yellow");
  setColor(255, 200, 0);
  delay(1000);

  Serial.println("Cyan");
  setColor(0, 255, 255);
  delay(1000);

  Serial.println("Magenta");
  setColor(255, 0, 255);
  delay(1000);

  Serial.println("White");
  setColor(255, 255, 255);
  delay(1000);

  // Smooth fade on red channel
  Serial.println("Fading red...");
  for (int val = 0; val <= 255; val++) {
    setColor(val, 0, 0);
    delay(8);
  }
  for (int val = 255; val >= 0; val--) {
    setColor(val, 0, 0);
    delay(8);
  }
}
```

**How it works:** The ESP32's `ledcSetup`/`ledcAttachPin` API maps each GPIO to one of 16 hardware LEDC timer channels, allowing true hardware PWM independent of the main loop. `ledcWrite` then sets the duty cycle from 0–255 on each channel separately, so any RGB color can be mixed by combining three independent brightness levels.

The MPU6050 is an I2C device, so it connects to the M5Stack Core2's Port A Grove connector (GPIO32/33), keeping it off the internal I2C bus reserved for the AXP192 and touch controller.

**Wiring Table**

| Component Pin | Connects to M5Stack Core2 |
|---|---|
| VCC | 3.3V (Grove Port A) |
| GND | GND (Grove Port A) |
| SDA | GPIO32 (Port A SDA) |
| SCL | GPIO33 (Port A SCL) |
| AD0 | GND (sets I2C address to 0x68) |
| INT | Not connected (polling mode) |

**Wiring Diagram**
```
+---------------------+          +-------------------+
|    M5Stack Core2    |          |     MPU6050       |
|                     |          |                   |
|  Port A (Grove)     |          |                   |
|  GPIO32 (SDA) ------+----------+-- SDA             |
|  GPIO33 (SCL) ------+----------+-- SCL             |
|  3.3V         ------+----------+-- VCC             |
|  GND          ------+----------+-- GND             |
|                     |          |                   |
|                     |       GND+-- AD0 (addr=0x68) |
+---------------------+          +-------------------+
```

The MPU6050 runs on 3.3V and is not 5V tolerant on its logic pins, so always power it from the 3.3V rail on the Grove port.

**Code**
```cpp
#include <M5Core2.h>
#include <Wire.h>

#define MPU6050_ADDR     0x68
#define PWR_MGMT_1       0x6B
#define ACCEL_XOUT_H     0x3B
#define GYRO_XOUT_H      0x43

// Scale factors
const float ACCEL_SCALE = 16384.0f; // LSB/g for ±2g range
const float GYRO_SCALE  = 131.0f;   // LSB/(°/s) for ±250°/s range

void writeMPU6050(uint8_t reg, uint8_t value) {
  Wire.beginTransmission(MPU6050_ADDR);
  Wire.write(reg);
  Wire.write(value);
  Wire.endTransmission();
}

bool readMPU6050Bytes(uint8_t reg, uint8_t* buf, uint8_t len) {
  Wire.beginTransmission(MPU6050_ADDR);
  Wire.write(reg);
  if (Wire.endTransmission(false) != 0) return false;
  Wire.requestFrom((uint8_t)MPU6050_ADDR, len);
  for (uint8_t i = 0; i < len; i++) {
    if (!Wire.available()) return false;
    buf[i] = Wire.read();
  }
  return true;
}

int16_t combineBytes(uint8_t high, uint8_t low) {
  return (int16_t)((high << 8) | low);
}

void setup() {
  M5.begin();

  // Initialize external I2C on Port A (GPIO32=SDA, GPIO33=SCL)
  Wire.begin(32, 33);

  // Wake the MPU6050 (clear sleep bit in PWR_MGMT_1)
  writeMPU6050(PWR_MGMT_1, 0x00);
  delay(100);

  M5.Lcd.setTextSize(2);
  M5.Lcd.setCursor(0, 0);
  M5.Lcd.println("MPU6050 Ready");
  delay(1000);
  M5.Lcd.fillScreen(BLACK);
}

void loop() {
  uint8_t buf[14];

  // Read 14 bytes starting from ACCEL_XOUT_H:
  // 6 bytes accel, 2 bytes temp, 6 bytes gyro
  if (!readMPU6050Bytes(ACCEL_XOUT_H, buf, 14)) {
    M5.Lcd.fillScreen(BLACK);
    M5.Lcd.setCursor(0, 0);
    M5.Lcd.println("Read Error!");
    delay(500);
    return;
  }

  float ax = combineBytes(buf[0],  buf[1])  / ACCEL_SCALE;
  float ay = combineBytes(buf[2],  buf[3])  / ACCEL_SCALE;
  float az = combineBytes(buf[4],  buf[5])  / ACCEL_SCALE;
  // buf[6] and buf[7] are temperature -- skipped here
  float gx = combineBytes(buf[8],  buf[9])  / GYRO_SCALE;
  float gy = combineBytes(buf[10], buf[11]) / GYRO_SCALE;
  float gz = combineBytes(buf[12], buf[13]) / GYRO_SCALE;

  M5.Lcd.fillScreen(BLACK);
  M5.Lcd.setTextSize(2);
  M5.Lcd.setCursor(0, 0);
  M5.Lcd.printf("Accel (g):\n");
  M5.Lcd.printf(" X: %6.3f\n", ax);
  M5.Lcd.printf(" Y: %6.3f\n", ay);
  M5.Lcd.printf(" Z: %6.3f\n", az);
  M5.Lcd.printf("Gyro (deg/s):\n");
  M5.Lcd.printf(" X: %6.2f\n", gx);
  M5.Lcd.printf(" Y: %6.2f\n", gy);
  M5.Lcd.printf(" Z: %6.2f\n", gz);

  delay(200);
}
```

**How it works:** Writing `0x00` to the `PWR_MGMT_1` register is essential because the MPU6050 powers up in sleep mode by default and will not output any data until the sleep bit is cleared. Reading all 14 bytes in a single burst starting from `ACCEL_XOUT_H` is more efficient than individual register reads and ensures the accelerometer, temperature, and gyroscope samples are all captured atomically from the same measurement cycle.

Port B exposes GPIO26 as a PWM-capable output pin, making it the natural choice for driving the SG90 servo signal line directly from the M5Stack Core2.

**Wiring Table**

| Component Pin | Connects to M5Stack Core2 |
|---|---|
| SG90 VCC (Red) | 5V (Grove Port B) |
| SG90 GND (Brown) | GND (Grove Port B) |
| SG90 Signal (Orange) | GPIO26 (Port B pin2) |

**Wiring Diagram**
```
+-------------------------+          +-------------------+
|      M5Stack Core2      |          |    SG90 Servo     |
|                         |          |                   |
|  Port B (Grove)         |          |                   |
|  [5V  ]-----------------|----------| VCC  (Red)        |
|  [GND ]-----------------|----------| GND  (Brown)      |
|  [GPIO26]---------------|----------| Signal (Orange)   |
|  [GPIO36]  (unused)     |          |                   |
+-------------------------+          +-------------------+
```

The SG90 can run on 5V from the Grove port; do not power it from the 3.3V rail as it may lack sufficient torque and stable operation at that voltage.

**Code**
```cpp
#include <M5Core2.h>

// Port B pin2 used for PWM servo signal
const int SERVO_PIN = 26;

// PWM configuration
const int PWM_CHANNEL  = 0;
const int PWM_FREQ     = 50;   // 50 Hz standard servo frequency
const int PWM_RESOLUTION = 16; // 16-bit resolution for fine control

// SG90 pulse width range in microseconds
const int SERVO_MIN_US = 500;  // ~0 degrees
const int SERVO_MAX_US = 2400; // ~180 degrees

// Convert microseconds to 16-bit duty cycle count for 50 Hz
uint32_t usToDuty(int us) {
  // Period = 1,000,000 us / 50 Hz = 20,000 us
  // duty = (us / 20000) * 65535
  return (uint32_t)((uint64_t)us * 65535 / 20000);
}

// Set servo to angle 0-180 degrees
void setServoAngle(int angle) {
  angle = constrain(angle, 0, 180);
  int us = map(angle, 0, 180, SERVO_MIN_US, SERVO_MAX_US);
  ledcWrite(PWM_CHANNEL, usToDuty(us));
}

void setup() {
  M5.begin();
  M5.Lcd.setTextSize(2);
  M5.Lcd.setCursor(10, 10);
  M5.Lcd.println("SG90 Servo Demo");

  // Attach PWM channel to servo pin
  ledcSetup(PWM_CHANNEL, PWM_FREQ, PWM_RESOLUTION);
  ledcAttachPin(SERVO_PIN, PWM_CHANNEL);

  // Center servo at startup
  setServoAngle(90);
  delay(500);
}

void loop() {
  M5.update();

  // Sweep from 0 to 180 degrees
  for (int angle = 0; angle <= 180; angle += 5) {
    setServoAngle(angle);
    M5.Lcd.fillRect(10, 40, 300, 30, BLACK);
    M5.Lcd.setCursor(10, 40);
    M5.Lcd.printf("Angle: %3d deg", angle);
    delay(50);
  }
  delay(500);

  // Sweep back from 180 to 0 degrees
  for (int angle = 180; angle >= 0; angle -= 5) {
    setServoAngle(angle);
    M5.Lcd.fillRect(10, 40, 300, 30, BLACK);
    M5.Lcd.setCursor(10, 40);
    M5.Lcd.printf("Angle: %3d deg", angle);
    delay(50);
  }
  delay(500);
}
```

**How it works:** The ESP32's `ledcWrite` API requires converting the desired pulse width in microseconds to a duty cycle count scaled to the chosen resolution — here 16-bit (0–65535) over a 20 ms period — which is what `usToDuty()` computes. Using 16-bit resolution instead of the more common 8-bit gives much finer angular positioning since the SG90's usable pulse range (500–2400 µs) maps across a larger count span.

The MFRC522 is bridged over UART here by using a serial-passthrough adapter firmware on the reader module, routing its output through Port C (GPIO13 RX / GPIO14 TX) to avoid consuming the I2C bus on Port A.

**Wiring Table**

| Component Pin | Connects to M5Stack Core2 |
|---|---|
| VCC | 3.3V (Grove Port C power) |
| GND | GND (Grove Port C ground) |
| TX | GPIO13 (Port C RX) |
| RX | GPIO14 (Port C TX) |

**Wiring Diagram**
```
+----------------------+          +-------------------+
|    M5Stack Core2     |          |  MFRC522 (UART)   |
|                      |          |                   |
|  Port C / GPIO14 TX |--------->| RX                |
|  Port C / GPIO13 RX |<---------| TX                |
|               3.3V  |--------->| VCC               |
|                GND  |--------->| GND               |
+----------------------+          +-------------------+
```

The MFRC522 module must be running UART-bridge firmware (some breakout boards support this mode); ensure VCC is strictly 3.3V as the chip is not 5V tolerant.

**Code**
```cpp
#include <M5Core2.h>

// Port C UART pins on M5Stack Core2
#define RFIDSerial Serial2
#define RFID_RX_PIN 13
#define RFID_TX_PIN 14
#define RFID_BAUD   9600

// Frame constants for UART-bridge MFRC522 protocol
// The bridge firmware sends: 0xAA 0xBB <len> <UID bytes...> <checksum>
#define FRAME_HEADER_1 0xAA
#define FRAME_HEADER_2 0xBB
#define UID_MAX_BYTES  7

void setup() {
  M5.begin();
  M5.Lcd.setTextSize(2);
  M5.Lcd.setCursor(0, 0);
  M5.Lcd.println("RFID UART Reader");

  // Initialize Port C as Serial2
  RFIDSerial.begin(RFID_BAUD, SERIAL_8N1, RFID_RX_PIN, RFID_TX_PIN);
  Serial.println("MFRC522 UART ready.");
}

bool readUID(uint8_t* uidBuf, uint8_t* uidLen) {
  // Wait for frame header 0xAA 0xBB
  if (RFIDSerial.available() < 2) return false;

  uint8_t b1 = RFIDSerial.read();
  if (b1 != FRAME_HEADER_1) return false;

  // Block briefly for second header byte
  unsigned long t = millis();
  while (!RFIDSerial.available() && millis() - t < 50);
  if (!RFIDSerial.available()) return false;
  uint8_t b2 = RFIDSerial.read();
  if (b2 != FRAME_HEADER_2) return false;

  // Read length byte
  t = millis();
  while (!RFIDSerial.available() && millis() - t < 50);
  if (!RFIDSerial.available()) return false;
  uint8_t len = RFIDSerial.read();
  if (len == 0 || len > UID_MAX_BYTES) return false;

  // Read UID bytes
  uint8_t received = 0;
  t = millis();
  while (received < len && millis() - t < 200) {
    if (RFIDSerial.available()) {
      uidBuf[received++] = RFIDSerial.read();
    }
  }
  if (received < len) return false;

  // Read and verify checksum (XOR of all UID bytes)
  t = millis();
  while (!RFIDSerial.available() && millis() - t < 50);
  if (!RFIDSerial.available()) return false;
  uint8_t checksum = RFIDSerial.read();
  uint8_t calc = 0;
  for (uint8_t i = 0; i < len; i++) calc ^= uidBuf[i];
  if (calc != checksum) return false;

  *uidLen = len;
  return true;
}

void loop() {
  M5.update();

  uint8_t uid[UID_MAX_BYTES];
  uint8_t uidLen = 0;

  if (readUID(uid, &uidLen)) {
    String uidStr = "UID: ";
    for (uint8_t i = 0; i < uidLen; i++) {
      if (uid[i] < 0x10) uidStr += "0";
      uidStr += String(uid[i], HEX);
      if (i < uidLen - 1) uidStr += ":";
    }
    uidStr.toUpperCase();
    Serial.println(uidStr);
    M5.Lcd.fillRect(0, 40, 320, 40, BLACK);
    M5.Lcd.setCursor(0, 40);
    M5.Lcd.println(uidStr);
  }

  delay(100);
}
```

**How it works:** `Serial2.begin()` maps ESP32's second hardware UART peripheral directly to GPIO13/GPIO14 (Port C), giving clean full-duplex communication without bit-banging. The `readUID()` function relies on a two-byte magic header (`0xAA 0xBB`) to synchronize with the bridge firmware's framing, then validates the payload with an XOR checksum to discard corrupted or partial reads.

Port B on the M5Stack Core2 exposes GPIO36 and GPIO26 as general-purpose I/O pins; since GPIO36 is input-only on the ESP32, the DS18B20 DATA line is routed to GPIO26, which supports the bidirectional OneWire protocol.

**Wiring Table**

| Component Pin | Connects to M5Stack Core2 |
|---|---|
| VCC | 3.3V (Grove Port B) |
| GND | GND (Grove Port B) |
| DATA | GPIO26 (Port B pin2) |
| DATA (pull-up) | 4.7kΩ resistor to 3.3V |

**Wiring Diagram**
```
+-------------------+          +-------------------+
|   M5Stack Core2   |          |     DS18B20       |
|                   |          |                   |
|  Port B           |          |                   |
|  3.3V  -----------+----------+  VCC              |
|  GND   -----------+----------+  GND              |
|  GPIO26-----------+----+-----+  DATA             |
|                   |    |     +-------------------+
+-------------------+    |
                         R (4.7kΩ)
                         |
                        3.3V
```

A 4.7kΩ pull-up resistor is required between the DATA line and 3.3V for reliable OneWire communication; without it the bus will float and readings will fail.

**Code**
```cpp
#include <M5Core2.h>
#include <OneWire.h>
#include <DallasTemperature.h>

// DS18B20 DATA pin connected to Port B pin2 (GPIO26)
#define ONE_WIRE_BUS 26

OneWire oneWire(ONE_WIRE_BUS);
DallasTemperature sensors(&oneWire);

void setup() {
  M5.begin();
  M5.Lcd.setTextSize(2);
  M5.Lcd.setTextColor(WHITE, BLACK);

  sensors.begin();

  M5.Lcd.setCursor(0, 0);
  M5.Lcd.println("DS18B20 Temp");
  M5.Lcd.println("Sensor Ready");

  Serial.begin(115200);
  Serial.println("DS18B20 initialized");

  uint8_t deviceCount = sensors.getDeviceCount();
  Serial.printf("Devices found: %d\n", deviceCount);
  M5.Lcd.printf("Devices: %d\n", deviceCount);
}

void loop() {
  M5.update();

  // Request temperature conversion from all sensors on the bus
  sensors.requestTemperatures();

  // getTempCByIndex(0) fetches the first sensor's result in Celsius
  float tempC = sensors.getTempCByIndex(0);
  float tempF = DallasTemperature::toFahrenheit(tempC);

  if (tempC == DEVICE_DISCONNECTED_C) {
    M5.Lcd.setCursor(0, 80);
    M5.Lcd.println("Sensor error!  ");
    Serial.println("ERROR: Sensor disconnected");
  } else {
    M5.Lcd.setCursor(0, 80);
    M5.Lcd.printf("%.2f C         \n", tempC);
    M5.Lcd.printf("%.2f F         \n", tempF);

    Serial.printf("Temperature: %.2f C / %.2f F\n", tempC, tempF);
  }

  delay(1000);
}
```

**How it works:** `sensors.requestTemperatures()` broadcasts a convert-T command over the OneWire bus and blocks until the 12-bit conversion completes (~750 ms), after which `getTempCByIndex(0)` retrieves the result by sensor position rather than requiring you to know the device's unique 64-bit address. Checking the return value against `DEVICE_DISCONNECTED_C` catches wiring faults or a missing pull-up resistor gracefully.

Port B's two GPIO pins (GPIO36 and GPIO26) are used here, with GPIO26 driving the TRIG pulse and GPIO36 reading the ECHO return — note that GPIO36 is input-only on the ESP32, which suits the ECHO line perfectly.

**Wiring Table**

| Component Pin | Connects to M5Stack Core2 |
|---|---|
| VCC | 5V (Grove Port B) |
| GND | GND (Grove Port B) |
| TRIG | GPIO26 (Port B pin2) |
| ECHO | GPIO36 (Port B pin1) |

**Wiring Diagram**
```
+---------------------+          +-------------------+
|    M5Stack Core2    |          |     HC-SR04       |
|                     |          |                   |
|  Port B             |          |                   |
|  5V  ---------------+----------+ VCC               |
|  GND ---------------+----------+ GND               |
|  GPIO26 (pin2) -----+----------+ TRIG              |
|  GPIO36 (pin1) -----+----------+ ECHO              |
+---------------------+          +-------------------+
```

The HC-SR04 operates reliably at 5V; its ECHO output signal is 5V logic, but GPIO36 on the ESP32 is generally tolerant enough in practice — for production use consider a voltage divider on the ECHO line to protect the GPIO.

**Code**
```cpp
#include <M5Core2.h>

const int TRIG_PIN = 26;  // Port B pin2 - output
const int ECHO_PIN = 36;  // Port B pin1 - input only GPIO

float measureDistanceCm() {
  // Send a 10us trigger pulse
  digitalWrite(TRIG_PIN, LOW);
  delayMicroseconds(2);
  digitalWrite(TRIG_PIN, HIGH);
  delayMicroseconds(10);
  digitalWrite(TRIG_PIN, LOW);

  // Measure the echo pulse duration (timeout after 30ms)
  long duration = pulseIn(ECHO_PIN, HIGH, 30000);

  if (duration == 0) {
    return -1.0f;  // No echo received / out of range
  }

  // Convert time to distance: speed of sound ~343 m/s
  // distance = duration(us) * 0.0343 / 2
  float distanceCm = (duration * 0.0343f) / 2.0f;
  return distanceCm;
}

void setup() {
  M5.begin();
  M5.Lcd.setTextSize(2);
  M5.Lcd.setTextColor(WHITE, BLACK);

  pinMode(TRIG_PIN, OUTPUT);
  pinMode(ECHO_PIN, INPUT);  // GPIO36 is input-only, no INPUT_PULLUP needed

  digitalWrite(TRIG_PIN, LOW);

  Serial.begin(115200);
  Serial.println("HC-SR04 Ultrasonic Distance Sensor Ready");
}

void loop() {
  M5.update();

  float distance = measureDistanceCm();

  M5.Lcd.setCursor(10, 80);
  if (distance < 0) {
    M5.Lcd.println("Out of range!   ");
    Serial.println("Out of range!");
  } else {
    M5.Lcd.printf("Dist: %.1f cm   ", distance);
    Serial.printf("Distance: %.1f cm\n", distance);
  }

  delay(200);
}
```

**How it works:** The `pulseIn()` call with a 30 ms timeout is critical — it measures how long the ECHO pin stays HIGH after the trigger pulse, which is directly proportional to the round-trip travel time of the ultrasonic burst, and the timeout prevents the code from blocking indefinitely when no object is detected. GPIO36 is used as a pure input (it has no internal pull-up capability) which is exactly what the ECHO receive line requires.

The BME280 uses I2C with a default address of 0x76 (or 0x77 if SDO is pulled high), so both SDA and SCL connect to the ESP32's hardware I2C pins to keep bus timing reliable.

