| Component Pin | Connects to ESP32 |
|---|---|
| VCC | 3.3V |
| GND | GND |
| SDA | GPIO 21 |
| SCL | GPIO 22 |
| SDO | GND (sets I2C address to 0x76) |
| CSB | 3.3V (selects I2C mode) |

**Wiring Diagram**
```
        +------------------+          +-------------------+
        |      ESP32       |          |      BME280        |
        |                  |          |                    |
        |       3.3V  o----+----------+o VCC               |
        |        GND  o----+----------+o GND               |
        |             |    |          |                    |
        |   GPIO21    o----+----------+o SDA               |
        |  (I2C SDA)  |    |          |                    |
        |   GPIO22    o----+----------+o SCL               |
        |  (I2C SCL)  |    |          |                    |
        |             |    |     GND--+o SDO  (addr 0x76)  |
        |             |    |   3.3V--++o CSB  (I2C mode)   |
        +------------------+          +-------------------+
```

The BME280 is a 3.3V-only device — do not connect VCC to 5V or you risk damaging the sensor.

**Code**
```cpp
#include <Wire.h>
#include <Adafruit_Sensor.h>
#include <Adafruit_BME280.h>

#define BME280_I2C_ADDRESS 0x76
#define SEA_LEVEL_PRESSURE_HPA 1013.25

Adafruit_BME280 bme;

void setup() {
  Serial.begin(115200);
  Wire.begin(21, 22); // SDA=GPIO21, SCL=GPIO22

  if (!bme.begin(BME280_I2C_ADDRESS, &Wire)) {
    Serial.println("Could not find BME280 sensor! Check wiring and I2C address.");
    while (1) delay(10);
  }

  // Use indoor navigation mode for stable readings
  bme.setSampling(
    Adafruit_BME280::MODE_NORMAL,
    Adafruit_BME280::SAMPLING_X16,  // temperature
    Adafruit_BME280::SAMPLING_X16,  // pressure
    Adafruit_BME280::SAMPLING_X16,  // humidity
    Adafruit_BME280::FILTER_X16,
    Adafruit_BME280::STANDBY_MS_500
  );

  Serial.println("BME280 initialized.");
}

void loop() {
  float temperature = bme.readTemperature();          // degrees Celsius
  float humidity    = bme.readHumidity();             // percent RH
  float pressure    = bme.readPressure() / 100.0F;   // hPa
  float altitude    = bme.readAltitude(SEA_LEVEL_PRESSURE_HPA); // meters

  Serial.print("Temperature: "); Serial.print(temperature); Serial.println(" °C");
  Serial.print("Humidity:    "); Serial.print(humidity);    Serial.println(" %");
  Serial.print("Pressure:    "); Serial.print(pressure);    Serial.println(" hPa");
  Serial.print("Altitude:    "); Serial.print(altitude);    Serial.println(" m");
  Serial.println();

  delay(2000);
}
```

**How it works:** Passing `&Wire` explicitly to `bme.begin()` ensures the library uses the specific `Wire` instance initialized on GPIO 21/22 rather than any default, which matters on ESP32 where multiple I2C buses are possible. Dividing `readPressure()` by 100.0F converts the raw value from Pascals to the more human-readable hectopascals (hPa/millibar) unit.

The MPU6050 uses I2C and runs on 3.3V, so it connects directly to the ESP32's hardware I2C bus without any level shifting.

**Wiring Table**

| Component Pin | Connects to ESP32 |
|---|---|
| VCC | 3.3V |
| GND | GND |
| SDA | GPIO 21 (SDA) |
| SCL | GPIO 22 (SCL) |
| AD0 | GND (sets I2C address to 0x68) |
| INT | (not connected in this example) |

**Wiring Diagram**
```
        +----------------+          +-------------------+
        |    ESP32       |          |     MPU6050       |
        |                |          |                   |
        |   3.3V o-------+----------o VCC               |
        |    GND o-------+----------o GND               |
        |                |    +-----o AD0               |
        |                |    |     |                   |
        |  GPIO21 o-------+----------o SDA               |
        |  GPIO22 o-------+----------o SCL               |
        |                |          |                   |
        +----------------+          +-------------------+
                              GND --+
```

Keep SDA and SCL lines short; the ESP32's internal I2C pull-ups are usually sufficient for bench use, but add 4.7kΩ external pull-ups to 3.3V if you see communication errors.

**Code**
```cpp
#include <Wire.h>

const uint8_t MPU6050_ADDR   = 0x68;
const uint8_t REG_PWR_MGMT_1 = 0x6B;
const uint8_t REG_ACCEL_XOUT = 0x3B;
const uint8_t REG_GYRO_XOUT  = 0x43;

// Scale factors from datasheet (default full-scale ranges)
const float ACCEL_SCALE = 16384.0f; // LSB/g  for ±2g range
const float GYRO_SCALE  = 131.0f;   // LSB/°/s for ±250°/s range

void writeByte(uint8_t addr, uint8_t reg, uint8_t value) {
  Wire.beginTransmission(addr);
  Wire.write(reg);
  Wire.write(value);
  Wire.endTransmission();
}

void readBytes(uint8_t addr, uint8_t reg, uint8_t count, uint8_t* dest) {
  Wire.beginTransmission(addr);
  Wire.write(reg);
  Wire.endTransmission(false);  // repeated start
  Wire.requestFrom((uint8_t)addr, count);
  for (uint8_t i = 0; i < count && Wire.available(); i++) {
    dest[i] = Wire.read();
  }
}

int16_t toInt16(uint8_t hi, uint8_t lo) {
  return (int16_t)((hi << 8) | lo);
}

void setup() {
  Serial.begin(115200);
  Wire.begin(21, 22);  // SDA=GPIO21, SCL=GPIO22

  // Wake the MPU6050 (clears sleep bit in PWR_MGMT_1)
  writeByte(MPU6050_ADDR, REG_PWR_MGMT_1, 0x00);
  delay(100);

  Serial.println("MPU6050 ready");
}

void loop() {
  uint8_t rawAccel[6];
  uint8_t rawGyro[6];

  readBytes(MPU6050_ADDR, REG_ACCEL_XOUT, 6, rawAccel);
  readBytes(MPU6050_ADDR, REG_GYRO_XOUT,  6, rawGyro);

  float ax = toInt16(rawAccel[0], rawAccel[1]) / ACCEL_SCALE;
  float ay = toInt16(rawAccel[2], rawAccel[3]) / ACCEL_SCALE;
  float az = toInt16(rawAccel[4], rawAccel[5]) / ACCEL_SCALE;

  float gx = toInt16(rawGyro[0], rawGyro[1]) / GYRO_SCALE;
  float gy = toInt16(rawGyro[2], rawGyro[3]) / GYRO_SCALE;
  float gz = toInt16(rawGyro[4], rawGyro[5]) / GYRO_SCALE;

  Serial.printf("Accel (g):  X=%.3f  Y=%.3f  Z=%.3f\n", ax, ay, az);
  Serial.printf("Gyro (°/s): X=%.3f  Y=%.3f  Z=%.3f\n\n", gx, gy, gz);

  delay(200);
}
```

**How it works:** Writing `0x00` to the `PWR_MGMT_1` register is essential — the MPU6050 powers up in sleep mode and will return all zeros until that bit is cleared. The repeated-start condition (`endTransmission(false)`) in `readBytes` keeps the I2C bus active between the register-address write and the data read, which the MPU6050 requires for burst reads.

The DS3231 uses I2C and operates at 3.3V, making it directly compatible with the ESP32's default I2C pins (GPIO 21/22) without any level shifting.

**Wiring Table**

| Component Pin | Connects to ESP32 |
|---|---|
| VCC | 3.3V |
| GND | GND |
| SDA | GPIO 21 |
| SCL | GPIO 22 |

**Wiring Diagram**
```
        +----------------------+         +-------------------+
        |        ESP32         |         |   DS3231 RTC      |
        |                     |         |                   |
        |       3.3V  o-------+---------o VCC               |
        |        GND  o-------+---------o GND               |
        |  GPIO21/SDA o-------+---------o SDA               |
        |  GPIO22/SCL o-------+---------o SCL               |
        +----------------------+         +-------------------+
```

The DS3231 has built-in pull-up resistors on many breakout boards; if yours does not, add 4.7kΩ pull-ups from SDA and SCL to 3.3V.

**Code**
```cpp
#include <Wire.h>
#include <RTClib.h>  // Adafruit RTClib library

RTC_DS3231 rtc;

void setup() {
  Serial.begin(115200);
  Wire.begin(21, 22);  // SDA, SCL

  if (!rtc.begin()) {
    Serial.println("Couldn't find DS3231 RTC. Check wiring!");
    while (1) delay(10);
  }

  // If the RTC lost power or is not set, set it to the compile time
  if (rtc.lostPower()) {
    Serial.println("RTC lost power -- setting time to compile time.");
    rtc.adjust(DateTime(F(__DATE__), F(__TIME__)));
  }

  Serial.println("DS3231 RTC initialized.");
}

void loop() {
  DateTime now = rtc.now();

  Serial.print("Current date/time: ");
  Serial.print(now.year());   Serial.print('/');
  Serial.print(now.month());  Serial.print('/');
  Serial.print(now.day());    Serial.print(" ");

  // Zero-pad hours/minutes/seconds for readability
  if (now.hour()   < 10) Serial.print('0');
  Serial.print(now.hour());   Serial.print(':');
  if (now.minute() < 10) Serial.print('0');
  Serial.print(now.minute()); Serial.print(':');
  if (now.second() < 10) Serial.print('0');
  Serial.println(now.second());

  delay(1000);
}
```

**How it works:** `rtc.adjust(DateTime(F(__DATE__), F(__TIME__)))` seeds the DS3231 with the exact moment the sketch was compiled, so the clock is accurate from first boot without any manual input. The `rtc.lostPower()` check reads the DS3231's internal power-loss flag, ensuring we only overwrite the stored time when the backup coin-cell battery has been depleted or removed — not on every restart.

The ADS1115 communicates over I2C and its I2C address is set by the ADDR pin, which is tied to GND for the default address of 0x48; both SDA and SCL need 4.7kΩ pull-up resistors to 3.3V if not already present on the module.

**Wiring Table**

| Component Pin | Connects to ESP32 |
|---|---|
| VCC | 3.3V |
| GND | GND |
| SDA | GPIO 21 (SDA) |
| SCL | GPIO 22 (SCL) |
| ADDR | GND (sets I2C address to 0x48) |
| AIN0 | Analog signal input (0–3.3V) |
| AIN1 | GND (or second signal for differential) |

**Wiring Diagram**
```
        +------------------+          +-------------------+
        |      ESP32       |          |     ADS1115       |
        |                  |          |                   |
        |   3.3V  o--------+----------o VCC               |
        |   GND   o--------+----------o GND               |
        |                  |    +-----o ADDR (0x48)       |
        |                  |    |     |                   |
        |  GPIO21 o--------+----+-----o SDA               |
        |  GPIO22 o--------+----------o SCL               |
        |                  |          |                   |
        |                  |   Signal-o AIN0              |
        |                  |     GND--o AIN1              |
        +------------------+          +-------------------+
```
The ADS1115 is 3.3V-only on its VCC and signal inputs; do not apply more than VCC + 0.3V on any analog input pin.

**Code**
```cpp
#include <Wire.h>
#include <Adafruit_ADS1X15.h>

Adafruit_ADS1115 ads;

void setup() {
  Serial.begin(115200);
  Wire.begin(21, 22); // SDA=GPIO21, SCL=GPIO22

  // Default I2C address 0x48 (ADDR tied to GND)
  if (!ads.begin(0x48)) {
    Serial.println("Failed to initialize ADS1115! Check wiring.");
    while (1);
  }

  // Set gain: GAIN_ONE = +/-4.096V range, 1 bit = 0.125mV
  ads.setGain(GAIN_ONE);

  Serial.println("ADS1115 ready.");
}

void loop() {
  // Read single-ended voltage on AIN0 (referenced to GND)
  int16_t rawAIN0 = ads.readADC_SingleEnded(0);

  // Convert raw reading to voltage using the gain's LSB size (0.125 mV per bit for GAIN_ONE)
  float voltage = rawAIN0 * 0.0001250f;

  Serial.print("AIN0 raw: ");
  Serial.print(rawAIN0);
  Serial.print("  Voltage: ");
  Serial.print(voltage, 4);
  Serial.println(" V");

  delay(500);
}
```

**How it works:** `ads.setGain(GAIN_ONE)` configures the internal programmable gain amplifier to a ±4.096 V full-scale range, which maps the 16-bit signed output (−32768 to +32767) to a resolution of 0.125 mV per LSB — that per-bit voltage constant (0.0001250f V) is what converts the raw integer from `readADC_SingleEnded()` into a meaningful floating-point voltage.

The NRF24L01 runs on 3.3V only and uses the ESP32's hardware SPI bus; a 10–100µF decoupling capacitor across VCC/GND is strongly recommended because the module draws current spikes that can cause brown-outs.

**Wiring Table**

| Component Pin | Connects to ESP32 |
|---|---|
| VCC | 3.3V |
| GND | GND |
| SCK | GPIO 18 (SPI SCK) |
| MISO | GPIO 19 (SPI MISO) |
| MOSI | GPIO 23 (SPI MOSI) |
| CSN | GPIO 5 (SPI CS) |
| CE | GPIO 4 (any free GPIO) |
| IRQ | (not connected, optional) |

**Wiring Diagram**
```
+-------------------------+          +-------------------+
|          ESP32          |          |     NRF24L01      |
|                         |          |                   |
|   3.3V |----------------+----------| VCC               |
|    GND |----------------+----------| GND               |
|        |          100uF cap        |                   |
|        |       (VCC to GND)        |                   |
| GPIO18 |---------------------------| SCK               |
| GPIO19 |---------------------------| MISO              |
| GPIO23 |---------------------------| MOSI              |
|  GPIO5 |---------------------------| CSN               |
|  GPIO4 |---------------------------| CE                |
+-------------------------+          +-------------------+
```

Do NOT supply 5V to the NRF24L01 — it is not 5V tolerant and will be permanently damaged.

**Code**
```cpp
#include <SPI.h>
#include <RF24.h>

// CE pin, CSN pin
RF24 radio(4, 5);

// Both TX and RX nodes must use the same address
const byte address[6] = "00001";

void setup() {
  Serial.begin(115200);

  if (!radio.begin()) {
    Serial.println("NRF24L01 not detected! Check wiring.");
    while (1) {}
  }

  // Set power level and data rate for reliability
  radio.setPALevel(RF24_PA_LOW);
  radio.setDataRate(RF24_250KBPS);

  // Open writing pipe to the target address
  radio.openWritingPipe(address);

  // Disable auto-ack for this simple broadcast example
  radio.stopListening();

  Serial.println("NRF24L01 ready, transmitting...");
}

void loop() {
  const char message[] = "Hello ESP32";

  bool success = radio.write(&message, sizeof(message));

  if (success) {
    Serial.println("Sent: Hello ESP32");
  } else {
    Serial.println("Transmission failed or timed out");
  }

  delay(1000);
}
```

**How it works:** The `RF24` constructor takes CE and CSN pin numbers separately from the SPI bus because CE controls TX/RX mode switching while CSN is the standard SPI chip-select — keeping them distinct lets the library manage radio state independently of the SPI transaction. `radio.write()` blocks until the packet is sent (or times out), returning `true` on success, which is why it works reliably inside `loop()` without needing interrupt handling.

The MAX7219 uses SPI but only needs MOSI, SCK, and a chip-select line — MISO is unused since the MAX7219 is a write-only device, so no MISO connection is required.

**Wiring Table**

| Component Pin | Connects to ESP32 |
|---|---|
| VCC | 5V |
| GND | GND |
| DIN (MOSI) | GPIO 23 (VSPI MOSI) |
| CLK (SCK) | GPIO 18 (VSPI SCK) |
| CS (LOAD) | GPIO 5 (VSPI CS) |

**Wiring Diagram**
```
        +------------------+          +-------------------+
        |      ESP32       |          |  MAX7219 8x8 LED  |
        |                  |          |      Matrix       |
        |      GPIO23 MOSI |--------->| DIN               |
        |      GPIO18  SCK |--------->| CLK               |
        |       GPIO5   CS |--------->| CS (LOAD)         |
        |             3.3V |          |                   |
        |              5V  |--------->| VCC               |
        |             GND  |--------->| GND               |
        +------------------+          +-------------------+
```
The MAX7219 requires a 5V supply for the LED matrix; its logic inputs are 5V-tolerant and accept the 3.3V signals from the ESP32 without a level shifter.

**Code**
```cpp
#include <Arduino.h>
#include <SPI.h>
#include <MD_Parola.h>
#include <MD_MAX72xx.h>

// Hardware type for common generic 8x8 modules
#define HARDWARE_TYPE MD_MAX72XX::FC16_HW
#define MAX_DEVICES   1   // Number of chained MAX7219 modules

#define PIN_CS   5
#define PIN_CLK  18
#define PIN_MOSI 23

// Create Parola object using hardware SPI
MD_Parola display(HARDWARE_TYPE, PIN_MOSI, PIN_CLK, PIN_CS, MAX_DEVICES);

const char* scrollText = "Hello ESP32! ";
uint8_t scrollSpeed = 50; // ms per frame step

void setup() {
  Serial.begin(115200);

  if (!display.begin()) {
    Serial.println("MAX7219 init failed!");
    while (true);
  }

  display.setIntensity(5);          // Brightness 0-15
  display.displayClear();

  // Start a left-scrolling text animation
  display.displayScroll(scrollText, PA_LEFT, PA_SCROLL_LEFT, scrollSpeed);
  Serial.println("Scrolling started.");
}

void loop() {
  // displayAnimate() returns true when the current animation cycle finishes
  if (display.displayAnimate()) {
    // Reset the same scroll so it loops continuously
    display.displayReset();
  }
}
```

**How it works:** `MD_Parola` wraps the lower-level `MD_MAX72xx` SPI driver and handles frame timing and animation state internally — calling `displayAnimate()` in every `loop()` iteration advances the scroll by one step only when enough time has elapsed, so no `delay()` is needed and the loop stays non-blocking. When `displayAnimate()` returns `true` the animation is complete, and `displayReset()` restarts it from the beginning to create a continuous loop.

