}
```

**How it works:** `initR(INITR_BLACKTAB)` sends the specific initialization sequence for the common black-tab 1.8" ST7735 panel — using the wrong variant flag (e.g. `INITR_REDTAB`) will produce shifted or color-incorrect output. The library automatically uses ESP32's hardware SPI peripheral on GPIO 18/23, which is significantly faster than software bit-banging and is why no explicit `SPI.begin()` call is needed before `initR()`.

The MFRC522 uses SPI and runs at 3.3V, making it directly compatible with the ESP32's hardware SPI bus without any level shifting.

**Wiring Table**

| Component Pin | Connects to ESP32 |
|---|---|
| VCC (3.3V) | 3.3V |
| GND | GND |
| SCK | GPIO 18 (SPI SCK) |
| MISO | GPIO 19 (SPI MISO) |
| MOSI | GPIO 23 (SPI MOSI) |
| SDA (CS) | GPIO 5 (chip select) |
| RST | GPIO 22 |

**Wiring Diagram**
```
 +----------------------+         +-------------------+
 |        ESP32         |         |     MFRC522        |
 |                      |         |                   |
 |    3.3V |------------+-------->| VCC               |
 |     GND |------------+-------->| GND               |
 |  GPIO18 |------------+-------->| SCK               |
 |  GPIO19 |<-----------+--------| MISO              |
 |  GPIO23 |------------+-------->| MOSI              |
 |   GPIO5 |------------+-------->| SDA (CS)          |
 |  GPIO22 |------------+-------->| RST               |
 +----------------------+         +-------------------+
```
The MFRC522 is strictly 3.3V — never connect VCC to 5V or you risk damaging the module.

**Code**
```cpp
#include <SPI.h>
#include <MFRC522.h>

#define SS_PIN  5
#define RST_PIN 22

MFRC522 rfid(SS_PIN, RST_PIN);

void setup() {
  Serial.begin(115200);
  SPI.begin();          // Init SPI bus (SCK=18, MISO=19, MOSI=23)
  rfid.PCD_Init();      // Init MFRC522
  Serial.println("MFRC522 RFID Reader ready. Scan a card...");
}

void loop() {
  // Look for a new card; return early if none present
  if (!rfid.PICC_IsNewCardPresent() || !rfid.PICC_ReadCardSerial()) {
    return;
  }

  Serial.print("Card UID: ");
  for (byte i = 0; i < rfid.uid.size; i++) {
    if (rfid.uid.uidByte[i] < 0x10) {
      Serial.print("0"); // leading zero for single-digit hex bytes
    }
    Serial.print(rfid.uid.uidByte[i], HEX);
    if (i < rfid.uid.size - 1) Serial.print(":");
  }
  Serial.println();

  rfid.PICC_HaltA();       // Halt the current card
  rfid.PCD_StopCrypto1();  // Stop encryption on PCD
}
```

**How it works:** `PICC_IsNewCardPresent()` followed by `PICC_ReadCardSerial()` must both return true before any UID data is valid — this two-step check prevents spurious reads from RF noise. Calling `PICC_HaltA()` and `PCD_StopCrypto1()` at the end of each loop iteration resets the reader state so the same card can be re-detected on the next pass rather than being ignored as already processed.

The MAX6675 uses a read-only SPI interface (no MOSI needed) and outputs 12-bit temperature data, so only SCK, CS, and MISO are required from the ESP32's SPI bus.

**Wiring Table**

| Component Pin | Connects to ESP32 |
|---|---|
| VCC | 3.3V |
| GND | GND |
| SCK | GPIO 18 (SPI SCK) |
| SO (MISO) | GPIO 19 (SPI MISO) |
| CS | GPIO 5 (chip select) |
| T+ | Thermocouple positive lead |
| T- | Thermocouple negative lead |

**Wiring Diagram**
```
+----------------------+          +-------------------+
|        ESP32         |          |     MAX6675       |
|                      |          |                   |
|  3.3V |--------------+----------| VCC               |
|   GND |--------------+----------| GND               |
| GPIO18|--------------+----------| SCK               |
| GPIO19|--------------+----------| SO (MISO)         |
|  GPIO5|--------------+----------| CS                |
|                      |          |                   |
|                      |          | T+ |-- Thermocouple+|
|                      |          | T- |-- Thermocouple-|
+----------------------+          +-------------------+
```
The MAX6675 is strictly 3.3V–5V tolerant on VCC, but its logic levels follow VCC, so powering it from the ESP32's 3.3V rail keeps logic levels safe for the ESP32's GPIOs.

**Code**
```cpp
#include <Arduino.h>
#include <SPI.h>

// Pin definitions
const int CS_PIN  = 5;
const int SCK_PIN = 18;
const int SO_PIN  = 19;  // MISO — MAX6675 is read-only, no MOSI needed

// Read raw 16-bit word from MAX6675 and convert to Celsius
float readThermocouple() {
  digitalWrite(CS_PIN, LOW);
  delayMicroseconds(2);  // CS assert-to-clock setup time (t_CSS >= 100 ns)

  // MAX6675 sends 16 bits: 3 status bits + 12 data bits + 1 fault bit
  uint16_t rawData = SPI.transfer16(0x0000);

  digitalWrite(CS_PIN, HIGH);

  // Bit 2 (D2) is the fault bit — if set, thermocouple is disconnected
  if (rawData & 0x0004) {
    Serial.println("ERROR: Thermocouple not connected!");
    return NAN;
  }

  // Bits [15:3] contain the 12-bit temperature value (LSB = 0.25 °C)
  uint16_t tempRaw = (rawData >> 3) & 0x0FFF;
  return tempRaw * 0.25f;
}

void setup() {
  Serial.begin(115200);
  pinMode(CS_PIN, OUTPUT);
  digitalWrite(CS_PIN, HIGH);  // Deselect chip on startup

  // MAX6675 SPI: Mode 0, max clock 4.3 MHz
  SPI.begin(SCK_PIN, SO_PIN, -1, CS_PIN);  // -1 = no MOSI
  SPI.beginTransaction(SPISettings(1000000, MSBFIRST, SPI_MODE0));

  Serial.println("MAX6675 Thermocouple Reader Ready");
}

void loop() {
  float tempC = readThermocouple();

  if (!isnan(tempC)) {
    float tempF = tempC * 9.0f / 5.0f + 32.0f;
    Serial.print("Temperature: ");
    Serial.print(tempC, 2);
    Serial.print(" °C  /  ");
    Serial.print(tempF, 2);
    Serial.println(" °F");
  }

  delay(500);  // MAX6675 conversion time is ~170 ms; 500 ms gives comfortable margin
}
```

**How it works:** The key decode step shifts the raw 16-bit SPI word right by 3 bits and masks with 0x0FFF to isolate the 12-bit ADC result, then multiplies by 0.25 because each LSB represents a quarter of a degree Celsius. Passing `-1` as the MOSI pin to `SPI.begin()` leaves that bus line unconnected, which is correct since the MAX6675 is a transmit-only device and never needs to receive data.

The SIM800L operates at 3.7–4.2V (not 3.3V or 5V), so it needs its own regulated supply — a LiPo cell or dedicated 4V regulator — while its UART logic levels are 2.8V, which the ESP32's 3.3V GPIOs can drive directly without a level shifter in most setups.

**Wiring Table**

| Component Pin | Connects to ESP32 |
|---|---|
| VCC | 3.7–4.2V external supply (NOT ESP32 3.3V) |
| GND | GND (shared with ESP32 GND) |
| TXD | GPIO16 (ESP32 RX2) |
| RXD | GPIO17 (ESP32 TX2) |
| RST | GPIO5 (optional reset control) |

**Wiring Diagram**
```
+----------------------+          +-------------------+
|        ESP32         |          |     SIM800L       |
|                      |          |                   |
|   GPIO17 (TX2) ------|--------->| RXD               |
|   GPIO16 (RX2) <-----|----------| TXD               |
|        GPIO5  -------|--------->| RST               |
|            GND ------+--------- | GND               |
|                      |    |     |                   |
+----------------------+    |     | VCC               |
                            |     +--------+----------+
                            |              |
                   +--------+------+  4.0V regulated
                   | External 4.0V |  supply (e.g.
                   | Supply / LiPo |  LiPo or LDO)
                   +---------------+
```
The SIM800L can draw up to 2A in bursts during transmission, so the external power supply must be capable of sourcing at least 2A; powering it from the ESP32's 3.3V or 5V pin will cause resets or brownouts.

**Code**
```cpp
#include <Arduino.h>
#include <HardwareSerial.h>

// Use ESP32 UART2 for SIM800L
HardwareSerial sim800(2); // UART2

const int SIM800_TX_PIN = 17; // ESP32 TX2 -> SIM800L RXD
const int SIM800_RX_PIN = 16; // ESP32 RX2 <- SIM800L TXD
const int SIM800_RST_PIN = 5;

const char* PHONE_NUMBER = "+15551234567"; // Replace with recipient number
const char* SMS_TEXT = "Hello from ESP32 + SIM800L!";

void sendAT(const char* cmd, unsigned long timeout = 2000) {
  sim800.println(cmd);
  unsigned long start = millis();
  while (millis() - start < timeout) {
    while (sim800.available()) {
      Serial.write(sim800.read());
    }
  }
}

bool waitForResponse(const char* expected, unsigned long timeout = 5000) {
  String response = "";
  unsigned long start = millis();
  while (millis() - start < timeout) {
    while (sim800.available()) {
      char c = sim800.read();
      response += c;
      Serial.write(c);
    }
    if (response.indexOf(expected) != -1) return true;
  }
  return false;
}

void resetSIM800() {
  digitalWrite(SIM800_RST_PIN, LOW);
  delay(200);
  digitalWrite(SIM800_RST_PIN, HIGH);
  delay(3000); // Wait for module to boot
}

void sendSMS(const char* number, const char* text) {
  // Set SMS text mode
  sendAT("AT+CMGF=1");
  delay(500);

  // Specify recipient
  String cmd = String("AT+CMGS=\"") + number + "\"";
  sim800.println(cmd);
  delay(500);

  // Send message body followed by Ctrl+Z (ASCII 26) to submit
  sim800.print(text);
  sim800.write(26);

  // Wait for +CMGS confirmation
  if (waitForResponse("+CMGS", 10000)) {
    Serial.println("\nSMS sent successfully!");
  } else {
    Serial.println("\nSMS send failed.");
  }
}

void setup() {
  Serial.begin(115200);
  pinMode(SIM800_RST_PIN, OUTPUT);
  digitalWrite(SIM800_RST_PIN, HIGH);

  // Begin UART2 with explicit TX/RX pins
  sim800.begin(9600, SERIAL_8N1, SIM800_RX_PIN, SIM800_TX_PIN);
  delay(1000);

  Serial.println("Resetting SIM800L...");
  resetSIM800();

  Serial.println("Checking module...");
  sendAT("AT");
  delay(500);

  // Wait for network registration
  Serial.println("Waiting for network...");
  for (int i = 0; i < 10; i++) {
    sim800.println("AT+CREG?");
    delay(1000);
    while (sim800.available()) Serial.write(sim800.read());
  }

  Serial.println("Sending SMS...");
  sendSMS(PHONE_NUMBER, SMS_TEXT);
}

void loop() {
  // Echo SIM800L output to Serial Monitor for debugging
  while (sim800.available()) Serial.write(sim800.read());
  while (Serial.available()) sim800.write(Serial.read());
}
```

**How it works:** The SMS is submitted by sending `AT+CMGF=1` to select text mode, then `AT+CMGS="number"` to open the message, and finally terminating the message body with `sim800.write(26)` — ASCII 26 is the Ctrl+Z character that signals the SIM800L to transmit the SMS over the cellular network. The `HardwareSerial sim800(2)` constructor selects ESP32's second hardware UART, and `sim800.begin(9600, SERIAL_8N1, SIM800_RX_PIN, SIM800_TX_PIN)` explicitly maps it to GPIO16/17 instead of the default UART2 pins.

The HC-05 uses UART communication, so it is wired to one of the ESP32's hardware UART ports (UART2 on GPIO16/17) to keep the primary Serial port free for USB debug output.

**Wiring Table**

| Component Pin | Connects to ESP32 |
|---|---|
| VCC | 5V |
| GND | GND |
| TX | GPIO16 (UART2 RX) |
| RX | GPIO17 (UART2 TX) — through voltage divider |

**Wiring Diagram**
```
        +----------------------+          +-------------------+
        |        ESP32         |          |      HC-05        |
        |                     |          |                   |
        |    5V  o------------|----------o VCC               |
        |   GND  o------------|----------o GND               |
        |  GPIO16 (RX2) o-----|----------o TX                |
        |                     |   1kΩ    |                   |
        |  GPIO17 (TX2) o--[1kΩ]--+-----o RX                |
        |                     |   2kΩ   |                   |
        |                     |  [2kΩ]  |                   |
        |                     |   |     |                   |
        |   GND  o------------|---+     |                   |
        +----------------------+          +-------------------+
```

The HC-05 RX pin is 5V-tolerant on some modules but its logic is 3.3V; use a 1kΩ/2kΩ voltage divider on the TX2→RX line to safely bring the ESP32's 3.3 V signal down — this is optional if your module is confirmed 3.3 V on RX, but recommended for safety.

**Code**
```cpp
#include <Arduino.h>

// Use hardware UART2 on the ESP32 to communicate with HC-05
// GPIO16 = RX2, GPIO17 = TX2
#define BT_RX 16
#define BT_TX 17

HardwareSerial BTSerial(2); // UART2

void setup() {
  // USB debug serial
  Serial.begin(115200);
  while (!Serial) { ; }
  Serial.println("ESP32 HC-05 Bluetooth UART demo");

  // HC-05 default baud rate is 9600
  BTSerial.begin(9600, SERIAL_8N1, BT_RX, BT_TX);
  Serial.println("BTSerial started on UART2 (RX=16, TX=17)");
}

void loop() {
  // Forward data received from Bluetooth to USB Serial monitor
  while (BTSerial.available()) {
    char c = (char)BTSerial.read();
    Serial.print(c);
  }

  // Forward data typed in USB Serial monitor to Bluetooth
  while (Serial.available()) {
    char c = (char)Serial.read();
    BTSerial.print(c);
  }
}
```

**How it works:** `HardwareSerial BTSerial(2)` instantiates the ESP32's second hardware UART peripheral, and passing the explicit pin numbers to `BTSerial.begin()` remaps UART2 to GPIO16/17 at runtime — this is an ESP32-specific overload that lets any UART be assigned to almost any GPIO pair. The bidirectional forwarding loop lets you test the link by typing in the Arduino Serial Monitor while a phone paired to HC-05 sends and receives data simultaneously.

The SG90 servo is controlled via a 50 Hz PWM signal, so we route its signal wire to a GPIO that supports LEDC (any general-purpose output on the ESP32) rather than relying on the classic Arduino Servo library, which does not work natively on ESP32 without the ESP32Servo wrapper.

**Wiring Table**

| Component Pin | Connects to ESP32 |
|---|---|
| VCC (Red) | 5V (VIN) |
| GND (Brown/Black) | GND |
| Signal (Orange/Yellow) | GPIO 18 |

**Wiring Diagram**
```
        +---------------------+
        |        ESP32        |
        |                     |
        |   5V (VIN) o--------+-----------> VCC  (Red)      |
        |       GND  o--------+-----------> GND  (Brown)    |  SG90 Servo
        |     GPIO18 o--------+-----------> SIG  (Orange)   |
        +---------------------+
```

The SG90 can draw up to ~600 mA stall current, so power it from the ESP32's VIN/5V pin (which passes through from USB) rather than the 3.3V regulator to avoid brownouts.

**Code**
```cpp
#include <Arduino.h>
#include <ESP32Servo.h>   // Install via Library Manager: "ESP32Servo" by Kevin Harrington

// Pin and servo object
const int SERVO_PIN = 18;
Servo myServo;

void setup() {
  Serial.begin(115200);

  // Allocate a LEDC timer channel for the servo
  // ESP32Servo defaults to 50 Hz PWM, matching SG90 requirements
  myServo.setPeriodHertz(50);            // Standard 50 Hz servo signal
  myServo.attach(SERVO_PIN, 500, 2400);  // Min/max pulse width in microseconds

  Serial.println("SG90 Servo sweep starting...");
}

void loop() {
  // Sweep from 0 to 180 degrees
  for (int angle = 0; angle <= 180; angle += 1) {
    myServo.write(angle);
    delay(15);  // Give servo time to reach position
  }

  // Sweep back from 180 to 0 degrees
  for (int angle = 180; angle >= 0; angle -= 1) {
    myServo.write(angle);
    delay(15);
  }
}
```

**How it works:** The `myServo.attach(SERVO_PIN, 500, 2400)` call is critical — it maps `write(0)` to a 500 µs pulse and `write(180)` to a 2400 µs pulse, which are the actual hardware limits of the SG90 and prevent the motor from stalling at the extremes. Unlike the standard Arduino AVR Servo library, ESP32Servo uses the ESP32's LEDC peripheral under the hood, making it compatible with the ESP32's hardware timer architecture.

A passive buzzer requires a PWM-driven square wave signal (unlike active buzzers which have an internal oscillator), so we connect its positive leg to a PWM-capable GPIO and use the Arduino `tone()` function to generate pitches.

**Wiring Table**

| Component Pin | Connects to ESP32 |
|---|---|
| + (positive) | GPIO 25 |
| - (negative) | GND |

**Wiring Diagram**
```
        +------------------+
        |      ESP32       |
        |                  |
        |        GPIO 25 o-|-------> [+] Passive
        |                  |             Buzzer
        |            GND o-|-------> [-]
        |                  |
        +------------------+
```
No current-limiting resistor is strictly required for a passive buzzer at 3.3 V logic, but adding a 100 Ω resistor in series is a safe practice to protect the GPIO.

**Code**
```cpp
#define BUZZER_PIN 25

// Note frequencies in Hz
#define NOTE_C4  262
#define NOTE_D4  294
#define NOTE_E4  330
#define NOTE_F4  349
#define NOTE_G4  392
#define NOTE_A4  440
#define NOTE_B4  494
#define NOTE_C5  523
#define REST     0

// Melody: notes and durations (ms)
int melody[] = {
  NOTE_C4, NOTE_D4, NOTE_E4, NOTE_F4,
  NOTE_G4, NOTE_G4, NOTE_A4, NOTE_A4,
  NOTE_G4, REST,    NOTE_F4, NOTE_F4,
  NOTE_E4, NOTE_E4, NOTE_D4, NOTE_D4,
  NOTE_C5
};

int durations[] = {
  200, 200, 200, 200,
  200, 200, 200, 200,
  400, 200, 200, 200,
  200, 200, 200, 200,
  400
};

const int noteCount = sizeof(melody) / sizeof(melody[0]);

void setup() {
  pinMode(BUZZER_PIN, OUTPUT);
  playMelody();
}

void loop() {
  // Replay melody every 3 seconds
  delay(3000);
  playMelody();
}

void playMelody() {
  for (int i = 0; i < noteCount; i++) {
    if (melody[i] == REST) {
      noTone(BUZZER_PIN);
    } else {
      tone(BUZZER_PIN, melody[i], durations[i]);
    }
    // Small gap between notes for clarity
    delay(durations[i] + 30);
    noTone(BUZZER_PIN);
  }
}
```

**How it works:** `tone(pin, frequency, duration)` internally configures one of the ESP32's hardware PWM channels to output a 50% duty-cycle square wave at the specified frequency, which is exactly what a passive buzzer needs to produce sound. The extra `delay(durations[i] + 30)` after each `tone()` call adds a brief silent gap between notes so the melody sounds articulated rather than slurred together.

The relay module uses a simple digital control signal, so any available GPIO on the ESP32 can drive it — just be aware the relay coil is powered separately from the ESP32's logic signal.

**Wiring Table**

| Component Pin | Connects to ESP32 |
|---|---|
| VCC | 5V (VIN) |
| GND | GND |
| IN (Signal) | GPIO 26 |

**Wiring Diagram**
```
 +------------------+          +-------------------+
 |      ESP32       |          |   Relay Module    |
 |                  |          |                   |
 |       5V (VIN) --+----------+-- VCC             |
 |             GND --+----------+-- GND             |
 |         GPIO 26 --+----------+-- IN              |
 |                  |          |                   |
 |                  |          |  [NO] [COM] [NC]  |
 +------------------+          +-------------------+
```
Most relay modules include an onboard optocoupler and flyback diode, so no additional protection components are needed on the ESP32 side; use the relay's COM/NO/NC screw terminals for switching your load.

**Code**
```cpp
#define RELAY_PIN 26

// Set to true if your relay module is active-LOW (energizes on LOW signal)
const bool ACTIVE_LOW = false;

void setup() {
  Serial.begin(115200);
  pinMode(RELAY_PIN, OUTPUT);

  // Ensure relay starts in the OFF state
  digitalWrite(RELAY_PIN, ACTIVE_LOW ? HIGH : LOW);
  Serial.println("Relay initialized. Starting blink loop...");
}

void loop() {
  // Turn relay ON
  digitalWrite(RELAY_PIN, ACTIVE_LOW ? LOW : HIGH);
  Serial.println("Relay ON");
  delay(2000);

  // Turn relay OFF
  digitalWrite(RELAY_PIN, ACTIVE_LOW ? HIGH : LOW);
  Serial.println("Relay OFF");
  delay(2000);
}
```

**How it works:** The `ACTIVE_LOW` flag lets you adapt the logic to either active-HIGH or active-LOW relay modules without restructuring the code — many cheap relay boards energize the coil when the IN pin is pulled LOW, which is the opposite of what you might expect. The relay is explicitly driven to its OFF state in `setup()` to prevent it from briefly energizing during the ESP32's boot sequence before `loop()` begins.

WS2812 strips use a single-wire timed data protocol, so only one GPIO is needed for data — a 300–500 Ω series resistor on the data line protects the first LED from signal reflections, and a large bulk capacitor (100–1000 µF) across the power rails prevents voltage spikes from damaging the strip.

**Wiring Table**

| Component Pin | Connects to ESP32 |
|---|---|
| VCC (5V) | External 5V power supply (+) |
| GND | GND (shared with ESP32 GND) |
| DIN (Data In) | GPIO5 via 330 Ω series resistor |

**Wiring Diagram**
```
 +---------------------+          +-------------------------------+
 |        ESP32        |          |     WS2812 LED Strip          |
 |                     |          |                               |
 |              GPIO5  |---[330Ω]---| DIN                         |
 |                     |          |                               |
 |             GND (*)--|----------| GND                         |
 |                     |          |                               |
 +---------------------+          |  5V  |--- External 5V PSU    |
                                  |      |                        |
                          [100µF cap across 5V and GND at strip]  |
                                  +-------------------------------+
 (* ESP32 GND tied to external PSU GND)
```
Keep the external 5V supply ground tied to the ESP32 GND; without this common ground the data signal has no reference and the strip will not respond.

**Code**
```cpp
#include <Adafruit_NeoPixel.h>

#define LED_PIN    5      // GPIO connected to DIN via 330Ω resistor
#define NUM_LEDS   30     // adjust to match your strip length
#define BRIGHTNESS 80     // 0-255; keep lower to limit current draw

Adafruit_NeoPixel strip(NUM_LEDS, LED_PIN, NEO_GRB + NEO_KHZ800);

// Define a small palette of colors to cycle through
const uint32_t colors[] = {
  strip.Color(255,   0,   0),   // Red
  strip.Color(  0, 255,   0),   // Green
  strip.Color(  0,   0, 255),   // Blue
  strip.Color(255, 165,   0),   // Orange
  strip.Color(128,   0, 128),   // Purple
  strip.Color(  0, 255, 255),   // Cyan
};
const uint8_t NUM_COLORS = sizeof(colors) / sizeof(colors[0]);

void fillStrip(uint32_t color) {
  for (int i = 0; i < strip.numPixels(); i++) {
    strip.setPixelColor(i, color);
  }
  strip.show();
}

void setup() {
  strip.begin();                // initialise the NeoPixel library
  strip.setBrightness(BRIGHTNESS);
  strip.clear();
  strip.show();                 // ensure all LEDs start OFF
}

void loop() {
  for (uint8_t c = 0; c < NUM_COLORS; c++) {
    fillStrip(colors[c]);
    delay(800);
  }

  // Simple chase effect before repeating
  strip.clear();
  for (int i = 0; i < strip.numPixels(); i++) {
    strip.setPixelColor(i, strip.Color(255, 255, 255));
    strip.show();
    delay(40);
    strip.setPixelColor(i, 0);  // turn pixel back off
  }
}
```

**How it works:** The `NEO_KHZ800` flag tells the Adafruit NeoPixel library to use the 800 kHz single-wire protocol that WS2812 LEDs expect, and `strip.show()` is the call that actually transmits the buffered color data to the strip — any `setPixelColor()` calls before it only modify an in-memory buffer and have no visible effect until `show()` is called.

A 4x4 matrix keypad uses 8 digital GPIO lines (4 rows driven as outputs, 4 columns read as inputs with pull-ups) so no additional protocol hardware is needed — just direct GPIO scanning.

**Wiring Table**

| Component Pin | Connects to ESP32 |
|---|---|
| R1 (Row 1) | GPIO 19 |
| R2 (Row 2) | GPIO 18 |
| R3 (Row 3) | GPIO 5 |
| R4 (Row 4) | GPIO 17 |
| C1 (Col 1) | GPIO 16 |
| C2 (Col 2) | GPIO 4 |
| C3 (Col 3) | GPIO 2 |
| C4 (Col 4) | GPIO 15 |

**Wiring Diagram**
```
+-------------------------+          +-------------------+
|          ESP32          |          |  4x4 Matrix Keypad|
|                         |          |                   |
|   GPIO19 (Row1) --------|----------| R1                |
|   GPIO18 (Row2) --------|----------| R2                |
|   GPIO5  (Row3) --------|----------| R3                |
|   GPIO17 (Row4) --------|----------| R4                |
|                         |          |                   |
|   GPIO16 (Col1) --------|----------| C1                |
|   GPIO4  (Col2) --------|----------| C2                |
|   GPIO2  (Col3) --------|----------| C3                |
|   GPIO15 (Col4) --------|----------| C4                |
+-------------------------+          +-------------------+
```

No external resistors are required because the ESP32's internal pull-ups are enabled on the column pins in software.

**Code**
```cpp
#include <Arduino.h>

// Row pins driven LOW one at a time
const int rowPins[4] = {19, 18, 5, 17};
// Column pins read with internal pull-ups
const int colPins[4] = {16, 4, 2, 15};

// Key map matching physical keypad layout
const char keys[4][4] = {
  {'1', '2', '3', 'A'},
  {'4', '5', '6', 'B'},
  {'7', '8', '9', 'C'},
  {'*', '0', '#', 'D'}
};

char lastKey = 0;

void setup() {
  Serial.begin(115200);

  // Rows as OUTPUT, default HIGH (inactive)
  for (int r = 0; r < 4; r++) {
    pinMode(rowPins[r], OUTPUT);
    digitalWrite(rowPins[r], HIGH);
  }

  // Columns as INPUT with internal pull-up
  for (int c = 0; c < 4; c++) {
    pinMode(colPins[c], INPUT_PULLUP);
  }

  Serial.println("4x4 Keypad ready. Press a key...");
}

char scanKeypad() {
  for (int r = 0; r < 4; r++) {
    // Pull this row LOW to activate it
    digitalWrite(rowPins[r], LOW);

    for (int c = 0; c < 4; c++) {
      if (digitalRead(colPins[c]) == LOW) {
        // Debounce: wait for release
        delay(20);
        while (digitalRead(colPins[c]) == LOW) {
          delay(5);
        }
        digitalWrite(rowPins[r], HIGH);
        return keys[r][c];
      }
    }

    // Deactivate row before moving to next
    digitalWrite(rowPins[r], HIGH);
  }
  return 0; // No key pressed
}

void loop() {
  char key = scanKeypad();
  if (key != 0) {
    Serial.print("Key pressed: ");
    Serial.println(key);
  }
}
```

**How it works:** The scanner pulls each row LOW one at a time and checks all four column pins — because the columns are held HIGH by pull-ups, a LOW reading on a column pin can only occur when a key physically bridges that row-column intersection. The blocking wait inside the key-detected branch serves as both debounce and key-release detection, preventing a single press from being reported multiple times.

Rotary encoders output two quadrature digital signals (CLK and DT) that must be read on interrupt-capable GPIO pins for accurate step detection, while the push button is read as a standard active-low digital input with internal pull-up.

**Wiring Table**

| Component Pin | Connects to ESP32 |
|---|---|
| VCC (+) | 3.3V |
| GND | GND |
| CLK (A) | GPIO 18 |
| DT (B) | GPIO 19 |
| SW (Button) | GPIO 21 |

**Wiring Diagram**
```
+----------------------+          +-------------------------+
|        ESP32         |          |    Rotary Encoder       |
|                      |          |   (with push button)    |
|     3.3V o-----------+----------o VCC                     |
|       GND o-----------+----------o GND                     |
|   GPIO18 o-----------+----------o CLK (A)                 |
|   GPIO19 o-----------+----------o DT  (B)                 |
|   GPIO21 o-----------+----------o SW  (Button)            |
+----------------------+          +-------------------------+
```
All three signal pins use the ESP32's internal pull-up resistors, so no external resistors are required as long as the encoder module does not already include them.

**Code**
```cpp
#include <Arduino.h>

#define CLK_PIN  18
#define DT_PIN   19
#define SW_PIN   21

volatile int encoderPosition = 0;
volatile bool buttonPressed  = false;

// Track last CLK state for quadrature decoding
volatile int lastCLKState;

void IRAM_ATTR handleEncoder() {
  int currentCLK = digitalRead(CLK_PIN);
  if (currentCLK != lastCLKState) {
    // If DT differs from CLK, rotation is clockwise
    if (digitalRead(DT_PIN) != currentCLK) {
      encoderPosition++;
    } else {
      encoderPosition--;
    }
    lastCLKState = currentCLK;
  }
}

void IRAM_ATTR handleButton() {
  buttonPressed = true;
}

void setup() {
  Serial.begin(115200);

  pinMode(CLK_PIN, INPUT_PULLUP);
  pinMode(DT_PIN,  INPUT_PULLUP);
  pinMode(SW_PIN,  INPUT_PULLUP);

  // Read initial CLK state before attaching interrupt
  lastCLKState = digitalRead(CLK_PIN);

  // Trigger on any edge so we catch both rising and falling transitions
  attachInterrupt(digitalPinToInterrupt(CLK_PIN), handleEncoder, CHANGE);

  // Button is active-low; trigger on falling edge (press)
  attachInterrupt(digitalPinToInterrupt(SW_PIN),  handleButton,  FALLING);

  Serial.println("Rotary Encoder Ready");
}

void loop() {
  // Safely read volatile shared variables
  noInterrupts();
  int pos     = encoderPosition;
  bool btnEvt = buttonPressed;
  if (buttonPressed) buttonPressed = false;
  interrupts();

  static int lastPos = 0;
  if (pos != lastPos) {
    Serial.print("Position: ");
    Serial.println(pos);
    lastPos = pos;
  }

  if (btnEvt) {
    Serial.println("Button Pressed!");
    delay(200); // simple software debounce
  }
}
```

**How it works:** The ISR marked `IRAM_ATTR` (placing it in fast IRAM) compares the current CLK level against the DT level on every edge change — if they differ the encoder turned clockwise, if they match it turned counter-clockwise. The `noInterrupts()`/`interrupts()` guard in `loop()` prevents a torn read of the `volatile` shared variables mid-update by the ISR.

The potentiometer's wiper (middle pin) connects to one of the ESP32's ADC-capable GPIO pins, with the outer terminals tied to 3.3V and GND to form a simple voltage divider that the ADC reads directly.

**Wiring Table**

| Component Pin | Connects to ESP32 |
|---|---|
| Left terminal (or Pin 1) | 3.3V |
| Wiper (middle pin) | GPIO34 (ADC1_CH6) |
| Right terminal (or Pin 3) | GND |

**Wiring Diagram**
```
        +------------------+
        |      ESP32       |
        |                  |
        |  3.3V o----------+----> POT Pin 1 (left)
        |                  |
        | GPIO34 o---------+----> POT Wiper (middle)
        |                  |
        |    GND o----------+----> POT Pin 3 (right)
        |                  |
        +------------------+

        Potentiometer
        +----------+
        | Pin1 [=======] Pin3 |
        |      Wiper           |
        |      (mid)           |
        +----------+
```

Use GPIO34 (or any ADC1 pin) rather than ADC2 pins, since ADC2 is shared with Wi-Fi and may give unreliable readings when Wi-Fi is active.

**Code**
```cpp
#include <Arduino.h>

const int POT_PIN = 34;       // ADC1_CH6, input-only GPIO, safe for analog reads
const int ADC_RESOLUTION = 12; // ESP32 ADC is 12-bit: 0-4095

void setup() {
  Serial.begin(115200);
  // GPIO34 is input-only by default; no pinMode needed, but explicit is fine:
  pinMode(POT_PIN, INPUT);
  analogReadResolution(ADC_RESOLUTION); // Set ADC to 12-bit resolution
  Serial.println("Potentiometer Read Example");
}

void loop() {
  int rawValue = analogRead(POT_PIN);           // 0 to 4095
  float voltage = rawValue * (3.3f / 4095.0f);  // Convert to voltage
  float percentage = (rawValue / 4095.0f) * 100.0f;

  Serial.print("Raw ADC: ");
  Serial.print(rawValue);
  Serial.print("  |  Voltage: ");
  Serial.print(voltage, 3);
  Serial.print(" V  |  Position: ");
  Serial.print(percentage, 1);
  Serial.println(" %");

  delay(200);
}
```

**How it works:** The ESP32's ADC converts the wiper voltage (0–3.3 V) into a 12-bit integer (0–4095) via `analogRead()`; dividing by 4095.0 and multiplying by 3.3 then maps that integer back to the actual voltage, giving you both a human-readable voltage and a 0–100% position value. GPIO34 is chosen specifically because it belongs to ADC1, which remains fully functional even when Wi-Fi or Bluetooth is enabled.

An LDR forms a voltage divider with a fixed resistor so the ESP32's ADC pin sees an analog voltage that varies with light intensity.

**Wiring Table**

| Component Pin | Connects to ESP32 |
|---|---|
| LDR leg 1 | 3.3V |
| LDR leg 2 | GPIO34 (ADC) and 10kΩ resistor leg 1 |
| 10kΩ resistor leg 2 | GND |

**Wiring Diagram**
```
        +3.3V
          |
        [LDR]
          |
          +--------> GPIO34 (ADC input)
          |
        [10kΩ]
          |
         GND

  +------------------+
  |      ESP32       |
  |                  |
  |  3.3V  o---------+-- LDR leg 1
  |                  |
  |  GPIO34 o--------+-- LDR leg 2 / resistor junction
  |                  |
  |  GND   o---------+-- 10kΩ to junction
  +------------------+
```
GPIO34 is input-only and has no internal pull-up, making it a clean ADC pin; keep all analog wiring away from GPIO2/GPIO0 which have boot-mode side effects.

**Code**
```cpp
#include <Arduino.h>

const int LDR_PIN = 34;        // ADC1 channel 6, input-only GPIO
const int ADC_MAX  = 4095;     // 12-bit ADC on ESP32
const float V_REF  = 3.3f;     // ADC reference voltage

void setup() {
  Serial.begin(115200);
  // GPIO34 is input-only by hardware; no pinMode call needed,
  // but we set it explicitly for clarity
  pinMode(LDR_PIN, INPUT);
  // Use 12-bit resolution (default on ESP32 Arduino core)
  analogReadResolution(12);
  Serial.println("LDR Light Sensor Ready");
}

void loop() {
  int   rawValue  = analogRead(LDR_PIN);
  float voltage   = (rawValue / (float)ADC_MAX) * V_REF;
  // Higher voltage at GPIO34 means more light (LDR resistance drops,
  // less voltage dropped across fixed 10k, more at LDR... wait:
  // LDR is top of divider, so MORE light -> lower LDR resistance
  // -> lower voltage at junction -> lower raw value)
  int   lightPct  = map(rawValue, 0, ADC_MAX, 100, 0); // invert: 0=dark,100=bright

  Serial.print("Raw ADC: ");
  Serial.print(rawValue);
  Serial.print("  Voltage: ");
  Serial.print(voltage, 3);
  Serial.print(" V  Light: ");
  Serial.print(lightPct);
  Serial.println("%");

  delay(500);
}
```

**How it works:** Because the LDR sits between 3.3V and the ADC pin while the 10kΩ pull-down goes to GND, increased light lowers the LDR's resistance and pulls the junction voltage down, so `map(rawValue, 0, ADC_MAX, 100, 0)` inverts the reading to give an intuitive 0 % (dark) to 100 % (bright) scale. `analogReadResolution(12)` is called explicitly to ensure the full 12-bit range on the ESP32 Arduino core rather than the 10-bit default used on AVR boards.

Capacitive soil moisture sensors output an analog voltage inversely proportional to soil moisture, so they connect directly to one of the ESP32's ADC-capable GPIO pins — no pull-up resistors or special protocol needed.

**Wiring Table**

| Component Pin | Connects to ESP32 |
|---|---|
| VCC | 3.3V |
| GND | GND |
| AOUT | GPIO34 (ADC1_CH6) |

**Wiring Diagram**
```
+-------------------------+          +----------------------------+
|          ESP32          |          | Capacitive Soil Moisture   |
|                         |          |          Sensor            |
|              3.3V o-----+----------+-o VCC                      |
|               GND o-----+----------+-o GND                      |
|           GPIO34 o-----+----------+-o AOUT                      |
|      (ADC1_CH6)  |          |                            |
+-------------------------+          +----------------------------+
```
Use GPIO34 (or any ADC1 pin) rather than ADC2 pins, since ADC2 is shared with Wi-Fi and can give unreliable readings when Wi-Fi is active.

**Code**
```cpp
#include <Arduino.h>

// ADC pin connected to sensor AOUT
const int SOIL_PIN = 34;

// Calibration values: adjust these by testing sensor in dry air and fully submerged in water
const int AIR_VALUE   = 3200;  // raw ADC reading in dry air (0% moisture)
const int WATER_VALUE = 1500;  // raw ADC reading submerged in water (100% moisture)

void setup() {
  Serial.begin(115200);
  // GPIO34 is input-only on ESP32, no pinMode needed, but explicit is fine
  pinMode(SOIL_PIN, INPUT);
  Serial.println("Capacitive Soil Moisture Sensor Ready");
}

void loop() {
  int rawValue = analogRead(SOIL_PIN);

  // Map raw ADC value to 0-100% moisture percentage
  // Note: higher raw value = drier soil, so we invert the mapping
  int moisturePercent = map(rawValue, AIR_VALUE, WATER_VALUE, 0, 100);
  moisturePercent = constrain(moisturePercent, 0, 100);

  Serial.print("Raw ADC: ");
  Serial.print(rawValue);
  Serial.print("  |  Moisture: ");
  Serial.print(moisturePercent);
  Serial.println("%");

  delay(1000);
}
```

**How it works:** The `map()` call inverts the relationship between raw ADC counts and moisture — because the sensor outputs a *higher* voltage (higher ADC reading) when soil is dry and a *lower* voltage when wet, the AIR_VALUE maps to 0% and WATER_VALUE maps to 100%. The `constrain()` call clamps the result so out-of-range readings (e.g., sensor held in open air during testing) never produce nonsensical negative or >100% values.

The A4988 uses two digital control lines (STEP and DIR) to drive the motor, so only two GPIOs are needed from the ESP32, but the driver's VMOT rail must be powered separately from the ESP32's 3.3 V logic supply.

**Wiring Table**

| Component Pin | Connects to ESP32 |
|---|---|
| A4988 VDD | 3.3V |
| A4988 GND (logic) | GND |
| A4988 STEP | GPIO 26 |
| A4988 DIR | GPIO 27 |
| A4988 ENABLE | GND (tie low to enable driver permanently) |
| A4988 MS1 | GND (full-step mode) |
| A4988 MS2 | GND (full-step mode) |
| A4988 MS3 | GND (full-step mode) |
| A4988 RST | A4988 SLP (tie together) |
| A4988 VMOT | External 8–35 V motor supply (+) |
| A4988 GND (power) | External motor supply (–) and ESP32 GND |
| A4988 1A, 1B | Bipolar stepper coil A leads |
| A4988 2A, 2B | Bipolar stepper coil B leads |

**Wiring Diagram**
```
+-------------------+          +---------------------+
|      ESP32        |          |       A4988          |
|                   |          |                      |
|       GPIO26 -----+----------+ STEP                 |
|       GPIO27 -----+----------+ DIR                  |
|         3.3V -----+----------+ VDD                  |
|           GND ----+----------+ GND (logic)          |
|                   |          |                      |
+-------------------+          | ENABLE --- GND       |
                               | MS1,2,3 -- GND       |
                               | RST -+- SLP          |
                               |      |               |
                               | VMOT ----[8-35V Ext] |
                               | GND(pwr)--[Ext GND]  |
                               |                      |
                               | 1A ---+              |
                               | 1B ---+ Coil A       |
                               | 2A ---+              |
                               | 2B ---+ Coil B       |
                               +---------------------+
                                         |
                               +---------------------+
                               |  Bipolar Stepper    |
                               |      Motor          |
                               +---------------------+
```
Place a 100 µF electrolytic capacitor across VMOT and GND (power) close to the A4988 to suppress voltage spikes that can destroy the driver when the motor decelerates.

**Code**
```cpp
#define STEP_PIN 26
#define DIR_PIN  27

const int STEPS_PER_REV = 200;   // typical 1.8° full-step motor
const int STEP_DELAY_US = 1000;  // microseconds between pulses (controls speed)

void stepMotor(int steps, bool clockwise) {
  digitalWrite(DIR_PIN, clockwise ? HIGH : LOW);
  for (int i = 0; i < steps; i++) {
    digitalWrite(STEP_PIN, HIGH);
    delayMicroseconds(STEP_DELAY_US);
    digitalWrite(STEP_PIN, LOW);
    delayMicroseconds(STEP_DELAY_US);
  }
}

void setup() {
  pinMode(STEP_PIN, OUTPUT);
  pinMode(DIR_PIN, OUTPUT);
  digitalWrite(STEP_PIN, LOW);
  digitalWrite(DIR_PIN, LOW);
}

void loop() {
  // Rotate one full revolution clockwise
  stepMotor(STEPS_PER_REV, true);
  delay(500);

  // Rotate one full revolution counter-clockwise
  stepMotor(STEPS_PER_REV, false);
  delay(500);
}
```

**How it works:** Each HIGH→LOW pulse on the STEP pin advances the motor exactly one step (or microstep, depending on MS pin config), so motor speed is determined entirely by the delay between pulses — shortening `STEP_DELAY_US` increases RPM. The DIR pin is set before the step loop begins because the A4988 samples direction on the rising edge of each STEP pulse, so changing it mid-sequence would cause erratic movement.

The VS1838B outputs a 3.3V-compatible active-low digital signal, so it connects directly to any interrupt-capable ESP32 GPIO without a level shifter.

**Wiring Table**

| Component Pin | Connects to ESP32 |
|---|---|
| VCC (leftmost) | 3.3V |
| GND (center) | GND |
| OUT (rightmost) | GPIO 15 |

**Wiring Diagram**
```
 +------------------+          +-------------------+
 | ESP32 | | VS1838B IR Rcvr |
 | | | |
 | 3.3V |----------+--------| VCC |
 | | | | |
 | GND |----------+--------| GND |
 | | | |
 | GPIO15 |-------------------| OUT |
 | | | |
 +------------------+ +-------------------+
```
Keep wiring short and away from noise sources; the VS1838B has a built-in bandpass filter for 38 kHz carrier, but long leads can still introduce glitches.

**Code**
```cpp
#include <Arduino.h>
#include <IRremote.hpp>

// VS1838B OUT pin connected to GPIO 15
#define IR_RECEIVE_PIN 15

void setup() {
 Serial.begin(115200);
 // Initialize IRremote receiver; last argument enables LED feedback on built-in LED
 IrReceiver.begin(IR_RECEIVE_PIN, ENABLE_LED_FEEDBACK);
 Serial.println("IR Receiver ready. Point remote and press a button.");
}

void loop() {
 if (IrReceiver.decode()) {
 // Print the protocol name and decoded value in hex
 Serial.print("Protocol : ");
 Serial.println(IrReceiver.decode_type2String(IrReceiver.decodedIRData.protocol));
 Serial.print("Address : 0x");
 Serial.println(IrReceiver.decodedIRData.address, HEX);
 Serial.print("Command : 0x");
 Serial.println(IrReceiver.decodedIRData.command, HEX);
 Serial.print("Raw value: 0x");
 Serial.println(IrReceiver.decodedIRData.decodedRawData, HEX);
 Serial.println("---");

 // MUST call resume() to receive the next signal
 IrReceiver.resume();
 }
}
```

**How it works:** `IrReceiver.begin()` attaches an interrupt to GPIO 15 that timestamps every edge of the incoming digital pulse train, letting the library reconstruct and decode the modulated NEC/Sony/RC5 frames in the background. Calling `IrReceiver.resume()` after each decode is mandatory — it rearms the interrupt-driven capture buffer so the next transmission isn't missed.

The HX711 uses a simple two-wire serial protocol (CLK and DOUT) that works on any free GPIO pins, so no dedicated hardware peripheral is needed — just pick two convenient digital pins.

**Wiring Table**

| Component Pin | Connects to ESP32 |
|---|---|
| HX711 VCC | 3.3V |
| HX711 GND | GND |
| HX711 DOUT | GPIO 16 |
| HX711 SCK | GPIO 17 |
| Load Cell E+ (Excitation+) | HX711 E+ |
| Load Cell E- (Excitation-) | HX711 E- |
| Load Cell A+ (Signal+) | HX711 A+ |
| Load Cell A- (Signal-) | HX711 A- |

**Wiring Diagram**
```
 +-------------------+         +------------------+
 |       ESP32       |         |      HX711       |
 |                   |         |                  |
 |        3.3V |-----+-------->| VCC              |
 |         GND |-----+-------->| GND              |
 |     GPIO 16 |-----+-------->| DOUT             |
 |     GPIO 17 |-----+-------->| SCK              |
 |               |         |                  |
 +-------------------+         |  E+  E-  A+  A-  |
                               +--+---+---+---+---+
                                  |   |   |   |
                            +-----+---+---+---+-----+
                            |        LOAD CELL        |
                            +-------------------------+
```

The HX711 operates at 3.3V without issue on ESP32; avoid 5V if your ESP32 board's GPIO pins are not 5V tolerant on the DOUT line.

**Code**
```cpp
#include <Arduino.h>
#include <HX711.h>

// HX711 pin definitions
const int DOUT_PIN = 16;
const int SCK_PIN  = 17;

HX711 scale;

// Calibration factor — determine this empirically with a known weight
// Positive or negative depending on load cell orientation
float calibrationFactor = 420.0f;

void setup() {
  Serial.begin(115200);
  while (!Serial) { delay(10); }

  Serial.println("HX711 Load Cell Example");

  scale.begin(DOUT_PIN, SCK_PIN);

  // Wait until the HX711 is ready
  Serial.println("Waiting for HX711...");
  while (!scale.is_ready()) {
    delay(100);
  }
  Serial.println("HX711 ready.");

  // Tare the scale (zero it out with nothing on it)
  Serial.println("Taring scale — remove all weight now.");
  delay(2000);
  scale.tare();  // Resets the scale to zero
  Serial.println("Tare complete.");

  scale.set_scale(calibrationFactor);
}

void loop() {
  if (scale.is_ready()) {
    // Average 10 readings for stability
    float weight = scale.get_units(10);
    Serial.print("Weight: ");
    Serial.print(weight, 2);
    Serial.println(" g");
  } else {
    Serial.println("HX711 not ready.");
  }

  delay(500);
}
```

**How it works:** `scale.tare()` reads the raw ADC value with no load and stores it as the zero offset, so all subsequent readings are relative to that baseline. The `calibrationFactor` scales the raw 24-bit ADC counts into real-world grams — you find this value by placing a known weight on the scale and adjusting the factor until `get_units()` matches it.

The YF-S201 outputs a 5V pulse signal, so a voltage divider or the ESP32's 5V-tolerant input pin (GPIO34 in input-only mode) is used — here we use a simple voltage divider to safely bring the signal to 3.3V logic.

**Wiring Table**

| Component Pin | Connects to ESP32 |
|---|---|
| VCC (Red) | 5V (VIN) |
| GND (Black) | GND |
| Signal (Yellow) | GPIO23 via voltage divider (10kΩ to GND, 20kΩ from signal) |

**Wiring Diagram**
```
+----------------+          +-------------------+
|   YF-S201      |          |      ESP32        |
|                |          |                   |
|  VCC (Red) o---+----------+o 5V (VIN)         |
|  GND (Blk) o---+----------+o GND              |
|                |          |                   |
|  SIG (Yel) o---+          |                   |
|                |  20kΩ    |                   |
|                +--[R1]----+o GPIO23            |
|                |          |        |           |
|                |  10kΩ    |       [R2]         |
|                +--[R2]----+o GND              |
+----------------+          +-------------------+
  (Voltage divider: 20kΩ + 10kΩ scales 5V → ~3.3V)
```
The voltage divider (20kΩ and 10kΩ) scales the 5V pulse output down to ~3.3V to protect the ESP32 GPIO input.

**Code**
```cpp
#include <Arduino.h>

#define FLOW_SENSOR_PIN 23

volatile uint32_t pulseCount = 0;
uint32_t lastPulseCount = 0;
unsigned long lastCalcTime = 0;

float flowRateLPM = 0.0;   // litres per minute
float totalVolumeLitres = 0.0;

// YF-S201 datasheet: ~7.5 pulses per second per litre/minute
const float CALIBRATION_FACTOR = 7.5;

void IRAM_ATTR onPulse() {
  pulseCount++;
}

void setup() {
  Serial.begin(115200);
  pinMode(FLOW_SENSOR_PIN, INPUT);
  attachInterrupt(digitalPinToInterrupt(FLOW_SENSOR_PIN), onPulse, RISING);
  lastCalcTime = millis();
  Serial.println("YF-S201 Water Flow Sensor Ready");
}

void loop() {
  unsigned long now = millis();
  if (now - lastCalcTime >= 1000) {
    // Safely read volatile pulse count
    noInterrupts();
    uint32_t pulses = pulseCount;
    pulseCount = 0;
    interrupts();

    float elapsedSeconds = (now - lastCalcTime) / 1000.0;
    lastCalcTime = now;

    // Calculate flow rate in litres per minute
    flowRateLPM = (pulses / CALIBRATION_FACTOR) / elapsedSeconds * 60.0;

    // Accumulate total volume
    totalVolumeLitres += (pulses / CALIBRATION_FACTOR) / 60.0;

    Serial.print("Flow Rate: ");
    Serial.print(flowRateLPM, 2);
    Serial.print(" L/min  |  Total Volume: ");
    Serial.print(totalVolumeLitres, 4);
    Serial.println(" L");
  }
}
```

**How it works:** The ISR marked `IRAM_ATTR` runs from internal RAM so it isn't blocked by flash reads, ensuring no pulses are missed; `noInterrupts()`/`interrupts()` guards the atomic read-and-reset of `pulseCount` to prevent a race condition between the ISR and the main loop. The calibration factor of 7.5 (pulses per litre/minute) converts raw pulse frequency directly into a flow rate in litres per minute as specified in the YF-S201 datasheet.

