The PN532 supports I2C, SPI, and UART; selecting I2C keeps the wiring minimal and uses the ESP32's hardware I2C peripheral on GPIO 21/22, but the PN532 board's interface-select jumpers (or solder bridges) must be set to I2C mode before powering up.

**Wiring Table**

| Component Pin | Connects to ESP32 |
|---|---|
| VCC | 3.3V |
| GND | GND |
| SDA | GPIO 21 |
| SCL | GPIO 22 |
| IRQ | GPIO 4 |
| RSTO | GPIO 5 |

**Wiring Diagram**
```
        +---------------------+          +-------------------+
        |        ESP32        |          |    PN532 NFC      |
        |                     |          |  (I2C mode set)   |
        |       3.3V  o-------+----------o VCC               |
        |        GND  o-------+----------o GND               |
        |  GPIO21/SDA o-------+----------o SDA               |
        |  GPIO22/SCL o-------+----------o SCL               |
        |      GPIO4  o-------+----------o IRQ               |
        |      GPIO5  o-------+----------o RSTO              |
        +---------------------+          +-------------------+
```
The PN532 runs on 3.3V only on most breakout boards — verify your module's silkscreen before connecting to 5V.

**Code**
```cpp
#include <Wire.h>
#include <Adafruit_PN532.h>

// IRQ and RESET pins for I2C mode
#define PN532_IRQ   4
#define PN532_RESET 5

// Construct with IRQ and RESET; Wire (I2C) is used automatically
Adafruit_PN532 nfc(PN532_IRQ, PN532_RESET);

void setup() {
  Serial.begin(115200);
  while (!Serial) { delay(10); }

  Serial.println("PN532 NFC Reader — I2C mode");

  // SDA=21, SCL=22 are the ESP32 hardware I2C defaults
  Wire.begin(21, 22);

  nfc.begin();

  uint32_t versiondata = nfc.getFirmwareVersion();
  if (!versiondata) {
    Serial.println("ERROR: PN532 not found. Check wiring and I2C jumpers.");
    while (true) { delay(10); }
  }

  Serial.print("Found PN532 chip, firmware version: ");
  Serial.print((versiondata >> 16) & 0xFF);
  Serial.print('.');
  Serial.println((versiondata >> 8) & 0xFF);

  // Configure to read MiFare cards
  nfc.SAMConfig();
  Serial.println("Waiting for NFC tag...");
}

void loop() {
  uint8_t uid[7];      // Buffer to store UID (up to 7 bytes)
  uint8_t uidLength;   // Actual UID length returned

  // Returns true when a card is detected; blocks until timeout
  bool success = nfc.readPassiveTargetID(
      PN532_MIFARE_ISO14443A, uid, &uidLength, 1000);

  if (success) {
    Serial.print("Tag detected! UID (");
    Serial.print(uidLength);
    Serial.print(" bytes): ");
    for (uint8_t i = 0; i < uidLength; i++) {
      if (uid[i] < 0x10) Serial.print('0');  // leading zero
      Serial.print(uid[i], HEX);
      if (i < uidLength - 1) Serial.print(':');
    }
    Serial.println();
    delay(1500);  // debounce: avoid re-reading same tag immediately
  }
}
```

**How it works:** The `Adafruit_PN532` constructor variant that takes IRQ and RESET pins (rather than CS or no arguments) automatically selects I2C transport, using whichever `Wire` instance was started — so calling `Wire.begin(21, 22)` before `nfc.begin()` is what routes communication through the ESP32's hardware I2C peripheral. The `readPassiveTargetID` call with a 1000 ms timeout drives the IRQ line low when a tag enters the field, avoiding the need to poll the I2C bus continuously.

