Make sure the external motor power supply's GND is connected to the Arduino GND to create a common ground reference; without this, the direction signals will not be interpreted correctly by the L298N.

**Code**
```cpp
// L298N DC Motor Control
// ENA -> D9 (PWM), IN1 -> D7, IN2 -> D8

const int ENA = 9;
const int IN1 = 7;
const int IN2 = 8;

void setup() {
  pinMode(ENA, OUTPUT);
  pinMode(IN1, OUTPUT);
  pinMode(IN2, OUTPUT);
  Serial.begin(9600);
  Serial.println("L298N Motor Driver Ready");
}

void motorForward(int speed) {
  // speed: 0-255
  digitalWrite(IN1, HIGH);
  digitalWrite(IN2, LOW);
  analogWrite(ENA, speed);
}

void motorBackward(int speed) {
  // speed: 0-255
  digitalWrite(IN1, LOW);
  digitalWrite(IN2, HIGH);
  analogWrite(ENA, speed);
}

void motorStop() {
  digitalWrite(IN1, LOW);
  digitalWrite(IN2, LOW);
  analogWrite(ENA, 0);
}

void loop() {
  Serial.println("Forward at full speed");
  motorForward(255);
  delay(2000);

  Serial.println("Slowing down");
  motorForward(100);
  delay(2000);

  Serial.println("Stop");
  motorStop();
  delay(1000);

  Serial.println("Backward at full speed");
  motorBackward(255);
  delay(2000);

  Serial.println("Stop");
  motorStop();
  delay(1000);
}
```

**How it works:** The IN1/IN2 pin combination determines spin direction — HIGH/LOW drives forward while LOW/HIGH drives backward — and `analogWrite()` on the ENA pin sets the motor's duty cycle (0–255), giving smooth variable speed control through the L298N's built-in H-bridge.

The MPU6050 communicates over I2C and runs on 3.3V logic internally, but most breakout boards include an onboard regulator and level shifter making them 5V-safe, so it connects directly to the Uno's A4/A5 I2C bus without additional components.

**Wiring Table**

| Component Pin | Connects to Arduino Uno |
|---|---|
| VCC | 5V pin |
| GND | GND |
| SDA | A4 (I2C SDA) |
| SCL | A5 (I2C SCL) |
| AD0 | GND (sets I2C address to 0x68) |
| INT | (not connected for basic polling) |

**Wiring Diagram**
```
+-------------------------+          +-------------------+
|       Arduino Uno       |          |     MPU6050       |
|                         |          |                   |
|  5V  -------------------|----------| VCC               |
|  GND -------------------|----------| GND               |
|  A4 (SDA) -------------|----------| SDA               |
|  A5 (SCL) -------------|----------| SCL               |
|                         |    GND --| AD0  (addr 0x68)  |
+-------------------------+          +-------------------+
```

Keep I2C wires short (under 20 cm) to avoid signal integrity issues at 400 kHz fast-mode; the Uno's internal Wire library defaults to 100 kHz which is perfectly reliable at typical bench wire lengths.

**Code**
```cpp
#include <Wire.h>

const uint8_t MPU_ADDR = 0x68;  // AD0 tied to GND

// Raw sensor data
int16_t accelX, accelY, accelZ;
int16_t gyroX,  gyroY,  gyroZ;
int16_t temperature;

void mpu6050Init() {
  Wire.beginTransmission(MPU_ADDR);
  Wire.write(0x6B);  // PWR_MGMT_1 register
  Wire.write(0x00);  // Clear sleep bit -- wake the device
  Wire.endTransmission(true);

  // Optional: set gyro full-scale range to +/-250 deg/s (default)
  Wire.beginTransmission(MPU_ADDR);
  Wire.write(0x1B);  // GYRO_CONFIG register
  Wire.write(0x00);
  Wire.endTransmission(true);

  // Optional: set accel full-scale range to +/-2g (default)
  Wire.beginTransmission(MPU_ADDR);
  Wire.write(0x1C);  // ACCEL_CONFIG register
  Wire.write(0x00);
  Wire.endTransmission(true);
}

void readMPU6050() {
  // Burst-read 14 bytes starting at ACCEL_XOUT_H (0x3B)
  Wire.beginTransmission(MPU_ADDR);
  Wire.write(0x3B);
  Wire.endTransmission(false);  // Repeated start -- keep bus active
  Wire.requestFrom((uint8_t)MPU_ADDR, (uint8_t)14, (uint8_t)true);

  accelX      = (Wire.read() << 8) | Wire.read();
  accelY      = (Wire.read() << 8) | Wire.read();
  accelZ      = (Wire.read() << 8) | Wire.read();
  temperature = (Wire.read() << 8) | Wire.read();
  gyroX       = (Wire.read() << 8) | Wire.read();
  gyroY       = (Wire.read() << 8) | Wire.read();
  gyroZ       = (Wire.read() << 8) | Wire.read();
}

void setup() {
  Serial.begin(115200);
  Wire.begin();
  mpu6050Init();
  Serial.println("MPU6050 ready");
}

void loop() {
  readMPU6050();

  // Convert raw accel to g (LSB sensitivity = 16384 at +/-2g range)
  float ax = accelX / 16384.0f;
  float ay = accelY / 16384.0f;
  float az = accelZ / 16384.0f;

  // Convert raw gyro to deg/s (LSB sensitivity = 131 at +/-250 deg/s range)
  float gx = gyroX / 131.0f;
  float gy = gyroY / 131.0f;
  float gz = gyroZ / 131.0f;

  // Convert raw temp: Temp_degC = RawTemp/340.0 + 36.53
  float tempC = temperature / 340.0f + 36.53f;

  Serial.print("Accel (g)  X: "); Serial.print(ax, 3);
  Serial.print("  Y: ");          Serial.print(ay, 3);
  Serial.print("  Z: ");          Serial.println(az, 3);

  Serial.print("Gyro (d/s) X: "); Serial.print(gx, 2);
  Serial.print("  Y: ");          Serial.print(gy, 2);
  Serial.print("  Z: ");          Serial.println(gz, 2);

  Serial.print("Temp (C): ");     Serial.println(tempC, 1);
  Serial.println();

  delay(200);
}
```

**How it works:** Writing `0x00` to register `0x6B` (PWR_MGMT_1) is mandatory — the MPU6050 powers up in sleep mode and will return all-zero data until this wake-up write is performed. The burst read starting at register `0x3B` with `endTransmission(false)` issues a repeated-start condition so the bus isn't released between the register address write and the data read, which is required by the MPU6050's register map to guarantee all 14 bytes come from the same sample snapshot.

The BMP280 communicates over I2C and its module typically includes an onboard voltage regulator, making it safe to power from either 3.3V or 5V, though logic lines connect directly to the Uno's A4/A5 I2C bus.

**Wiring Table**

| Component Pin | Connects to Arduino Uno |
|---|---|
| VCC | 3.3V pin |
| GND | GND |
| SDA | A4 (SDA) |
| SCL | A5 (SCL) |
| CSB | 3.3V (ties high to force I2C mode) |
| SDO | GND (sets I2C address to 0x76) |

**Wiring Diagram**
```
  +------------------+          +-------------------+
  |   Arduino Uno    |          |      BMP280        |
  |                  |          |                    |
  |       3.3V pin --+----------+-- VCC              |
  |           GND --+----------+-- GND              |
  |        A4 SDA --+----------+-- SDA              |
  |        A5 SCL --+----------+-- SCL              |
  |                  |          |                    |
  |                  |    3.3V--+-- CSB (I2C mode)  |
  |                  |     GND--+-- SDO (addr 0x76) |
  +------------------+          +-------------------+
```

Tying SDO to GND sets the I2C address to 0x76; pulling it high instead would set the address to 0x77, which is useful if two BMP280s share the same bus.

**Code**
```cpp
#include <Wire.h>
#include <Adafruit_BMP280.h>

Adafruit_BMP280 bmp; // uses I2C by default

void setup() {
  Serial.begin(9600);
  while (!Serial); // wait for Serial Monitor to open

  if (!bmp.begin(0x76)) {
    Serial.println("Could not find BMP280 at 0x76. Check wiring!");
    while (1); // halt if sensor not found
  }

  // Recommended settings for weather monitoring
  bmp.setSampling(Adafruit_BMP280::MODE_NORMAL,
                  Adafruit_BMP280::SAMPLING_X2,   // temperature oversampling
                  Adafruit_BMP280::SAMPLING_X16,  // pressure oversampling
                  Adafruit_BMP280::FILTER_X16,    // IIR filter
                  Adafruit_BMP280::STANDBY_MS_500); // standby time

  Serial.println("BMP280 initialized successfully.");
}

void loop() {
  float temperatureC = bmp.readTemperature();       // degrees Celsius
  float pressurePa   = bmp.readPressure();          // Pascals
  float altitudeM    = bmp.readAltitude(1013.25);   // meters, std sea-level pressure

  Serial.print("Temperature: ");
  Serial.print(temperatureC, 2);
  Serial.println(" °C");

  Serial.print("Pressure: ");
  Serial.print(pressurePa / 100.0, 2); // convert Pa to hPa
  Serial.println(" hPa");

  Serial.print("Altitude: ");
  Serial.print(altitudeM, 2);
  Serial.println(" m");

  Serial.println("----------");
  delay(2000);
}
```

**How it works:** The `bmp.setSampling()` call configures the BMP280's internal oversampling and IIR filter registers before readings begin, which significantly reduces noise on the pressure output without requiring any software averaging. Passing `1013.25` to `readAltitude()` sets the reference sea-level pressure in hPa; adjusting this to your local station pressure will give a more accurate absolute altitude estimate.

A common cathode RGB LED needs its three color pins on PWM-capable outputs so analogWrite() can blend any color; the shared cathode goes to GND through a current-limiting resistor on each channel.

**Wiring Table**

| Component Pin | Connects to Arduino Uno |
|---|---|
| R (Red anode) | D9 (via 220Ω resistor) |
| G (Green anode) | D10 (via 220Ω resistor) |
| B (Blue anode) | D11 (via 220Ω resistor) |
| Cathode (longest leg) | GND |

**Wiring Diagram**
```
+------------------+          +-------------------+
|   Arduino Uno    |          |  Common Cathode   |
|                  |          |     RGB LED       |
|  D9 (PWM)  o----[220Ω]---->| R anode           |
|                  |          |                   |
|  D10 (PWM) o----[220Ω]---->| G anode           |
|                  |          |                   |
|  D11 (PWM) o----[220Ω]---->| B anode           |
|                  |          |                   |
|  GND       o----|---------->| Cathode (GND)     |
+------------------+          +-------------------+
```
Each color channel needs its own 220Ω series resistor to limit current to a safe ~20 mA from the 5V rail.

**Code**
```cpp
// RGB LED PWM color mixing on Arduino Uno
// Common cathode: higher analogWrite value = brighter channel

const int RED_PIN   = 9;
const int GREEN_PIN = 10;
const int BLUE_PIN  = 11;

void setColor(uint8_t r, uint8_t g, uint8_t b) {
  analogWrite(RED_PIN,   r);
  analogWrite(GREEN_PIN, g);
  analogWrite(BLUE_PIN,  b);
}

void setup() {
  pinMode(RED_PIN,   OUTPUT);
  pinMode(GREEN_PIN, OUTPUT);
  pinMode(BLUE_PIN,  OUTPUT);
  setColor(0, 0, 0); // start off
}

void loop() {
  // Red
  setColor(255, 0, 0);
  delay(1000);

  // Green
  setColor(0, 255, 0);
  delay(1000);

  // Blue
  setColor(0, 0, 255);
  delay(1000);

  // Yellow (R + G)
  setColor(255, 200, 0);
  delay(1000);

  // Cyan (G + B)
  setColor(0, 255, 255);
  delay(1000);

  // Magenta (R + B)
  setColor(255, 0, 255);
  delay(1000);

  // White (all channels)
  setColor(255, 255, 255);
  delay(1000);

  // Fade red in and out
  for (int i = 0; i <= 255; i++) {
    setColor(i, 0, 0);
    delay(8);
  }
  for (int i = 255; i >= 0; i--) {
    setColor(i, 0, 0);
    delay(8);
  }
}
```

**How it works:** `analogWrite()` outputs a PWM signal whose 0–255 duty cycle controls perceived brightness for each color channel independently, allowing any RGB mix by varying the three values together. Pins D9, D10, and D11 are all hardware PWM-capable on the Uno's ATmega328P, so no software PWM overhead is needed.

A transistor (NPN, e.g. 2N2222 or PN2222) is used as a low-side switch between the Arduino's digital output and the motor, since the motor draws more current than any GPIO pin can safely supply directly.

**Wiring Table**

| Component Pin | Connects to Arduino Uno |
|---|---|
| Motor (+) lead | 5V pin |
| Motor (−) lead | Transistor Collector |
| Transistor Base | D9 (via 1kΩ resistor) |
| Transistor Emitter | GND |
| Flyback diode Anode | Transistor Collector (motor − lead) |
| Flyback diode Cathode | 5V pin (motor + lead) |

**Wiring Diagram**
```
+------------------+          1kΩ
|   Arduino Uno    |        +------+
|                  |        |      |
|              D9  |--------+    [Base]
|                  |           [2N2222 NPN]
|              5V  |----+      [Collector]----[Motor−]
|                  |    |      [Emitter]            |
|             GND  |--+ |          |                |
+------------------+  | |         GND    [Motor+]---+
                      | |                    |
                      | +--------------------+
                      |         (1N4001 flyback diode
                      |          cathode→5V, anode→Collector)
                      +---------[Emitter]
```

Always place a 1N4001 (or similar) flyback diode across the motor terminals — cathode to the motor's positive side — to suppress the voltage spike generated when the inductive motor coil is switched off.

**Code**
```cpp
const int MOTOR_PIN = 9; // PWM-capable pin drives transistor base via 1kΩ resistor

void setup() {
  pinMode(MOTOR_PIN, OUTPUT);
  digitalWrite(MOTOR_PIN, LOW); // ensure motor is off at startup
}

void loop() {
  // Buzz on for 500ms
  digitalWrite(MOTOR_PIN, HIGH);
  delay(500);

  // Buzz off for 500ms
  digitalWrite(MOTOR_PIN, LOW);
  delay(500);

  // Example: fade vibration intensity using PWM
  for (int power = 0; power <= 255; power += 5) {
    analogWrite(MOTOR_PIN, power);
    delay(20);
  }
  delay(300);

  for (int power = 255; power >= 0; power -= 5) {
    analogWrite(MOTOR_PIN, power);
    delay(20);
  }
  delay(500);
}
```

**How it works:** Because D9 is PWM-capable, `analogWrite()` lets you vary the motor's average voltage (and thus vibration intensity) by duty-cycling the transistor's base signal — the transistor amplifies this low-current PWM signal into the higher current the motor actually needs. The flyback diode is critical: without it, the collapsing magnetic field in the motor coil would generate a large reverse-voltage spike that could destroy the transistor and potentially the Arduino.

A reed switch is a passive mechanical component, so it only needs a digital GPIO pin with the internal pull-up resistor enabled — no external power rail is required beyond the logic pin itself.

**Wiring Table**

| Component Pin | Connects to Arduino Uno |
|---|---|
| Terminal 1 | D2 |
| Terminal 2 | GND |

**Wiring Diagram**
```
+------------------+          +-------------------+
|   Arduino Uno    |          |    Reed Switch    |
|                  |          |                   |
|               D2 |----------| Terminal 1        |
|                  |          | Terminal 2        |
|              GND |----------+-------------------+
|                  |
+------------------+
```
With the internal pull-up active, the pin reads HIGH when the switch is open and LOW when a magnet closes the contacts — no external resistor needed.

**Code**
```cpp
const int REED_PIN = 2;
const int LED_PIN  = 13;  // onboard LED

void setup() {
  Serial.begin(9600);
  pinMode(REED_PIN, INPUT_PULLUP);  // internal pull-up keeps pin HIGH when switch open
  pinMode(LED_PIN, OUTPUT);
}

void loop() {
  int state = digitalRead(REED_PIN);

  if (state == LOW) {
    // Magnet present: switch contacts closed, pin pulled to GND
    digitalWrite(LED_PIN, HIGH);
    Serial.println("Magnet detected — switch CLOSED");
  } else {
    // No magnet: switch open, pin held HIGH by pull-up
    digitalWrite(LED_PIN, LOW);
    Serial.println("No magnet — switch OPEN");
  }

  delay(200);
}
```

**How it works:** `INPUT_PULLUP` enables the ATmega328P's built-in ~20–50 kΩ pull-up resistor, so the pin sits at HIGH with no external components; when a magnet closes the reed switch, Terminal 2 connects the pin directly to GND and the reading flips to LOW, making the logic inverted (LOW = magnet present).

A hall effect sensor outputs a digital HIGH or LOW signal depending on magnetic field presence, so it connects to any standard GPIO pin with an internal pull-up resistor to stabilize the idle state.

**Wiring Table**

| Component Pin | Connects to Arduino Uno |
|---|---|
| VCC | 5V pin |
| GND | GND pin |
| OUT (signal) | D2 |

**Wiring Diagram**
```
+----------------+          +-------------------+
|   Arduino Uno  |          |  Hall Effect Sensor|
|                |          |                   |
|            5V  |----------| VCC               |
|           GND  |----------| GND               |
|            D2  |----------| OUT               |
+----------------+          +-------------------+
```
Many hall effect sensor modules have an onboard pull-up resistor on the OUT line, but enabling Arduino's internal pull-up as well ensures a clean HIGH signal when no magnet is detected.

**Code**
```cpp
const int HALL_PIN = 2;
const int LED_PIN  = 13;

void setup() {
  Serial.begin(9600);
  pinMode(HALL_PIN, INPUT_PULLUP); // enable internal pull-up for clean idle HIGH
  pinMode(LED_PIN, OUTPUT);
}

void loop() {
  int sensorState = digitalRead(HALL_PIN);

  // Most hall effect sensors are active-LOW: OUTPUT goes LOW when magnet is detected
  if (sensorState == LOW) {
    Serial.println("Magnet detected!");
    digitalWrite(LED_PIN, HIGH);
  } else {
    Serial.println("No magnet.");
    digitalWrite(LED_PIN, LOW);
  }

  delay(200);
}
```

**How it works:** `INPUT_PULLUP` keeps the signal line at a known HIGH level when no magnet is present, which is essential because hall effect sensors are open-collector/open-drain devices that only actively pull the line LOW when triggered. The active-LOW logic means the condition `sensorState == LOW` is what indicates magnet detection, which is the opposite of what many beginners expect.

The MQ-2 outputs an analog voltage proportional to gas/smoke concentration, so it connects directly to one of the Uno's analog input pins without any protocol overhead.

**Wiring Table**

| Component Pin | Connects to Arduino Uno |
|---|---|
| VCC | 5V pin |
| GND | GND |
| AO (Analog Out) | A0 |
| DO (Digital Out) | Not connected (optional: D7) |

**Wiring Diagram**
```
+------------------+          +-------------------+
|   Arduino Uno    |          |     MQ-2 Sensor   |
|                  |          |                   |
|               5V |----------| VCC               |
|              GND |----------| GND               |
|               A0 |----------| AO (Analog Out)   |
|                  |          | DO  (not used)    |
+------------------+          +-------------------+
```

Allow the MQ-2 sensor a 20–30 second warm-up time after power-on before trusting readings, as the heating element must stabilize; the raw ADC value will drift noticeably during this period.

**Code**
```cpp
#include <Arduino.h>

const int MQ2_ANALOG_PIN = A0;
const int WARMUP_MS = 30000;      // 30-second sensor warm-up
const int SMOKE_THRESHOLD = 400;  // ADC counts (0–1023); tune for your environment

void setup() {
  Serial.begin(9600);
  Serial.println("MQ-2 Gas/Smoke Sensor");
  Serial.println("Warming up sensor, please wait 30 seconds...");
  delay(WARMUP_MS);
  Serial.println("Warm-up complete. Reading sensor.");
}

void loop() {
  int rawValue = analogRead(MQ2_ANALOG_PIN);

  // Convert raw ADC reading to approximate voltage
  float voltage = rawValue * (5.0f / 1023.0f);

  Serial.print("Raw ADC: ");
  Serial.print(rawValue);
  Serial.print("  |  Voltage: ");
  Serial.print(voltage, 2);
  Serial.print(" V  |  Status: ");

  if (rawValue >= SMOKE_THRESHOLD) {
    Serial.println("*** GAS / SMOKE DETECTED ***");
  } else {
    Serial.println("Clean air");
  }

  delay(1000);
}
```

**How it works:** `analogRead(A0)` returns a 10-bit value (0–1023) scaled to 0–5 V, where higher values indicate greater gas concentration; the `SMOKE_THRESHOLD` constant is the single tuning point you adjust in your specific environment to distinguish clean air from a detected event, since the MQ-2's sensitivity varies with gas type and ambient conditions.

The DHT22 uses a single-wire digital protocol requiring a 10kΩ pull-up resistor on the data line; D5 is chosen here as a safe general-purpose GPIO that avoids boot-strapping concerns.

**Wiring Table**

| Component Pin | Connects to ESP8266 NodeMCU |
|---|---|
| VCC | 3.3V |
| GND | GND |
| DATA | D5 (GPIO14) via 10kΩ pull-up resistor to 3.3V |

**Wiring Diagram**
```
  ESP8266 NodeMCU                     DHT22
 +----------------+                +----------+
 |           3.3V |---+----------->| VCC      |
 |                |   |            |          |
 |            GND |---+----------->| GND      |
 |                |   |            |          |
 |             D5 |---+--[10kΩ]--+ | DATA     |
 |                |              | +----------+
 |                |              |
 |                |      pull-up to 3.3V
 +----------------+
```

The pull-up resistor must connect from the DATA line to 3.3V (not 5V), since the NodeMCU operates at 3.3V logic levels.

**Code**
```cpp
#include <Arduino.h>
#include <DHT.h>

#define DHTPIN D5
#define DHTTYPE DHT22

DHT dht(DHTPIN, DHTTYPE);

void setup() {
  Serial.begin(115200);
  delay(1000); // Allow Serial to initialize
  dht.begin();
  Serial.println("DHT22 sensor initialized.");
}

void loop() {
  // DHT22 needs at least 2 seconds between readings
  delay(2000);

  float humidity = dht.readHumidity();
  float temperatureC = dht.readTemperature();     // Celsius by default
  float temperatureF = dht.readTemperature(true); // Pass true for Fahrenheit

  // Check if any read failed
  if (isnan(humidity) || isnan(temperatureC)) {
    Serial.println("ERROR: Failed to read from DHT22! Check wiring and pull-up resistor.");
    return;
  }

  float heatIndexC = dht.computeHeatIndex(temperatureC, humidity, false);
  float heatIndexF = dht.computeHeatIndex(temperatureF, humidity);

  Serial.print("Humidity:       ");
  Serial.print(humidity);
  Serial.println(" %");

  Serial.print("Temperature:    ");
  Serial.print(temperatureC);
  Serial.print(" °C  /  ");
  Serial.print(temperatureF);
  Serial.println(" °F");

  Serial.print("Heat Index:     ");
  Serial.print(heatIndexC);
  Serial.print(" °C  /  ");
  Serial.print(heatIndexF);
  Serial.println(" °F");

  Serial.println("---");
}
```

**How it works:** The `isnan()` check after each read is essential because the DHT22's single-wire protocol can fail silently — if the pull-up resistor is missing or the timing is off, `readHumidity()` and `readTemperature()` return `NaN` rather than crashing, so you must explicitly guard against it. The mandatory `delay(2000)` between readings respects the DHT22's maximum sampling rate of 0.5 Hz; polling faster than this causes the sensor to return stale or corrupt data.

The BMP280 uses I2C at 3.3V, so it connects directly to the NodeMCU's default I2C bus on D2 (SDA) and D1 (SCL) without any level shifting.

**Wiring Table**

| Component Pin | Connects to ESP8266 NodeMCU |
|---|---|
| VCC | 3.3V |
| GND | GND |
| SDA | D2 (GPIO4) |
| SCL | D1 (GPIO5) |
| SDO | GND (sets I2C address to 0x76) |
| CSB | 3.3V (forces I2C mode) |

**Wiring Diagram**
```
+-------------------+          +-------------------+
|   ESP8266 NodeMCU |          |      BMP280       |
|                   |          |                   |
|               3V3 |----------| VCC               |
|               GND |----------| GND               |
|       D2 (GPIO4)  |----------| SDA               |
|       D1 (GPIO5)  |----------| SCL               |
|                   |     GND -| SDO  (addr 0x76)  |
|                   |    3.3V -| CSB  (I2C mode)   |
+-------------------+          +-------------------+
```

Keep CSB tied to 3.3V to lock the BMP280 into I2C mode; leaving it floating can cause unreliable communication.

**Code**
```cpp
#include <Wire.h>
#include <Adafruit_BMP280.h>

// BMP280 I2C address is 0x76 when SDO is pulled LOW
Adafruit_BMP280 bmp;

void setup() {
  Serial.begin(115200);
  Wire.begin(D2, D1); // SDA=D2, SCL=D1

  if (!bmp.begin(0x76)) {
    Serial.println("BMP280 not found! Check wiring and I2C address.");
    while (1) delay(10);
  }

  // Recommended settings for weather monitoring
  bmp.setSampling(
    Adafruit_BMP280::MODE_NORMAL,
    Adafruit_BMP280::SAMPLING_X2,   // temperature oversampling
    Adafruit_BMP280::SAMPLING_X16,  // pressure oversampling
    Adafruit_BMP280::FILTER_X16,    // IIR filter
    Adafruit_BMP280::STANDBY_MS_500 // standby time
  );

  Serial.println("BMP280 initialized.");
}

void loop() {
  float temperatureC = bmp.readTemperature();   // degrees Celsius
  float pressureHPa  = bmp.readPressure() / 100.0F; // convert Pa to hPa
  float altitudeM    = bmp.readAltitude(1013.25);    // std sea-level pressure

  Serial.print("Temperature: ");
  Serial.print(temperatureC);
  Serial.println(" °C");

  Serial.print("Pressure: ");
  Serial.print(pressureHPa);
  Serial.println(" hPa");

  Serial.print("Approx Altitude: ");
  Serial.print(altitudeM);
  Serial.println(" m");

  Serial.println("---");
  delay(2000);
}
```

**How it works:** `Wire.begin(D2, D1)` explicitly sets the I2C pins using NodeMCU silkscreen labels rather than raw GPIO numbers, which is required for the board variant to map them correctly. Dividing `readPressure()` by 100.0F converts the raw Pascal value returned by the library into the more human-readable hectopascal (hPa) unit commonly used in weather applications.

The SSD1306 OLED uses I2C, so it shares the NodeMCU's default SDA/SCL bus pins (D2 and D1), keeping the wiring minimal with just four wires.

**Wiring Table**

| Component Pin | Connects to ESP8266 NodeMCU |
|---|---|
| VCC | 3.3V |
| GND | GND |
| SDA | D2 (GPIO4) |
| SCL | D1 (GPIO5) |

**Wiring Diagram**
```
+-------------------+          +-------------------+
|   ESP8266 NodeMCU |          |   SSD1306 OLED    |
|                   |          |                   |
|               3V3 |----------| VCC               |
|               GND |----------| GND               |
|       D2 (GPIO4)  |----------| SDA               |
|       D1 (GPIO5)  |----------| SCL               |
+-------------------+          +-------------------+
```
The SSD1306 module typically operates at 3.3V; verify your specific board's VCC tolerance before connecting to 5V.

**Code**
```cpp
#include <Wire.h>
#include <Adafruit_GFX.h>
#include <Adafruit_SSD1306.h>

#define SCREEN_WIDTH 128
#define SCREEN_HEIGHT 64
#define OLED_RESET    -1        // No reset pin used
#define OLED_I2C_ADDR 0x3C

Adafruit_SSD1306 display(SCREEN_WIDTH, SCREEN_HEIGHT, &Wire, OLED_RESET);

void setup() {
  Serial.begin(115200);

  // SDA = D2 (GPIO4), SCL = D1 (GPIO5) -- NodeMCU default I2C pins
  Wire.begin(D2, D1);

  if (!display.begin(SSD1306_SWITCHCAPVCC, OLED_I2C_ADDR)) {
    Serial.println(F("SSD1306 allocation failed -- check wiring and I2C address"));
