|  3.3V               |          |                   |
|  GND                |          |                   |
+---------------------+          +-------------------+
```

No external resistors are required because the Teensy's internal pull-ups are enabled on the column pins.

**Code**
```cpp
// 4x4 Matrix Keypad scanner for Teensy 4.0
// Rows are driven LOW one at a time; columns are read with INPUT_PULLUP.

const int ROW_PINS[4] = {2, 3, 4, 5};
const int COL_PINS[4] = {6, 7, 8, 9};

// Key map matching physical keypad layout
const char KEY_MAP[4][4] = {
  {'1', '2', '3', 'A'},
  {'4', '5', '6', 'B'},
  {'7', '8', '9', 'C'},
  {'*', '0', '#', 'D'}
};

void setup() {
  Serial.begin(115200);
  while (!Serial && millis() < 3000);  // wait for Serial on Teensy

  // Rows: OUTPUT, default HIGH (inactive)
  for (int r = 0; r < 4; r++) {
    pinMode(ROW_PINS[r], OUTPUT);
    digitalWrite(ROW_PINS[r], HIGH);
  }

  // Columns: INPUT with internal pull-up
  for (int c = 0; c < 4; c++) {
    pinMode(COL_PINS[c], INPUT_PULLUP);
  }

  Serial.println("4x4 Keypad ready. Press a key...");
}

char scanKeypad() {
  for (int r = 0; r < 4; r++) {
    // Drive current row LOW
    digitalWrite(ROW_PINS[r], LOW);

    for (int c = 0; c < 4; c++) {
      if (digitalRead(COL_PINS[c]) == LOW) {
        // Debounce: wait for release
        delay(20);
        while (digitalRead(COL_PINS[c]) == LOW);
        digitalWrite(ROW_PINS[r], HIGH);
        return KEY_MAP[r][c];
      }
    }

    // Restore row to HIGH before moving to next
    digitalWrite(ROW_PINS[r], HIGH);
  }
  return '\0';  // no key pressed
}

void loop() {
  char key = scanKeypad();
  if (key != '\0') {
    Serial.print("Key pressed: ");
    Serial.println(key);
  }
}
```

**How it works:** Each row pin is pulled LOW in turn while all others stay HIGH — if a key is held down, the column connected through that key's switch is pulled LOW through the closed contact, revealing which (row, col) intersection is active. The debounce `while` loop waits for the physical contact to stop bouncing before returning, preventing a single press from registering multiple times.

The HX711 uses a simple two-wire clocked serial interface (not standard SPI/I2C), so any two free GPIO pins can serve as clock and data lines.

**Wiring Table**

| Component Pin | Connects to Teensy 4 0 |
|---|---|
| HX711 VCC | 3.3V |
| HX711 GND | GND |
| HX711 DT (Data) | Pin 2 |
| HX711 SCK (Clock) | Pin 3 |
| Load Cell E+ (Excitation+) | HX711 E+ |
| Load Cell E- (Excitation-) | HX711 E- |
| Load Cell A+ (Signal+) | HX711 A+ |
| Load Cell A- (Signal-) | HX711 A- |

**Wiring Diagram**
```
+---------------------+          +------------------+
|      Teensy 4.0     |          |      HX711       |
|                     |          |                  |
|              3.3V  |----------| VCC              |
|               GND  |----------| GND              |
|             Pin 2  |----------| DT (Data)        |
|             Pin 3  |----------| SCK (Clock)      |
|                     |          |                  |
|                     |          | E+  E-  A+  A-  |
+---------------------+          +--+---+---+---+--+
                                    |   |   |   |
                               +----+---+---+---+----+
                               |       Load Cell      |
                               |   (strain gauge)     |
                               +----------------------+
```

The HX711 module itself provides the excitation voltage to the load cell and handles the analog-to-digital conversion internally, so no external power supply for the load cell is needed beyond the HX711 VCC.

**Code**
```cpp
#include <Arduino.h>

// Pin definitions
const int HX711_DT  = 2;  // Data pin
const int HX711_SCK = 3;  // Clock pin

// Calibration values -- adjust these for your specific load cell
long zeroOffset    = 0;       // Raw reading at zero load (tare)
float calibFactor  = 420.0f;  // Raw units per kg (tune this experimentally)

// Read a single raw 24-bit sample from the HX711
long readHX711Raw() {
  // Wait until data is ready (DT goes LOW)
  while (digitalRead(HX711_DT) == HIGH) {
    yield(); // keep Teensy responsive
  }

  long data = 0;

  // Clock in 24 bits, MSB first
  for (int i = 0; i < 24; i++) {
    digitalWrite(HX711_SCK, HIGH);
    delayMicroseconds(1);
    data = (data << 1) | digitalRead(HX711_DT);
    digitalWrite(HX711_SCK, LOW);
    delayMicroseconds(1);
  }

  // 25th pulse: sets gain to 128 for channel A on next read
  digitalWrite(HX711_SCK, HIGH);
  delayMicroseconds(1);
  digitalWrite(HX711_SCK, LOW);
  delayMicroseconds(1);

  // Sign-extend 24-bit two's complement to 32-bit
  if (data & 0x800000) {
    data |= 0xFF000000;
  }

  return data;
}

// Average multiple readings to reduce noise
long readAveraged(int samples = 10) {
  long sum = 0;
  for (int i = 0; i < samples; i++) {
    sum += readHX711Raw();
  }
  return sum / samples;
}

void tare() {
  Serial.println("Taring... remove all weight.");
  delay(2000);
  zeroOffset = readAveraged(20);
  Serial.print("Zero offset set to: ");
  Serial.println(zeroOffset);
}

void setup() {
  Serial.begin(115200);
  while (!Serial && millis() < 3000); // wait for Serial Monitor

  pinMode(HX711_DT,  INPUT);
  pinMode(HX711_SCK, OUTPUT);
  digitalWrite(HX711_SCK, LOW);

  Serial.println("HX711 Load Cell Demo -- Teensy 4.0");
  tare();
  Serial.println("Ready. Place weight on load cell.");
}

void loop() {
  long raw = readAveraged(10);
  float weight_kg = (float)(raw - zeroOffset) / calibFactor;

  Serial.print("Raw: ");
  Serial.print(raw);
  Serial.print("  |  Weight: ");
  Serial.print(weight_kg, 3);
  Serial.println(" kg");

  delay(500);
}
```

**How it works:** The HX711 signals that a conversion is ready by pulling DT low, after which the host bit-bangs 24 clock pulses to shift out the ADC result MSB-first — the mandatory 25th clock pulse at the end configures the chip for 128x gain on channel A for the next conversion. The sign-extension step (`data |= 0xFF000000`) is critical because the raw value is a 24-bit two's complement number that must be properly extended to a signed 32-bit integer before arithmetic subtraction of the tare offset.

