|    Teensy 4.0     |          |   SX1278 LoRa     |
|                   |          |                   |
|  3.3V  -----------|----------|--> VCC            |
|  GND   -----------|----------|--> GND            |
|  Pin13 (SCK)  ----|----------|--> SCK            |
|  Pin12 (MISO) <---|----------|--> MISO           |
|  Pin11 (MOSI) ----|----------|--> MOSI           |
|  Pin10 (CS)   ----|----------|--> NSS/CS         |
|  Pin9  (RST)  ----|----------|--> RST            |
|  Pin8  (DIO0) <---|----------|--> DIO0           |
+-------------------+          +-------------------+
```

Do NOT connect the SX1278 VCC to the 5V/VIN pin — the module is not 5V tolerant and will be damaged.

**Code**
```cpp
#include <SPI.h>
#include <LoRa.h>

// Pin definitions
#define LORA_CS   10
#define LORA_RST  9
#define LORA_DIO0 8

// LoRa frequency — change to match your region:
// 433E6 for Asia, 866E6 for Europe, 915E6 for North America
#define LORA_FREQ 915E6

int packetCount = 0;

void setup() {
  Serial.begin(115200);
  while (!Serial && millis() < 3000); // Wait for Serial Monitor (up to 3s)

  Serial.println("SX1278 LoRa Transmitter");

  // Tell the library which pins we're using
  LoRa.setPins(LORA_CS, LORA_RST, LORA_DIO0);

  if (!LoRa.begin(LORA_FREQ)) {
    Serial.println("LoRa init failed! Check wiring.");
    while (true); // Halt
  }

  // Optional: set spreading factor (7-12), bandwidth, TX power
  LoRa.setSpreadingFactor(7);       // SF7 = fastest / shortest range
  LoRa.setSignalBandwidth(125E3);   // 125 kHz bandwidth
  LoRa.setTxPower(17);              // 17 dBm (max for SX1278 without PA_BOOST)

  Serial.println("LoRa init OK.");
}

void loop() {
  Serial.print("Sending packet #");
  Serial.println(packetCount);

  // beginPacket/endPacket handles CS and triggers transmission
  LoRa.beginPacket();
  LoRa.print("Hello from Teensy 4.0, packet: ");
  LoRa.print(packetCount);
  LoRa.endPacket(); // Blocks until transmission completes

  packetCount++;
  delay(2000); // Send every 2 seconds
}
```

**How it works:** `LoRa.setPins()` must be called before `LoRa.begin()` to override the library's default CS/RST/DIO0 assignments — skipping this causes silent SPI failures. `LoRa.endPacket()` without arguments blocks until the radio finishes transmitting (passing `true` would make it async via DIO0 interrupt), which is the simplest approach for a basic transmitter.

The TCS34725 runs on 3.3V and communicates over I2C, so it connects directly to the Teensy 4.0's default I2C bus on pins 18 (SDA) and 19 (SCL) without any level shifting.

**Wiring Table**

| Component Pin | Connects to Teensy 4 0 |
|---|---|
| VIN / VCC | 3.3V |
| GND | GND |
| SDA | Pin 18 (SDA) |
| SCL | Pin 19 (SCL) |
| LED | 3.3V (or GPIO to control onboard LED) |
| INT | Pin 2 (optional interrupt, any free GPIO) |

**Wiring Diagram**
```
+-------------------+          +-------------------+
|    Teensy 4.0     |          |    TCS34725        |
|                   |          |   Color Sensor     |
|          3.3V o---+----------+---o VIN            |
|            GND o--+----------+---o GND            |
|    Pin 18 (SDA) o--+----------+---o SDA            |
|    Pin 19 (SCL) o--+----------+---o SCL            |
|          3.3V o---+----------+---o LED             |
|          Pin 2 o--+----------+---o INT  (optional) |
+-------------------+          +-------------------+
```

The TCS34725 is strictly a 3.3V device — do not connect VIN to 5V or you risk damaging the sensor.

**Code**
```cpp
#include <Wire.h>
#include <Adafruit_TCS34725.h>

// Create sensor object with 700ms integration time and 1x gain
// Adjust integration time / gain depending on your lighting conditions
Adafruit_TCS34725 tcs = Adafruit_TCS34725(
    TCS34725_INTEGRATIONTIME_700MS,
    TCS34725_GAIN_1X
);

void setup() {
    Serial.begin(115200);
    while (!Serial && millis() < 3000); // Wait for Serial Monitor (up to 3s)

    Wire.begin(); // SDA = pin 18, SCL = pin 19 on Teensy 4.0

    if (!tcs.begin()) {
        Serial.println("ERROR: TCS34725 not found. Check wiring and I2C address (0x29).");
        while (1); // Halt
    }

    Serial.println("TCS34725 initialized.");
    Serial.println("R\tG\tB\tC\tr\tg\tb");
}

void loop() {
    uint16_t r, g, b, c;
    float red, green, blue;

    // Read raw RGBC values (blocks for integration time duration)
    tcs.getRawData(&r, &g, &b, &c);

    // Calculate color temperature and lux (optional)
    uint16_t colorTemp = tcs.calculateColorTemperature_dn40(r, g, b, c);
    uint16_t lux       = tcs.calculateLux(r, g, b);

    // Normalize to 0.0-1.0 using the clear channel to compensate for brightness
    if (c > 0) {
        red   = (float)r / c;
        green = (float)g / c;
        blue  = (float)b / c;
    } else {
        red = green = blue = 0;
    }

    Serial.print(r);     Serial.print("\t");
    Serial.print(g);     Serial.print("\t");
    Serial.print(b);     Serial.print("\t");
    Serial.print(c);     Serial.print("\t");
    Serial.print(red,   3); Serial.print("\t");
    Serial.print(green, 3); Serial.print("\t");
    Serial.print(blue,  3); Serial.print("\t");
    Serial.print("Temp: "); Serial.print(colorTemp); Serial.print(" K\t");
    Serial.print("Lux: ");  Serial.println(lux);

    delay(1000);
}
```

**How it works:** `getRawData()` blocks for the configured integration period (700 ms here) before returning calibrated RGBC counts — longer integration yields more accurate but slower readings, so tune `TCS34725_INTEGRATIONTIME_*` for your refresh-rate needs. Dividing each channel by the clear (C) channel normalizes the color components against ambient brightness, giving consistent hue values regardless of how bright or dim the scene is.

