|    M5Stack Core2    |          |      BMP280        |
|                     |          |                   |
|  Port A (Grove)     |          |                   |
|  3.3V  o------------+----------o VCC               |
|  GND   o------------+----------o GND               |
|  GPIO32 (SDA) o-----+----------o SDA               |
|  GPIO33 (SCL) o-----+----------o SCL               |
+---------------------+          +-------------------+
```

The BMP280 operates at 3.3V only — do not supply 5V or you risk damaging the sensor.

**Code**
```cpp
#include <M5Core2.h>
#include <Wire.h>
#include <Adafruit_BMP280.h>

Adafruit_BMP280 bmp;

void setup() {
  M5.begin();
  // Initialize Port A I2C on GPIO32 (SDA) and GPIO33 (SCL)
  Wire1.begin(32, 33);

  M5.Lcd.setTextSize(2);
  M5.Lcd.setCursor(0, 0);

  if (!bmp.begin(0x76, &Wire1)) {
    // Try alternate address 0x77 if 0x76 fails (SDO pin sets address)
    if (!bmp.begin(0x77, &Wire1)) {
      M5.Lcd.println("BMP280 not found!");
      while (1) delay(10);
    }
  }

  // Configure sensor for weather monitoring use case
  bmp.setSampling(Adafruit_BMP280::MODE_NORMAL,
                  Adafruit_BMP280::SAMPLING_X2,   // temperature
                  Adafruit_BMP280::SAMPLING_X16,  // pressure
                  Adafruit_BMP280::FILTER_X16,
                  Adafruit_BMP280::STANDBY_MS_500);

  M5.Lcd.println("BMP280 ready");
}

void loop() {
  float temperature = bmp.readTemperature();         // degrees Celsius
  float pressure    = bmp.readPressure() / 100.0F;  // hPa
  float altitude    = bmp.readAltitude(1013.25);    // metres, sea-level ref

  M5.Lcd.fillScreen(BLACK);
  M5.Lcd.setCursor(0, 0);
  M5.Lcd.printf("Temp:  %.1f C\n", temperature);
  M5.Lcd.printf("Press: %.1f hPa\n", pressure);
  M5.Lcd.printf("Alt:   %.1f m\n", altitude);

  delay(2000);
}
```

**How it works:** `Wire1.begin(32, 33)` creates a second I2C bus instance mapped to Port A's pins, leaving the Core2's internal `Wire` bus (GPIO21/22) untouched for the AXP192 power IC and touch controller. The library call `bmp.begin(0x76, &Wire1)` explicitly passes this alternate bus so the Adafruit driver communicates on the correct I2C peripheral — the BMP280's address can be either 0x76 or 0x77 depending on how the SDO pin is connected on your breakout board.

