#include <Arduino.h>
#include <M5Core2.h>

// Port B pin2 is GPIO26 -- usable as digital output
const int RELAY_PIN = 26;

void setup() {
  M5.begin();
  M5.Lcd.setTextSize(2);

  pinMode(RELAY_PIN, OUTPUT);
  digitalWrite(RELAY_PIN, LOW); // relay off at startup

  M5.Lcd.setCursor(10, 10);
  M5.Lcd.println("Relay Control");
  M5.Lcd.println("BtnA: ON");
  M5.Lcd.println("BtnB: OFF");
}

void loop() {
  M5.update(); // refresh button states

  if (M5.BtnA.wasPressed()) {
    digitalWrite(RELAY_PIN, HIGH);
    M5.Lcd.fillRect(10, 100, 200, 30, BLACK);
    M5.Lcd.setCursor(10, 100);
    M5.Lcd.setTextColor(GREEN, BLACK);
    M5.Lcd.println("Relay: ON");
  }

  if (M5.BtnB.wasPressed()) {
    digitalWrite(RELAY_PIN, LOW);
    M5.Lcd.fillRect(10, 100, 200, 30, BLACK);
    M5.Lcd.setCursor(10, 100);
    M5.Lcd.setTextColor(RED, BLACK);
    M5.Lcd.println("Relay: OFF");
  }
}
```

**How it works:** `M5.update()` must be called each loop iteration to latch button edge events, so `wasPressed()` only returns true for a single cycle when the button is physically tapped rather than continuously while held. GPIO36 is deliberately avoided because the ESP32 straps it as an analog-only input with no output capability, making GPIO26 the only viable digital output on Port B.

