                                 +------------------+
                                       | | | |
                                   [Load Cell wires]
```

GPIO36 is an input-only pin on the ESP32 and cannot be driven as an output, so it is correctly assigned to DOUT (input); always verify the HX711 module runs on 3.3V logic before powering it from the 3.3V rail.

**Code**
```cpp
#include <M5Core2.h>

// Port B pins
const int HX711_DOUT = 36; // GPIO36 - input only, used for data
const int HX711_SCK  = 26; // GPIO26 - output, used for clock

// Calibration: raw units per gram (tune this for your load cell)
const float CALIBRATION_FACTOR = 420.0f;
long zeroOffset = 0;

// Read a raw 24-bit signed value from the HX711
long readHX711Raw() {
  // Wait for DOUT to go LOW (HX711 ready)
  while (digitalRead(HX711_DOUT) == HIGH) {
    delay(1);
  }

  long value = 0;
  // Clock in 24 bits, MSB first
  for (int i = 0; i < 24; i++) {
    digitalWrite(HX711_SCK, HIGH);
    delayMicroseconds(1);
    value = (value << 1) | digitalRead(HX711_DOUT);
    digitalWrite(HX711_SCK, LOW);
    delayMicroseconds(1);
  }

  // Send one extra clock pulse to set gain=128, channel A for next read
  digitalWrite(HX711_SCK, HIGH);
  delayMicroseconds(1);
  digitalWrite(HX711_SCK, LOW);
  delayMicroseconds(1);

  // Sign-extend 24-bit to 32-bit
  if (value & 0x800000) {
    value |= 0xFF000000;
  }

  return value;
}

void setup() {
  M5.begin();
  M5.Lcd.setTextSize(2);
  M5.Lcd.setTextColor(WHITE, BLACK);

  pinMode(HX711_DOUT, INPUT);
  pinMode(HX711_SCK, OUTPUT);
  digitalWrite(HX711_SCK, LOW);

  // Tare: average 10 readings for zero offset
  long sum = 0;
  for (int i = 0; i < 10; i++) {
    sum += readHX711Raw();
    delay(100);
  }
  zeroOffset = sum / 10;

  M5.Lcd.setCursor(0, 0);
  M5.Lcd.println("HX711 Ready");
  M5.Lcd.println("Tared!");
  delay(1000);
}

void loop() {
  M5.update();

  long raw = readHX711Raw();
  float grams = (float)(raw - zeroOffset) / CALIBRATION_FACTOR;

  M5.Lcd.fillScreen(BLACK);
  M5.Lcd.setCursor(0, 40);
  M5.Lcd.printf("Raw: %ld\n", raw);
  M5.Lcd.printf("Weight:\n %.2f g", grams);

  // Press button A to re-tare
  if (M5.BtnA.wasPressed()) {
    long sum = 0;
    for (int i = 0; i < 10; i++) {
      sum += readHX711Raw();
      delay(100);
    }
    zeroOffset = sum / 10;
    M5.Lcd.fillScreen(BLACK);
    M5.Lcd.setCursor(0, 40);
    M5.Lcd.println("Re-tared!");
    delay(500);
  }

  delay(200);
}
```

**How it works:** The HX711 uses a bit-banged serial protocol where each rising edge of SCK shifts out one data bit from DOUT; a 25th clock pulse at the end sets the gain and channel for the next conversion, which is required by the HX711 datasheet to keep it in the correct operating mode. The sign-extension step (`value |= 0xFF000000`) is critical because the HX711 returns a 24-bit two's complement integer that must be properly extended to a 32-bit signed long before arithmetic is performed.

The DS3231 RTC uses I2C and connects directly to the M5Stack Core2's Port A Grove connector (GPIO32/GPIO33), keeping it off the internal bus reserved for the AXP192 and touch controller.

**Wiring Table**

| Component Pin | Connects to M5Stack Core2 |
|---|---|
| VCC | 3.3V (Grove Port A) |
| GND | GND (Grove Port A) |
| SDA | GPIO32 (Port A SDA) |
| SCL | GPIO33 (Port A SCL) |

**Wiring Diagram**
```
+-------------------+          +-------------------+
|   M5Stack Core2   |          |   DS3231 RTC      |
|                   |          |                   |
|  Port A (Grove)   |          |                   |
|  GPIO32 (SDA) ----+----------+---- SDA           |
|  GPIO33 (SCL) ----+----------+---- SCL           |
|  3.3V         ----+----------+---- VCC           |
|  GND          ----+----------+---- GND           |
+-------------------+          +-------------------+
```

The DS3231 has internal pull-up resistors on most breakout boards; if yours does not, add 4.7kΩ pull-ups from SDA and SCL to 3.3V.

**Code**
```cpp
#include <Arduino.h>
#include <Wire.h>

// DS3231 I2C address
#define DS3231_ADDR 0x68

// Register addresses
#define DS3231_REG_TIME 0x00

// Helper: decode BCD byte to decimal
uint8_t bcdToDec(uint8_t bcd) {
  return ((bcd >> 4) * 10) + (bcd & 0x0F);
}

// Helper: encode decimal to BCD byte
uint8_t decToBcd(uint8_t dec) {
  return ((dec / 10) << 4) | (dec % 10);
}

struct DateTime {
  uint8_t second;
  uint8_t minute;
  uint8_t hour;
  uint8_t dayOfWeek;
  uint8_t day;
  uint8_t month;
  uint16_t year;
};

void setTime(DateTime dt) {
  Wire.beginTransmission(DS3231_ADDR);
  Wire.write(DS3231_REG_TIME);
  Wire.write(decToBcd(dt.second));
  Wire.write(decToBcd(dt.minute));
  Wire.write(decToBcd(dt.hour));      // 24-hour mode: bit6=0
  Wire.write(decToBcd(dt.dayOfWeek));
  Wire.write(decToBcd(dt.day));
  Wire.write(decToBcd(dt.month));
  Wire.write(decToBcd(dt.year - 2000)); // DS3231 stores 2-digit year
  Wire.endTransmission();
}

DateTime readTime() {
  DateTime dt;
  Wire.beginTransmission(DS3231_ADDR);
  Wire.write(DS3231_REG_TIME);        // point to register 0x00
  Wire.endTransmission(false);        // repeated start, keep bus active
  Wire.requestFrom((uint8_t)DS3231_ADDR, (uint8_t)7);

  dt.second    = bcdToDec(Wire.read() & 0x7F); // mask out oscillator-stop bit
  dt.minute    = bcdToDec(Wire.read() & 0x7F);
  dt.hour      = bcdToDec(Wire.read() & 0x3F); // mask mode bits
  dt.dayOfWeek = bcdToDec(Wire.read());
  dt.day       = bcdToDec(Wire.read());
  dt.month     = bcdToDec(Wire.read() & 0x1F); // mask century bit
  dt.year      = bcdToDec(Wire.read()) + 2000;
  return dt;
}

void setup() {
  Serial.begin(115200);
  // Port A on M5Stack Core2: SDA=GPIO32, SCL=GPIO33
  Wire.begin(32, 33);

  // Set an initial time (2024-06-15 Saturday 14:30:00)
  // Comment this out after first upload so time is not reset on every reboot
  DateTime initial = {0, 30, 14, 7, 15, 6, 2024};
  setTime(initial);

  Serial.println("DS3231 RTC initialized on Port A (GPIO32/33)");
}

void loop() {
  DateTime now = readTime();

  char buf[64];
  snprintf(buf, sizeof(buf),
    "Time: %04d-%02d-%02d %02d:%02d:%02d (DoW: %d)",
    now.year, now.month, now.day,
    now.hour, now.minute, now.second,
    now.dayOfWeek);
  Serial.println(buf);

  delay(1000);
}
```

**How it works:** `Wire.endTransmission(false)` issues a repeated START instead of a STOP after writing the register pointer, which is required by the DS3231 to keep the bus held so the subsequent `requestFrom` reads sequentially from register 0x00 onward. The BCD masking (e.g., `& 0x7F` on seconds) is essential because the DS3231 encodes status flags in the upper bits of several time registers alongside the actual time data.

The ENV II unit uses I2C and connects directly to Port A's Grove connector (GPIO32/GPIO33), keeping it off the internal I2C bus reserved for the AXP192 and touch controller.

**Wiring Table**

