The SHT30 operates at 3.3V only — do not supply 5V to the ENV II unit.

**Code**
```cpp
#include <Arduino.h>
#include <Wire.h>

// SHT30 default I2C address
#define SHT30_ADDR 0x44

// Port A I2C pins on M5Stack Core2
#define PORT_A_SDA 32
#define PORT_A_SCL 33

void setup() {
  Serial.begin(115200);
  // Initialize I2C on Port A pins, NOT the default GPIO21/22
  Wire.begin(PORT_A_SDA, PORT_A_SCL);
  delay(500);
  Serial.println("SHT30 ENV II Reader Ready");
}

bool readSHT30(float &temperature, float &humidity) {
  // Send single-shot measurement command (high repeatability)
  Wire.beginTransmission(SHT30_ADDR);
  Wire.write(0x2C); // clock stretching enabled
  Wire.write(0x06); // high repeatability
  if (Wire.endTransmission() != 0) {
    return false;
  }
  delay(20); // wait for measurement

  // Request 6 bytes: temp MSB, temp LSB, temp CRC, hum MSB, hum LSB, hum CRC
  Wire.requestFrom((uint8_t)SHT30_ADDR, (uint8_t)6);
  if (Wire.available() < 6) {
    return false;
  }

  uint8_t data[6];
  for (int i = 0; i < 6; i++) {
    data[i] = Wire.read();
  }

  // Convert raw values using SHT30 datasheet formulas
  uint16_t rawTemp = (data[0] << 8) | data[1];
  uint16_t rawHum  = (data[3] << 8) | data[4];

  temperature = -45.0f + 175.0f * ((float)rawTemp / 65535.0f);
  humidity    = 100.0f * ((float)rawHum  / 65535.0f);

  return true;
}

void loop() {
  float temp, hum;
  if (readSHT30(temp, hum)) {
    Serial.print("Temperature: ");
    Serial.print(temp, 2);
    Serial.print(" C  |  Humidity: ");
    Serial.print(hum, 2);
    Serial.println(" %");
  } else {
    Serial.println("ERROR: Could not read SHT30. Check wiring.");
  }
  delay(2000);
}
```

**How it works:** `Wire.begin(PORT_A_SDA, PORT_A_SCL)` explicitly binds the I2C bus to GPIO32/33 rather than the ESP32 defaults (GPIO21/22), which would collide with the Core2's internal peripherals. The raw 16-bit temperature and humidity values are converted using the fixed linear formulas from the SHT30 datasheet, where the divisor 65535 maps the full 16-bit range to the sensor's calibrated output span.

The VL53L0X communicates over I2C, so it connects directly to Port A (GPIO32/GPIO33) on the M5Stack Core2, keeping it off the internal I2C bus used by onboard peripherals.

**Wiring Table**

