The VL53L0X operates at 3.3V only — do not connect VCC to 5V or you risk damaging the sensor.

**Code**
```cpp
#include <M5Core2.h>
#include <Wire.h>
#include <VL53L0X.h>

VL53L0X sensor;

void setup() {
  M5.begin();
  // Initialize Port A I2C on GPIO32 (SDA) and GPIO33 (SCL)
  Wire.begin(32, 33);

  M5.Lcd.setTextSize(2);
  M5.Lcd.println("VL53L0X Init...");

  if (!sensor.init()) {
    M5.Lcd.println("Sensor not found!");
    while (1);
  }

  // Use long-range mode for distances up to ~2m
  sensor.setSignalRateLimit(0.1);
  sensor.setVcselPulsePeriod(VL53L0X::VcselPeriodPreRange, 18);
  sensor.setVcselPulsePeriod(VL53L0X::VcselPeriodFinalRange, 14);
  sensor.setMeasurementTimingBudget(200000); // 200ms timing budget

  sensor.startContinuous();
  M5.Lcd.println("Ready!");
}

void loop() {
  M5.update();

  uint16_t distance_mm = sensor.readRangeContinuousMillimeters();

  M5.Lcd.fillScreen(BLACK);
  M5.Lcd.setCursor(0, 0);

  if (sensor.timeoutOccurred()) {
    M5.Lcd.println("TIMEOUT");
  } else {
    M5.Lcd.printf("Distance:\n%u mm\n%.1f cm", distance_mm, distance_mm / 10.0);
  }

  delay(100);
}
```

**How it works:** `Wire.begin(32, 33)` explicitly assigns Port A's GPIO pins as the I2C bus so the VL53L0X doesn't accidentally share the internal bus on GPIO21/22. `setMeasurementTimingBudget(200000)` paired with the adjusted VCSEL pulse periods enables long-range mode, extending reliable detection from the default ~1.2 m up to roughly 2 m at the cost of slower update rate.

Port B on the M5Stack Core2 exposes GPIO36 and GPIO26, both of which support ADC input, making them the natural choice for reading the two analog axes of a joystick module.

**Wiring Table**

| Component Pin | Connects to M5Stack Core2 |
|---|---|
| VCC | 3.3V (Grove Port B) |
| GND | GND (Grove Port B) |
| VRX (X-axis) | GPIO36 (Port B pin1) |
| VRY (Y-axis) | GPIO26 (Port B pin2) |
| SW (button, optional) | not connected (no free Port B pin; use a separate GPIO if needed) |

**Wiring Diagram**
```
+-------------------------+          +-------------------+
|      M5Stack Core2      |          |  Analog Joystick  |
|                         |          |                   |
|  Port B GND  -----------|----------| GND               |
|  Port B 3V3  -----------|----------| VCC               |
|  Port B GPIO36 ---------|----------| VRX (X-axis)      |
|  Port B GPIO26 ---------|----------| VRY (Y-axis)      |
+-------------------------+          +-------------------+
```
GPIO36 is an input-only pin on ESP32 and does not have an internal pull-up/pull-down, which is fine here since the joystick module supplies its own resistor divider network.

**Code**
```cpp
#include <M5Core2.h>

const int PIN_JOY_X = 36;  // Port B pin1 (ADC1_CH0, input only)
const int PIN_JOY_Y = 26;  // Port B pin2 (DAC2 / ADC2_CH9)

const int ADC_MAX    = 4095;  // 12-bit ADC
const int ADC_CENTER = 2048;  // approximate resting center value

void setup() {
    M5.begin();
    Serial.begin(115200);

    // GPIO36 is input-only; no pinMode needed (analogRead works directly)
    // GPIO26 can be input or output; configure as input for ADC
    pinMode(PIN_JOY_Y, INPUT);

    M5.Lcd.setTextSize(2);
    M5.Lcd.setTextColor(WHITE, BLACK);
    M5.Lcd.setCursor(10, 10);
    M5.Lcd.println("Joystick Monitor");
}

void loop() {
    M5.update();

    int rawX = analogRead(PIN_JOY_X);
    int rawY = analogRead(PIN_JOY_Y);

    // Map raw 0-4095 to -100..+100 for intuitive axis values
    int axisX = map(rawX, 0, ADC_MAX, -100, 100);
    int axisY = map(rawY, 0, ADC_MAX, -100, 100);

    // Display on LCD
    M5.Lcd.fillRect(0, 50, 320, 140, BLACK);
    M5.Lcd.setCursor(10, 60);
    M5.Lcd.printf("Raw  X: %4d  Y: %4d", rawX, rawY);
    M5.Lcd.setCursor(10, 100);
    M5.Lcd.printf("Axis X: %4d  Y: %4d", axisX, axisY);

    // Also print to Serial
    Serial.printf("X=%d (raw %d)  Y=%d (raw %d)\n", axisX, rawX, axisY, rawY);

    delay(100);
}
```

**How it works:** GPIO36 on the ESP32 is a dedicated input-only ADC pin, so no `pinMode` call is required or valid for it — `analogRead()` works directly and attempting to set it as OUTPUT would silently fail. The `map()` call re-scales the 12-bit ADC range (0–4095) to −100…+100, giving a signed centered axis value that's easier to use in application logic than the raw counts.

The VL53L0X communicates over I2C and operates at 3.3V, making it directly compatible with the ESP32 without any level shifting.

**Wiring Table**

| Component Pin | Connects to ESP32 |
|---|---|
| VCC | 3.3V |
| GND | GND |
| SDA | GPIO 21 |
| SCL | GPIO 22 |
| XSHUT | GPIO 16 (optional, for hardware reset) |

**Wiring Diagram**
```
        +-------------------+          +-------------------+
        |       ESP32       |          |     VL53L0X       |
        |                   |          |                   |
        |        3.3V |-----+----------| VCC               |
        |         GND |-----+----------| GND               |
        |   GPIO 21   |-----+----------| SDA               |
        |  (SDA) 22   |-----+----------| SCL               |
        |       GPIO 22     |          |                   |
        |   GPIO 16   |-----+----------| XSHUT             |
        +-------------------+          +-------------------+
```
The VL53L0X must be powered from 3.3V only; applying 5V will damage the sensor.

**Code**
```cpp
#include <Arduino.h>
#include <Wire.h>
#include <VL53L0X.h>

// XSHUT pin allows hardware reset/power control of the sensor
#define XSHUT_PIN 16

VL53L0X sensor;

void setup() {
  Serial.begin(115200);

  // Drive XSHUT high to enable the sensor
  pinMode(XSHUT_PIN, OUTPUT);
  digitalWrite(XSHUT_PIN, HIGH);
  delay(10); // Allow sensor to boot

  Wire.begin(21, 22); // SDA, SCL

  if (!sensor.init()) {
    Serial.println("Failed to initialize VL53L0X! Check wiring.");
    while (1);
  }

  // Set measurement timing budget to 200ms for higher accuracy
  sensor.setMeasurementTimingBudget(200000);

  // Start continuous ranging mode with 250ms inter-measurement period
  sensor.startContinuous(250);

  Serial.println("VL53L0X ready.");
}

void loop() {
  uint16_t distance = sensor.readRangeContinuousMillimeters();

  if (sensor.timeoutOccurred()) {
    Serial.println("Timeout! No reading received.");
  } else {
    Serial.print("Distance: ");
    Serial.print(distance);
    Serial.println(" mm");
  }

  delay(300);
}
```

**How it works:** `setMeasurementTimingBudget(200000)` tells the sensor to spend up to 200 ms per measurement, trading speed for accuracy — reducing this value gives faster but noisier readings. The `startContinuous(250)` call puts the sensor into back-to-back ranging mode so the ESP32 can simply call `readRangeContinuousMillimeters()` in the loop without triggering each measurement individually.

The TCS34725 runs on 3.3V and uses the standard I2C bus, so it wires directly to the ESP32's default SDA/SCL pins without any level shifting.

**Wiring Table**

| Component Pin | Connects to ESP32 |
|---|---|
| VCC | 3.3V |
| GND | GND |
| SDA | GPIO 21 (SDA) |
| SCL | GPIO 22 (SCL) |
| LED | 3.3V (or GPIO for software control) |
| INT | Not connected (optional interrupt) |

**Wiring Diagram**
```
        +---------------------+          +-------------------+
        |        ESP32        |          |     TCS34725      |
        |                     |          |   Color Sensor    |
        |       GPIO 21 (SDA)|----------| SDA               |
        |       GPIO 22 (SCL)|----------| SCL               |
        |              3.3V  |----------| VCC               |
        |                    |----------| LED               |
        |                GND |----------| GND               |
        +---------------------+          +-------------------+
```

The TCS34725 is strictly 3.3V — do not connect VCC to 5V as it will damage the sensor.

**Code**
```cpp
#include <Wire.h>
#include <Adafruit_TCS34725.h>

// Instantiate with 50ms integration time and 4x gain
Adafruit_TCS34725 tcs = Adafruit_TCS34725(TCS34725_INTEGRATIONTIME_50MS, TCS34725_GAIN_4X);

void setup() {
  Serial.begin(115200);
  Wire.begin(21, 22); // SDA=GPIO21, SCL=GPIO22

  if (!tcs.begin()) {
    Serial.println("TCS34725 not found. Check wiring!");
    while (1); // halt
  }

  Serial.println("TCS34725 initialized.");
}

void loop() {
  uint16_t r, g, b, c;
  float red, green, blue;

  tcs.getRawData(&r, &g, &b, &c);

  // Normalize RGB values to 0-255 range using the clear channel
  if (c > 0) {
    red   = (float)r / c * 255.0f;
    green = (float)g / c * 255.0f;
    blue  = (float)b / c * 255.0f;
  } else {
    red = green = blue = 0;
  }

  // Clamp to 0-255
  red   = constrain(red,   0, 255);
  green = constrain(green, 0, 255);
  blue  = constrain(blue,  0, 255);

  Serial.printf("Raw  -> R: %4u  G: %4u  B: %4u  C: %4u\n", r, g, b, c);
  Serial.printf("Norm -> R: %5.1f  G: %5.1f  B: %5.1f\n", red, green, blue);

  // Calculate color temperature and lux using library helpers
  uint16_t colorTemp = tcs.calculateColorTemperature_dn40(r, g, b, c);
  uint16_t lux       = tcs.calculateLux(r, g, b);

  Serial.printf("Color Temp: %u K    Lux: %u\n\n", colorTemp, lux);

  delay(500);
}
```

**How it works:** Dividing each raw R/G/B channel by the clear (C) channel before scaling to 255 removes the effect of ambient light intensity, giving you a normalized color that reflects hue rather than brightness. The `calculateColorTemperature_dn40()` method uses Adafruit's improved DN40 algorithm, which is more accurate under non-daylight illuminants than the older McCamy formula.

The HMC5883L uses I2C and runs on 3.3V, making it directly compatible with the ESP32's default I2C pins without any level shifting.

**Wiring Table**

| Component Pin | Connects to ESP32 |
|---|---|
| VCC | 3.3V |
| GND | GND |
| SDA | GPIO 21 (SDA) |
| SCL | GPIO 22 (SCL) |

**Wiring Diagram**
```
        +------------------+          +-------------------+
        |      ESP32       |          |    HMC5883L       |
        |                  |          |                   |
        |       3.3V  >----+----------+> VCC              |
        |        GND  >----+----------+> GND              |
        |  GPIO21/SDA >----+----------+> SDA              |
        |  GPIO22/SCL >----+----------+> SCL              |
        +------------------+          +-------------------+
```
The HMC5883L is strictly 3.3V — do not connect VCC to 5V or you risk damaging the sensor.

**Code**
```cpp
#include <Wire.h>
#include <math.h>

#define HMC5883L_ADDR     0x1E
#define CONFIG_REG_A      0x00
#define CONFIG_REG_B      0x01
#define MODE_REG          0x02
#define DATA_OUTPUT_X_MSB 0x03

void setup() {
  Serial.begin(115200);
  Wire.begin(21, 22); // SDA, SCL

  // Configure HMC5883L
  // Config Register A: 8 samples averaged, 15 Hz output rate, normal measurement
  Wire.beginTransmission(HMC5883L_ADDR);
  Wire.write(CONFIG_REG_A);
  Wire.write(0x70); // 0b01110000
  Wire.endTransmission();

  // Config Register B: gain = 1.3 Ga (default)
  Wire.beginTransmission(HMC5883L_ADDR);
  Wire.write(CONFIG_REG_B);
  Wire.write(0x20);
  Wire.endTransmission();

  // Mode Register: continuous measurement mode
  Wire.beginTransmission(HMC5883L_ADDR);
  Wire.write(MODE_REG);
  Wire.write(0x00);
  Wire.endTransmission();

  delay(100);
  Serial.println("HMC5883L initialized.");
}

void loop() {
  // Request 6 bytes of data starting at X MSB register
  Wire.beginTransmission(HMC5883L_ADDR);
  Wire.write(DATA_OUTPUT_X_MSB);
  Wire.endTransmission(false);
  Wire.requestFrom(HMC5883L_ADDR, 6, true);

  if (Wire.available() == 6) {
    int16_t x = (Wire.read() << 8) | Wire.read(); // X axis
    int16_t z = (Wire.read() << 8) | Wire.read(); // Z axis (note: Z comes before Y in register order)
    int16_t y = (Wire.read() << 8) | Wire.read(); // Y axis

    // Calculate heading in degrees
    float heading = atan2((float)y, (float)x) * (180.0 / M_PI);
    if (heading < 0) heading += 360.0;

    Serial.print("X: "); Serial.print(x);
    Serial.print("  Y: "); Serial.print(y);
    Serial.print("  Z: "); Serial.print(z);
    Serial.print("  Heading: "); Serial.print(heading, 1);
    Serial.println(" deg");
  } else {
    Serial.println("Error: could not read 6 bytes from HMC5883L");
  }

  delay(500);
}
```

**How it works:** The HMC5883L's data registers return X, Z, then Y in that specific order (not X, Y, Z), so the reads must be assigned accordingly or the heading calculation will be wrong. The `atan2(y, x)` call converts the raw magnetic field vector components into a compass bearing in degrees, with the `+360` correction ensuring the result is always in the 0–360° range.

The SHT31 uses I2C and runs on 3.3V, so it connects directly to the ESP32's default I2C bus pins without any level shifting.

**Wiring Table**

| Component Pin | Connects to ESP32 |
|---|---|
| VCC | 3.3V |
| GND | GND |
| SDA | GPIO 21 (SDA) |
| SCL | GPIO 22 (SCL) |
| ADDR | GND (sets I2C address to 0x44) |

**Wiring Diagram**
```
        +------------------+          +-------------------+
        |      ESP32       |          |      SHT31        |
        |                  |          |                   |
        |      3.3V o------+----------o VCC               |
        |        GND o-----+----------o GND               |
        |              |   |          |                   |
        |  GPIO21(SDA) o---+----------o SDA               |
        |  GPIO22(SCL) o---+----------o SCL               |
        |                  |   GND o--o ADDR (0x44)       |
        +------------------+          +-------------------+
```
No external pull-up resistors are required if your SHT31 breakout board already includes them (most do); if using a bare chip, add 4.7kΩ pull-ups on SDA and SCL to 3.3V.

**Code**
```cpp
#include <Arduino.h>
#include <Wire.h>

#define SHT31_I2C_ADDR 0x44

bool sht31SendCommand(uint16_t cmd) {
  Wire.beginTransmission(SHT31_I2C_ADDR);
  Wire.write((uint8_t)(cmd >> 8));    // MSB
  Wire.write((uint8_t)(cmd & 0xFF));  // LSB
  return Wire.endTransmission() == 0;
}

bool sht31Read(float &temperature, float &humidity) {
  // Send single-shot measurement command, high repeatability
  if (!sht31SendCommand(0x2400)) {
    return false;
  }

  delay(20); // Wait for measurement to complete (~15ms for high repeatability)

  Wire.requestFrom((uint8_t)SHT31_I2C_ADDR, (uint8_t)6);
  if (Wire.available() != 6) {
    return false;
  }

  uint8_t buf[6];
  for (int i = 0; i < 6; i++) {
    buf[i] = Wire.read();
  }

  // buf[0..1] = raw temp, buf[2] = CRC, buf[3..4] = raw RH, buf[5] = CRC
  uint16_t rawTemp = ((uint16_t)buf[0] << 8) | buf[1];
  uint16_t rawHum  = ((uint16_t)buf[3] << 8) | buf[4];

  temperature = -45.0f + 175.0f * ((float)rawTemp / 65535.0f);
  humidity    = 100.0f * ((float)rawHum  / 65535.0f);

  return true;
}

void setup() {
  Serial.begin(115200);
  Wire.begin(21, 22); // SDA=GPIO21, SCL=GPIO22
  Serial.println("SHT31 I2C Example");
}

void loop() {
  float temp, hum;
  if (sht31Read(temp, hum)) {
    Serial.printf("Temperature: %.2f °C  Humidity: %.2f %%\n", temp, hum);
  } else {
    Serial.println("Failed to read from SHT31!");
  }
  delay(2000);
}
```

**How it works:** The single-shot command `0x2400` tells the SHT31 to take one high-repeatability measurement and then power down its ADC, which is more power-efficient than continuous mode; the 20 ms delay is required because the sensor needs up to ~15 ms to complete the conversion before the data registers are valid. The raw 16-bit values are converted to physical units using the fixed-point linear formulas given in the SHT31 datasheet, avoiding the need for any floating-point calibration constants.

The ADXL345 uses I2C with a configurable address (0x53 when SDO is pulled low, 0x1D when high), so both the SDO pin state and the POWER_CTL register must be set correctly before readings are valid.

**Wiring Table**

| Component Pin | Connects to ESP32 |
|---|---|
| VCC | 3.3V |
| GND | GND |
| SDA | GPIO 21 (SDA) |
| SCL | GPIO 22 (SCL) |
| SDO | GND (sets I2C address to 0x53) |
| CS | 3.3V (enables I2C mode) |

**Wiring Diagram**
```
        +----------------+          +-------------------+
        |   ESP32        |          |   ADXL345         |
        |                |          |                   |
        |   3.3V  -------+----------+-- VCC             |
        |   GND   -------+----------+-- GND             |
        |                |     |    +-- SDO (addr sel)  |
        |                |     +--------GND             |
        |   GPIO21 ------+----------+-- SDA             |
        |   GPIO22 ------+----------+-- SCL             |
        |                |          |                   |
        |   3.3V  -------+----------+-- CS  (I2C mode)  |
        +----------------+          +-------------------+
```
The ADXL345 is a 3.3V-only device on its VCC pin; do not connect it to 5V.

**Code**
```cpp
#include <Wire.h>

#define ADXL345_ADDR  0x53   // SDO tied to GND
#define REG_POWER_CTL 0x2D
#define REG_DATA_FORMAT 0x31
#define REG_DATAX0    0x32

void writeRegister(uint8_t reg, uint8_t value) {
  Wire.beginTransmission(ADXL345_ADDR);
  Wire.write(reg);
  Wire.write(value);
  Wire.endTransmission();
}

void readAccel(int16_t &x, int16_t &y, int16_t &z) {
  Wire.beginTransmission(ADXL345_ADDR);
  Wire.write(REG_DATAX0);
  Wire.endTransmission(false);          // repeated start keeps bus active
  Wire.requestFrom(ADXL345_ADDR, 6);   // 2 bytes each for X, Y, Z
  x = (int16_t)(Wire.read() | (Wire.read() << 8));
  y = (int16_t)(Wire.read() | (Wire.read() << 8));
  z = (int16_t)(Wire.read() | (Wire.read() << 8));
}

void setup() {
  Serial.begin(115200);
  Wire.begin(21, 22);                          // SDA=21, SCL=22
  writeRegister(REG_DATA_FORMAT, 0x08);        // full resolution, +/-2g
  writeRegister(REG_POWER_CTL, 0x08);          // exit standby, enable measurement
  delay(100);
  Serial.println("ADXL345 ready");
}

void loop() {
  int16_t x, y, z;
  readAccel(x, y, z);

  // Scale factor: 3.9 mg/LSB in full-resolution +/-2g mode
  float ax = x * 0.0039f;
  float ay = y * 0.0039f;
  float az = z * 0.0039f;

  Serial.printf("X: %.3f g  Y: %.3f g  Z: %.3f g\n", ax, ay, az);
  delay(200);
}
```

**How it works:** Writing `0x08` to POWER_CTL takes the ADXL345 out of its default standby state — without this the data registers always read zero. The repeated-start condition (`Wire.endTransmission(false)`) is required because the ADXL345's multi-byte read relies on the bus not being released between the register-address write and the subsequent data read.

The PCF8574 uses I2C and shares the bus with SDA/SCL, with its 3-bit address pins (A0–A2) setting the 7-bit device address, so pull them low for the default address of 0x20.

**Wiring Table**

| Component Pin | Connects to ESP32 |
|---|---|
| VCC | 3.3V |
| GND | GND |
| SDA | GPIO 21 (SDA) |
| SCL | GPIO 22 (SCL) |
| A0 | GND (address bit 0 = 0) |
| A1 | GND (address bit 1 = 0) |
| A2 | GND (address bit 2 = 0) |
| P0–P7 | Output devices (e.g. LEDs via 330Ω resistors) |
| INT | (optional) any free GPIO for interrupt-driven input |

**Wiring Diagram**
```
        +----------------------+         +-------------------+
        |        ESP32         |         |     PCF8574       |
        |                     |         |                   |
        |   3.3V  o-----------+-------->o VCC               |
        |   GND   o-----------+----+--->o GND               |
        |  GPIO21 o-----------+----+    |    (SDA)          |
        |   SDA   |           |    |    |                   |
        |         |  I2C bus  +---------o SDA               |
        |  GPIO22 o-----------+---------o SCL               |
        |   SCL   |                     |                   |
        |         |           GND o---->o A0                |
        |         |           GND o---->o A1                |
        +-------- +           GND o---->o A2                |
                              (addr=0x20)                   |
                                        | P0 o--> LED+330Ω |
                                        | P1 o--> LED+330Ω |
                                        | P2 o--> ...       |
                                        +-------------------+
```
The PCF8574 is a 3.3V-safe device but confirm your module does not have onboard 5V-only regulation; use 3.3V to keep I2C logic levels compatible with the ESP32.

**Code**
```cpp
#include <Arduino.h>
#include <Wire.h>

// PCF8574 I2C address: A2=0, A1=0, A0=0 → base address 0x20
#define PCF8574_ADDR 0x20

// Write a byte to PCF8574 output register
// Each bit controls one of P0–P7 (0 = LOW, 1 = HIGH)
bool pcf8574Write(uint8_t value) {
  Wire.beginTransmission(PCF8574_ADDR);
  Wire.write(value);
  return (Wire.endTransmission() == 0);
}

// Read current pin states from PCF8574
uint8_t pcf8574Read() {
  Wire.requestFrom((uint8_t)PCF8574_ADDR, (uint8_t)1);
  if (Wire.available()) {
    return Wire.read();
  }
  return 0xFF; // default high (input mode) on read failure
}

void setup() {
  Serial.begin(115200);
  // ESP32 default I2C: SDA=GPIO21, SCL=GPIO22
  Wire.begin(21, 22);
  delay(100);

  // Initialize all pins LOW
  if (pcf8574Write(0x00)) {
    Serial.println("PCF8574 initialized: all pins LOW");
  } else {
    Serial.println("ERROR: PCF8574 not found at 0x20 — check wiring and address pins");
  }
}

void loop() {
  // Knight-rider style: shift a single HIGH bit across P0–P7
  for (int i = 0; i < 8; i++) {
    uint8_t pinMask = (1 << i);   // set only pin i HIGH
    pcf8574Write(pinMask);
    Serial.print("Active pin: P");
    Serial.println(i);
    delay(150);
  }

  // Blink all pins together
  pcf8574Write(0xFF);  // all HIGH
  delay(400);
  pcf8574Write(0x00);  // all LOW
  delay(400);

  // Read back current pin state (useful when pins are used as inputs)
  uint8_t pinState = pcf8574Read();
  Serial.print("Pin state readback: 0b");
  Serial.println(pinState, BIN);
  delay(200);
}
```

**How it works:** The PCF8574 exposes all 8 I/O pins through a single byte written via `Wire.write()` — each bit maps directly to P0–P7, so bitwise shifting (`1 << i`) selects individual pins without any register configuration. Reading back with `Wire.requestFrom()` works because undriven pins float high via internal weak pull-ups, making the read byte reflect actual external pin levels for input use cases.

