Most microSD breakout modules include onboard 3.3V regulation and level shifting, but verify yours is 3.3V compatible before connecting to the ESP32's 3.3V rail.

**Code**
```cpp
#include <Arduino.h>
#include <SPI.h>
#include <SD.h>

const int SD_CS_PIN = 5;

void setup() {
  Serial.begin(115200);
  delay(1000);

  Serial.println("Initializing SD card...");

  if (!SD.begin(SD_CS_PIN)) {
    Serial.println("SD card initialization failed! Check wiring and card.");
    while (true) { delay(1000); }
  }

  Serial.println("SD card initialized successfully.");

  // Write a file
  File dataFile = SD.open("/hello.txt", FILE_WRITE);
  if (dataFile) {
    dataFile.println("Hello from ESP32!");
    dataFile.println("MicroSD SPI write test.");
    dataFile.close();
    Serial.println("File written: /hello.txt");
  } else {
    Serial.println("Error opening file for writing.");
  }

  // Read back the file
  dataFile = SD.open("/hello.txt");
  if (dataFile) {
    Serial.println("Reading /hello.txt:");
    while (dataFile.available()) {
      Serial.write(dataFile.read());
    }
    dataFile.close();
  } else {
    Serial.println("Error opening file for reading.");
  }
}

void loop() {
  // Nothing to do here
}
```

**How it works:** `SD.begin(SD_CS_PIN)` internally calls `SPI.begin()` using the default VSPI pins (18/19/23) and asserts CS on GPIO 5 to initialize the card — passing only the CS pin is enough because the Arduino SD library already knows the hardware SPI peripheral. Opening with `FILE_WRITE` creates the file if it doesn't exist and appends to it if it does, so calling `dataFile.close()` is critical to flush and finalize the data on the card.

The MCP2515 uses standard 4-wire SPI plus a dedicated interrupt line (INT) that must connect to a GPIO capable of handling edge-triggered interrupts, and the module runs at 3.3 V–5 V but its logic is 5 V — use a 3.3 V supply when paired directly with the ESP32 to keep logic levels safe.

**Wiring Table**

| Component Pin | Connects to ESP32 |
|---|---|
| VCC | 3.3V |
| GND | GND |
| SCK | GPIO 18 (SPI SCK) |
| SI (MOSI) | GPIO 23 (SPI MOSI) |
| SO (MISO) | GPIO 19 (SPI MISO) |
| CS | GPIO 5 |
| INT | GPIO 4 |

**Wiring Diagram**
```
  +------------------+          +----------------------+
  |      ESP32       |          |     MCP2515 Module   |
  |                  |          |                      |
  | 3.3V ------------+----------+-- VCC                |
  | GND  ------------+----------+-- GND                |
  | GPIO18 (SCK) ----+----------+-- SCK                |
  | GPIO23 (MOSI) ---+----------+-- SI                 |
  | GPIO19 (MISO) ---+----------+-- SO                 |
  | GPIO5  (CS)  ----+----------+-- CS                 |
  | GPIO4  (INT) ----+----------+-- INT                |
  +------------------+          +----------------------+
                                        |
                               [CAN Transceiver]
                                  CANH / CANL
                               (to CAN bus network)
```
Power the MCP2515 module from the ESP32's 3.3 V rail only — feeding it 5 V will push 5 V logic back onto the ESP32's GPIO pins and may damage the chip.

**Code**
```cpp
#include <Arduino.h>
#include <SPI.h>
#include <mcp2515.h>  // Autowp/mcp2515 library (install via Library Manager)

// Pin definitions
#define CAN_CS_PIN  5
#define CAN_INT_PIN 4

MCP2515 mcp2515(CAN_CS_PIN);

volatile bool canMessageReady = false;

void IRAM_ATTR onCanInterrupt() {
  canMessageReady = true;
}

void setup() {
  Serial.begin(115200);
  while (!Serial) {}

  SPI.begin(18, 19, 23, CAN_CS_PIN);  // SCK, MISO, MOSI, CS

  if (mcp2515.reset() != MCP2515::ERROR_OK) {
    Serial.println("MCP2515 reset failed");
    while (1);
  }

  // Set CAN bus speed to 500 kbps, oscillator is 8 MHz on most modules
  if (mcp2515.setBitrate(CAN_500KBPS, MCP_8MHZ) != MCP2515::ERROR_OK) {
    Serial.println("MCP2515 setBitrate failed");
    while (1);
  }

  mcp2515.setNormalMode();  // Leave configuration mode, enable TX/RX

  pinMode(CAN_INT_PIN, INPUT);
  attachInterrupt(digitalPinToInterrupt(CAN_INT_PIN), onCanInterrupt, FALLING);

  Serial.println("MCP2515 CAN bus ready.");
}

void loop() {
  // --- Transmit a CAN frame every 1 second ---
  static unsigned long lastTx = 0;
  if (millis() - lastTx >= 1000) {
    lastTx = millis();

    struct can_frame txFrame;
    txFrame.can_id  = 0x123;          // 11-bit standard CAN ID
    txFrame.can_dlc = 4;              // 4 data bytes
    txFrame.data[0] = 0xDE;
    txFrame.data[1] = 0xAD;
    txFrame.data[2] = 0xBE;
    txFrame.data[3] = 0xEF;

    MCP2515::ERROR result = mcp2515.sendMessage(&txFrame);
    if (result == MCP2515::ERROR_OK) {
      Serial.println("TX: frame sent (ID=0x123)");
    } else {
      Serial.print("TX error: ");
      Serial.println(result);
    }
  }

  // --- Receive CAN frames via interrupt flag ---
  if (canMessageReady) {
    canMessageReady = false;

    struct can_frame rxFrame;
    while (mcp2515.readMessage(&rxFrame) == MCP2515::ERROR_OK) {
      Serial.print("RX: ID=0x");
      Serial.print(rxFrame.can_id, HEX);
      Serial.print(" DLC=");
      Serial.print(rxFrame.can_dlc);
      Serial.print(" Data:");
      for (int i = 0; i < rxFrame.can_dlc; i++) {
        Serial.print(" 0x");
        Serial.print(rxFrame.data[i], HEX);
      }
      Serial.println();
    }
  }
}
```

**How it works:** The INT pin is wired to GPIO 4 and triggers an `IRAM_ATTR` ISR on a falling edge — the MCP2515 pulls INT low whenever a message arrives, so the ISR simply sets a flag that `loop()` drains safely outside interrupt context by calling `readMessage()` in a `while` loop until the RX buffers are empty. The `SPI.begin(18, 19, 23, CAN_CS_PIN)` call explicitly maps the ESP32's VSPI bus pins rather than relying on defaults, ensuring the MCP2515 library's underlying SPI transactions target the correct hardware peripheral.

The HC-05 operates at 3.3V logic but its VCC pin accepts 5V — use a logic level consideration on the RX line since the HC-05 TX output is 3.3V-compatible with the ESP32, but the ESP32 TX (3.3V) going into HC-05 RX is generally safe as the HC-05 RX is 3.3V tolerant on most modules.

**Wiring Table**

| Component Pin | Connects to ESP32 |
|---|---|
| VCC | 5V (or 3.3V if module has onboard regulator) |
| GND | GND |
| TX | GPIO16 (ESP32 UART2 RX) |
| RX | GPIO17 (ESP32 UART2 TX) |
| EN (KEY) | Not connected (leave floating for data mode) |
| STATE | Not connected (optional status indicator) |

**Wiring Diagram**
```
+----------------------+          +-------------------+
|        ESP32         |          |      HC-05        |
|                      |          |                   |
|   5V (or 3.3V) o----+----------+o VCC              |
|          GND  o----+----------+o GND               |
|                      |          |                   |
|  GPIO16 (UART2 RX) o-+----------+o TX               |
|  GPIO17 (UART2 TX) o-+----------+o RX               |
|                      |          |                   |
|   USB Serial         |          |   (Bluetooth)     |
|   (UART0)            |          |   to Phone/PC     |
+----------------------+          +-------------------+
```
Ensure the HC-05 module's onboard 3.3V regulator is present before applying 5V to VCC; if uncertain, use 3.3V to be safe.

**Code**
```cpp
#include <Arduino.h>

// Use ESP32 UART2 for HC-05 to keep UART0 free for USB Serial monitor
#define BT_RX_PIN 16  // ESP32 RX2 <- HC-05 TX
#define BT_TX_PIN 17  // ESP32 TX2 -> HC-05 RX
#define BT_BAUD   9600 // HC-05 default baud rate

void setup() {
  // USB Serial for PC-side monitoring/input
  Serial.begin(115200);
  while (!Serial) { ; }

  // Hardware UART2 connected to HC-05
  Serial2.begin(BT_BAUD, SERIAL_8N1, BT_RX_PIN, BT_TX_PIN);

  Serial.println("HC-05 Bluetooth passthrough ready.");
  Serial.println("Type in Serial Monitor to send to BT device, and vice versa.");
}

void loop() {
  // Forward data from USB Serial Monitor -> HC-05 (and out over Bluetooth)
  if (Serial.available()) {
    char c = Serial.read();
    Serial2.write(c);
  }

  // Forward data received over Bluetooth (HC-05) -> USB Serial Monitor
  if (Serial2.available()) {
    char c = Serial2.read();
    Serial.write(c);
  }
}
```

**How it works:** `Serial2.begin()` on the ESP32 accepts explicit RX and TX pin arguments, allowing any GPIO pair to be remapped to the hardware UART2 peripheral rather than being fixed — this is why GPIO16/17 work without any additional configuration. The loop simply bridges both directions one byte at a time, making the ESP32 act as a transparent UART↔Bluetooth tunnel between the PC and any Bluetooth Classic device paired with the HC-05.

The ESP32 has built-in capacitive touch sensing on several GPIO pins, so no external components or pull-up resistors are needed — just a wire or pad connected directly to the designated touch-capable GPIO.

**Wiring Table**

| Component Pin | Connects to ESP32 |
|---|---|
| Touch pad / wire | GPIO4 (Touch0) |
| (optional) Small metal pad or bare wire | Soldered or alligator-clipped to GPIO4 |

**Wiring Diagram**
```
        +-------------------------+
        |          ESP32          |
        |                         |
        |  GPIO4 (T0) o-----------+----[ bare wire / touch pad ]
        |                         |
        |         GND o--- GND    |
        +-------------------------+
```
No external resistors or power supply wiring is required; the ESP32's internal oscillator drives the capacitive measurement on its touch-capable pins.

**Code**
```cpp
// ESP32 built-in capacitive touch demo using touchRead()
// GPIO4 = Touch0; lower touchRead() value = stronger touch detected

const int TOUCH_PIN = T0;       // T0 maps to GPIO4
const int TOUCH_THRESHOLD = 40; // Tune this value for your setup

void setup() {
  Serial.begin(115200);
  Serial.println("ESP32 Capacitive Touch Demo");
  Serial.println("Touch the wire connected to GPIO4 (T0)");
}

void loop() {
  // touchRead() returns a raw capacitance value (0-~100).
  // The value DECREASES when a finger is detected.
  uint16_t touchValue = touchRead(TOUCH_PIN);

  Serial.print("Touch value: ");
  Serial.print(touchValue);

  if (touchValue < TOUCH_THRESHOLD) {
    Serial.println("  --> TOUCHED!");
  } else {
    Serial.println("  --> not touched");
  }

  delay(200);
}
```

**How it works:** `touchRead(T0)` internally drives a high-frequency signal on GPIO4 and measures the resulting capacitance — when a finger approaches, the capacitance rises and the returned integer value drops, which is why the detection condition checks `< TOUCH_THRESHOLD` rather than `>`. You may need to adjust `TOUCH_THRESHOLD` (printed baseline values when untouched are typically 60–80; touched values typically fall below 20–40 depending on wire length and environment).

The MPU9250 communicates over I2C and runs at 3.3V, making it directly compatible with the ESP32's default I2C bus on GPIO 21 (SDA) and GPIO 22 (SCL).

**Wiring Table**

| Component Pin | Connects to ESP32 |
|---|---|
| VCC | 3.3V |
| GND | GND |
| SDA | GPIO 21 (SDA) |
| SCL | GPIO 22 (SCL) |
| AD0 | GND (sets I2C address to 0x68) |
| NCS | 3.3V (selects I2C mode, not SPI) |

**Wiring Diagram**
```
        +------------------+          +-------------------+
        |      ESP32       |          |     MPU9250       |
        |                  |          |                   |
        |       3.3V o-----+----------+o VCC              |
        |        GND o-----+----------+o GND              |
        |    GPIO 21 o-----+----------+o SDA              |
        |    GPIO 22 o-----+----------+o SCL              |
        |                  |     GND--+o AD0  (addr 0x68) |
        |                  |   3.3V--++o NCS  (I2C mode)  |
        +------------------+          +-------------------+
```
Do not supply 5V to the MPU9250; it is a 3.3V-only device and will be damaged by higher voltage.

**Code**
```cpp
#include <Wire.h>

// MPU9250 I2C address when AD0 is pulled LOW
#define MPU9250_ADDR 0x68

// AK8963 magnetometer sits at a separate internal I2C address
#define AK8963_ADDR  0x0C

// Register addresses
#define PWR_MGMT_1   0x6B
#define ACCEL_XOUT_H 0x3B
#define GYRO_XOUT_H  0x43
#define INT_PIN_CFG  0x37  // enables pass-through to reach AK8963
#define AK8963_CNTL  0x0A
#define AK8963_HXL   0x03

void writeByte(uint8_t devAddr, uint8_t reg, uint8_t data) {
  Wire.beginTransmission(devAddr);
  Wire.write(reg);
  Wire.write(data);
  Wire.endTransmission();
}

void readBytes(uint8_t devAddr, uint8_t reg, uint8_t count, uint8_t *buf) {
  Wire.beginTransmission(devAddr);
  Wire.write(reg);
  Wire.endTransmission(false);  // repeated start keeps bus active
  Wire.requestFrom((uint8_t)devAddr, count);
  for (uint8_t i = 0; i < count && Wire.available(); i++) {
    buf[i] = Wire.read();
  }
}

void setup() {
  Serial.begin(115200);
  Wire.begin(21, 22);  // SDA=21, SCL=22

  // Wake the MPU9250 and select best clock source
  writeByte(MPU9250_ADDR, PWR_MGMT_1, 0x01);
  delay(100);

  // Enable I2C bypass so ESP32 can talk directly to AK8963
  writeByte(MPU9250_ADDR, INT_PIN_CFG, 0x02);
  delay(10);

  // Set AK8963 to continuous measurement mode 2, 16-bit output
  writeByte(AK8963_ADDR, AK8963_CNTL, 0x16);
  delay(10);

  Serial.println("MPU9250 initialized");
}

void loop() {
  uint8_t buf[6];
  int16_t ax, ay, az, gx, gy, gz, mx, my, mz;

  // --- Accelerometer ---
  readBytes(MPU9250_ADDR, ACCEL_XOUT_H, 6, buf);
  ax = (int16_t)(buf[0] << 8 | buf[1]);
  ay = (int16_t)(buf[2] << 8 | buf[3]);
  az = (int16_t)(buf[4] << 8 | buf[5]);

  // --- Gyroscope ---
  readBytes(MPU9250_ADDR, GYRO_XOUT_H, 6, buf);
  gx = (int16_t)(buf[0] << 8 | buf[1]);
  gy = (int16_t)(buf[2] << 8 | buf[3]);
  gz = (int16_t)(buf[4] << 8 | buf[5]);

  // --- Magnetometer (AK8963) ---
  readBytes(AK8963_ADDR, AK8963_HXL, 6, buf);
  // AK8963 is little-endian: low byte first
  mx = (int16_t)(buf[1] << 8 | buf[0]);
  my = (int16_t)(buf[3] << 8 | buf[2]);
  mz = (int16_t)(buf[5] << 8 | buf[4]);

  Serial.printf("Accel: %6d %6d %6d  Gyro: %6d %6d %6d  Mag: %6d %6d %6d\n",
                ax, ay, az, gx, gy, gz, mx, my, mz);

  delay(100);
}
```

**How it works:** Setting `INT_PIN_CFG` to `0x02` enables I2C bypass mode on the MPU9250, which bridges the chip's internal I2C bus to the external bus so the ESP32 can address the AK8963 magnetometer directly at `0x0C` — without this, the magnetometer is hidden behind the MPU9250's master controller. The magnetometer registers also arrive little-endian (low byte first), unlike the accelerometer and gyroscope, so the byte-swap order in the `mx/my/mz` assignments is intentional.

