The HC-SR04 ECHO pin outputs 5 V logic; most ESP32 GPIOs are 5 V-tolerant in practice, but adding a 1 kΩ resistor in series on each ECHO line is a safe precaution.

**Code**
```cpp
#include <Arduino.h>

// HC-SR04 #1
const int TRIG1 = 5;
const int ECHO1 = 18;

// HC-SR04 #2
const int TRIG2 = 19;
const int ECHO2 = 21;

// Buzzer
const int BUZZER = 23;

// Parking thresholds (cm)
const float DANGER_DIST  = 20.0f;   // continuous beep
const float WARNING_DIST = 80.0f;   // max beep interval distance

// Measure distance in cm for a given TRIG/ECHO pair
float measureDistance(int trigPin, int echoPin) {
  digitalWrite(trigPin, LOW);
  delayMicroseconds(2);
  digitalWrite(trigPin, HIGH);
  delayMicroseconds(10);
  digitalWrite(trigPin, LOW);

  long duration = pulseIn(echoPin, HIGH, 30000); // 30 ms timeout ~5 m
  if (duration == 0) return 999.0f; // no echo / out of range
  return duration * 0.0343f / 2.0f;
}

void setup() {
  Serial.begin(115200);

  pinMode(TRIG1, OUTPUT);
  pinMode(ECHO1, INPUT);
  pinMode(TRIG2, OUTPUT);
  pinMode(ECHO2, INPUT);
  pinMode(BUZZER, OUTPUT);

  digitalWrite(TRIG1, LOW);
  digitalWrite(TRIG2, LOW);
  digitalWrite(BUZZER, LOW);
}

void loop() {
  float d1 = measureDistance(TRIG1, ECHO1);
  delay(5); // brief gap between sensors to avoid cross-talk
  float d2 = measureDistance(TRIG2, ECHO2);

  // Use the smaller (closer) reading as the alert distance
  float nearest = min(d1, d2);

  Serial.printf("Sensor1: %.1f cm  Sensor2: %.1f cm  -> nearest: %.1f cm\n",
                d1, d2, nearest);

  if (nearest <= DANGER_DIST) {
    // Continuous tone — object dangerously close
    digitalWrite(BUZZER, HIGH);
    delay(100);
    digitalWrite(BUZZER, LOW);
    delay(50);
  } else if (nearest < WARNING_DIST) {
    // Beep interval scales linearly: 50 ms at DANGER_DIST to 800 ms at WARNING_DIST
    float ratio = (nearest - DANGER_DIST) / (WARNING_DIST - DANGER_DIST);
    int beepInterval = (int)(50 + ratio * 750);

    digitalWrite(BUZZER, HIGH);
    delay(80);
    digitalWrite(BUZZER, LOW);
    delay(beepInterval);
  } else {
    // Object far away — silence
    digitalWrite(BUZZER, LOW);
    delay(200);
  }
}
```

**How it works:** The 5 ms gap inserted between the two `measureDistance()` calls prevents acoustic cross-talk where one sensor's ultrasonic pulse accidentally triggers the other sensor's ECHO pin. The beep interval is computed with a linear interpolation (`ratio`) between the danger and warning distances, so the buzzer cadence tightens smoothly as the vehicle closes in on an obstacle.

