```

GPIO34 is input-only and ADC-capable on the ESP32, making it ideal for analog sensor reads; never drive it as an output.

**Code**
```cpp
#include <Arduino.h>

const int RAIN_ANALOG_PIN = 34;   // ADC input from rain sensor AO
const int RELAY_PIN       = 26;   // Digital output to relay module IN

// Lower analog value = more moisture (sensor conductivity increases)
const int RAIN_THRESHOLD  = 2000; // Tune 0-4095 for your sensor & rain level

// Relay logic: LOW activates most relay modules (active-low)
const int RELAY_ACTIVE    = LOW;
const int RELAY_INACTIVE  = HIGH;

bool coverClosed = false;

void setup() {
  Serial.begin(115200);
  pinMode(RAIN_ANALOG_PIN, INPUT);   // GPIO34 is input-only, but explicit is good
  pinMode(RELAY_PIN, OUTPUT);
  digitalWrite(RELAY_PIN, RELAY_INACTIVE); // Start with cover open / relay off
  Serial.println("Rain sensor cover system ready.");
}

void loop() {
  int rawValue = analogRead(RAIN_ANALOG_PIN); // 12-bit ADC: 0-4095
  Serial.print("Rain sensor raw: ");
  Serial.println(rawValue);

  bool isRaining = (rawValue < RAIN_THRESHOLD);

  if (isRaining && !coverClosed) {
    Serial.println("Rain detected! Closing cover.");
    digitalWrite(RELAY_PIN, RELAY_ACTIVE);
    coverClosed = true;
  } else if (!isRaining && coverClosed) {
    Serial.println("No rain. Opening cover.");
    digitalWrite(RELAY_PIN, RELAY_INACTIVE);
    coverClosed = false;
  }

  delay(1000); // Sample every second
}
```

**How it works:** The rain sensor's resistance drops when wet, pulling its analog output voltage lower, so the ADC reads a smaller value — the threshold comparison `rawValue < RAIN_THRESHOLD` exploits this inverse relationship. The `coverClosed` state flag prevents repeatedly toggling the relay on every loop iteration when conditions haven't changed.

