The MQ-2 requires 5V for its heater element; do not power it from 3.3V or readings will be unreliable. GPIO34 is input-only and ADC-capable, making it a safe choice for the analog signal.

**Code**
```cpp
#include <Arduino.h>

const int GAS_PIN    = 34;   // MQ-2 analog output
const int BUZZER_PIN = 26;   // active buzzer

// Threshold in raw ADC counts (0-4095 for ESP32 12-bit ADC).
// Adjust after observing baseline readings in clean air.
const int GAS_THRESHOLD = 1500;

void setup() {
  Serial.begin(115200);
  pinMode(BUZZER_PIN, OUTPUT);
  digitalWrite(BUZZER_PIN, LOW);

  // GPIO34 is input-only by hardware; no pinMode call needed,
  // but we configure ADC resolution explicitly.
  analogReadResolution(12);  // 12-bit: values 0-4095
  analogSetAttenuation(ADC_11db); // allows ~0-3.3V input range

  Serial.println("MQ-2 Gas Sensor Ready. Warming up...");
  delay(20000); // allow 20 s heater warm-up for stable readings
  Serial.println("Warm-up complete.");
}

void loop() {
  int gasValue = analogRead(GAS_PIN);
  Serial.print("Gas ADC value: ");
  Serial.println(gasValue);

  if (gasValue > GAS_THRESHOLD) {
    digitalWrite(BUZZER_PIN, HIGH); // trigger alarm
    Serial.println("WARNING: Gas detected!");
  } else {
    digitalWrite(BUZZER_PIN, LOW);  // safe, silence buzzer
  }

  delay(500); // sample every 500 ms
}
```

**How it works:** `analogSetAttenuation(ADC_11db)` is critical — without it the ESP32 ADC defaults to a reduced input range (~1V max), causing the sensor output to saturate early and give false alarms. The 20-second warm-up delay lets the MQ-2's internal heater reach operating temperature before any readings are trusted, preventing spurious triggers on power-on.

