**Code**
```cpp
#include <Arduino.h>

// Active-LOW relay signal pins
const int RELAY1_PIN = 26;  // Door 1
const int RELAY2_PIN = 27;  // Door 2

// Duration (ms) to simulate a button press on the garage opener
const unsigned long PULSE_MS = 500;

void triggerRelay(int pin) {
  digitalWrite(pin, LOW);   // Energize relay (active LOW)
  delay(PULSE_MS);
  digitalWrite(pin, HIGH);  // Release relay
}

void setup() {
  Serial.begin(115200);

  pinMode(RELAY1_PIN, OUTPUT);
  pinMode(RELAY2_PIN, OUTPUT);

  // Start with relays de-energized (HIGH = off for active-LOW modules)
  digitalWrite(RELAY1_PIN, HIGH);
  digitalWrite(RELAY2_PIN, HIGH);

  Serial.println("Garage door relay controller ready.");
  Serial.println("Send '1' to trigger Door 1, '2' to trigger Door 2.");
}

void loop() {
  if (Serial.available()) {
    char cmd = Serial.read();
    if (cmd == '1') {
      Serial.println("Triggering Door 1...");
      triggerRelay(RELAY1_PIN);
      Serial.println("Done.");
    } else if (cmd == '2') {
      Serial.println("Triggering Door 2...");
      triggerRelay(RELAY2_PIN);
      Serial.println("Done.");
    }
  }
}
```

**How it works:** The relays are initialized HIGH in `setup()` so they are off immediately on boot — skipping this step would cause the relay to briefly fire on every power cycle, which is unsafe for a garage door. The `triggerRelay()` helper pulls the pin LOW for 500 ms and then releases it, mimicking a momentary wall-button press that the garage opener interprets as a single open/close command.

