**Code**
```cpp
#include <Arduino.h>
#include <ESP32Servo.h>

// ADC pins for joystick axes
const int PIN_JOY_X  = 34;
const int PIN_JOY_Y  = 35;
const int PIN_JOY_SW = 32;  // optional joystick button

// PWM pins for servos
const int PIN_PAN  = 13;
const int PIN_TILT = 12;

// Servo angle limits
const int SERVO_MIN = 0;
const int SERVO_MAX = 180;
const int SERVO_CENTER = 90;

Servo panServo;
Servo tiltServo;

// Exponential moving average for ADC smoothing
float smoothX = 2048.0f;
float smoothY = 2048.0f;
const float ALPHA = 0.15f;

void setup() {
  Serial.begin(115200);

  pinMode(PIN_JOY_X,  INPUT);
  pinMode(PIN_JOY_Y,  INPUT);
  pinMode(PIN_JOY_SW, INPUT_PULLUP);

  // Allocate LEDC timers before attaching servos (ESP32Servo requirement)
  ESP32PWM::allocateTimer(0);
  ESP32PWM::allocateTimer(1);

  panServo.setPeriodHertz(50);   // standard 50 Hz servo signal
  tiltServo.setPeriodHertz(50);

  panServo.attach(PIN_PAN,   500, 2400);  // 500–2400 µs pulse range
  tiltServo.attach(PIN_TILT, 500, 2400);

  // Start servos at center position
  panServo.write(SERVO_CENTER);
  tiltServo.write(SERVO_CENTER);

  delay(500);
}

void loop() {
  // Read raw 12-bit ADC values (0–4095)
  int rawX = analogRead(PIN_JOY_X);
  int rawY = analogRead(PIN_JOY_Y);

  // Smooth ADC readings with exponential moving average
  smoothX = ALPHA * rawX + (1.0f - ALPHA) * smoothX;
  smoothY = ALPHA * rawY + (1.0f - ALPHA) * smoothY;

  // Map smoothed ADC range to servo angle range
  int panAngle  = map((int)smoothX, 0, 4095, SERVO_MIN, SERVO_MAX);
  int tiltAngle = map((int)smoothY, 0, 4095, SERVO_MIN, SERVO_MAX);

  // Constrain to safe limits
  panAngle  = constrain(panAngle,  SERVO_MIN, SERVO_MAX);
  tiltAngle = constrain(tiltAngle, SERVO_MIN, SERVO_MAX);

  panServo.write(panAngle);
  tiltServo.write(tiltAngle);

  // Optional: print button state and angles
  bool btnPressed = (digitalRead(PIN_JOY_SW) == LOW);
  Serial.printf("Pan: %3d  Tilt: %3d  Btn: %d\n", panAngle, tiltAngle, btnPressed);

  delay(20);  // ~50 Hz update rate matches servo PWM frequency
}
```

**How it works:** The exponential moving average (`smoothX/Y`) tames the ESP32 ADC's inherent noise so the servos don't jitter at rest — `ALPHA` controls responsiveness vs. smoothness. The `attach()` call with explicit 500–2400 µs pulse bounds is critical because the ESP32Servo default range may not match your specific servo's mechanical limits, and exceeding them can damage the servo's gear train.

The HX711 uses a simple two-wire serial protocol (CLK + DOUT) for the load cell side, while the 16x2 LCD is driven over I2C via a PCF8574 backpack to minimize GPIO usage.

**Wiring Table**

| Component Pin | Connects to ESP32 |
|---|---|
| HX711 VCC | 3.3V |
| HX711 GND | GND |
| HX711 DOUT | GPIO 16 |
| HX711 SCK | GPIO 17 |
| Load Cell E+ | HX711 E+ |
| Load Cell E- | HX711 E- |
| Load Cell A+ | HX711 A+ |
| Load Cell A- | HX711 A- |
| LCD VCC (backpack) | 5V |
| LCD GND (backpack) | GND |
| LCD SDA (backpack) | GPIO 21 |
| LCD SCL (backpack) | GPIO 22 |

**Wiring Diagram**
```
 +---------------------------+
 | ESP32 |
 | |
 | 3.3V |----> HX711 VCC
 | GND |----> HX711 GND
 | GPIO16 (RX2)|<---- HX711 DOUT
 | GPIO17 (TX2)|----> HX711 SCK
 | |
 | 5V |----> LCD Backpack VCC
 | GND |----> LCD Backpack GND
 | GPIO21 (SDA)|----> LCD Backpack SDA
 | GPIO22 (SCL)|----> LCD Backpack SCL
 +---------------------------+

 +----------------+ +-------------------+
 | HX711 | | Load Cell |
 | | | |
 | E+ |<------| E+ (Excite+) |
 | E- |<------| E- (Excite-) |
 | A+ |<------| A+ (Signal+) |
 | A- |<------| A- (Signal-) |
 +----------------+ +-------------------+

 +---------------------------+
 | 16x2 LCD + I2C Backpack |
 | (PCF8574, addr 0x27) |
 +---------------------------+
```

The HX711 operates at 3.3V safely on ESP32; the LCD backpack requires 5V for the display contrast, but its I2C lines are 3.3V compatible when the backpack uses a PCF8574.

**Code**
```cpp
#include <Arduino.h>
#include <Wire.h>
#include <LiquidCrystal_I2C.h>
#include <HX711.h>

// HX711 pins
#define DOUT_PIN 16
#define SCK_PIN 17

// I2C LCD: address 0x27, 16 columns, 2 rows
LiquidCrystal_I2C lcd(0x27, 16, 2);
HX711 scale;

// Calibration factor: adjust this after calibration
// Positive or negative depending on load cell orientation
float calibrationFactor = 420.0;

void setup() {
 Serial.begin(115200);

 // Initialize I2C LCD
 Wire.begin(21, 22); // SDA=21, SCL=22
 lcd.init();
 lcd.backlight();
 lcd.setCursor(0, 0);
 lcd.print(" Digital Scale ");
 lcd.setCursor(0, 1);
 lcd.print(" Initializing... ");

 // Initialize HX711
 scale.begin(DOUT_PIN, SCK_PIN);
 scale.set_scale(calibrationFactor);
 scale.tare(); // Reset scale to zero

 delay(2000);
 lcd.clear();
 lcd.setCursor(0, 0);
 lcd.print("Weight:");

 Serial.println("Scale ready. Tare complete.");
 Serial.println("Send 't' to tare, '+'/'-' to adjust calibration.");
}

void loop() {
 // Handle serial calibration commands
 if (Serial.available()) {
 char cmd = Serial.read();
 if (cmd == 't') {
 scale.tare();
 Serial.println("Tared (zeroed).");
 lcd.setCursor(0, 1);
 lcd.print(" Tared! ");
 delay(800);
 } else if (cmd == '+') {
 calibrationFactor += 10.0;
 scale.set_scale(calibrationFactor);
 Serial.print("Cal factor: ");
 Serial.println(calibrationFactor);
 } else if (cmd == '-') {
 calibrationFactor -= 10.0;
 scale.set_scale(calibrationFactor);
 Serial.print("Cal factor: ");
 Serial.println(calibrationFactor);
 }
 }

 if (scale.is_ready()) {
 // Average 5 readings for stability
 float weight = scale.get_units(5);

 // Display on LCD
 lcd.setCursor(0, 0);
 lcd.print("Weight: ");
 lcd.setCursor(0, 1);
 lcd.print(weight, 2);
 lcd.print(" g ");

 Serial.print("Weight: ");
 Serial.print(weight, 2);
 Serial.println(" g");
 } else {
 lcd.setCursor(0, 1);
 lcd.print("HX711 not ready ");
 Serial.println("HX711 not ready.");
 }

 delay(200);
}
```

**How it works:** `scale.tare()` internally records the raw ADC baseline so subsequent `get_units()` calls subtract it automatically, giving a zeroed reading — calling this in `setup()` means whatever is on the scale at boot becomes zero. The `calibrationFactor` divides the raw HX711 count into real-world grams, so you must tune it by placing a known weight and adjusting via the `+`/`-` serial commands until the display matches.

The PIR sensor outputs a simple 3.3V-compatible digital HIGH when motion is detected, making it straightforward to read on any ESP32 GPIO and then drive a relay module's active-LOW or active-HIGH input accordingly.

**Wiring Table**

| Component Pin | Connects to ESP32 |
|---|---|
| PIR VCC | 5V (or 3.3V if sensor supports it) |
| PIR GND | GND |
| PIR OUT | GPIO 27 |
| Relay VCC | 5V |
| Relay GND | GND |
| Relay IN | GPIO 26 |
| Relay COM | One terminal of light circuit |
| Relay NO | Other terminal of light circuit |

**Wiring Diagram**
```
        +------------------+
        |      ESP32       |
        |                  |        +-------------+
        |        GPIO 27 --+--------+ OUT         |
        |                  |        |  PIR SENSOR |
        |            3.3V --+-------+ VCC (or 5V) |
        |             GND --+-------+ GND         |
        |                  |        +-------------+
        |                  |
        |        GPIO 26 --+--------+-------------+
        |                  |        | IN   RELAY  |
        |              5V --+-------+ VCC  MODULE |
        |             GND --+-------+ GND         |
        |                  |        | COM ---- NO |
        +------------------+        +--|------|-+
                                       |      |
                                    [LIGHT CIRCUIT]
```

The relay's mains-side (COM/NO) terminals switch the actual light load — ensure the relay module is rated for your load voltage and current, and never touch mains wiring while powered.

**Code**
```cpp
#include <Arduino.h>

const int PIR_PIN   = 27;  // PIR sensor output
const int RELAY_PIN = 26;  // Relay control input

// How long to keep the light on after motion stops (milliseconds)
const unsigned long LIGHT_ON_DURATION_MS = 10000;

unsigned long lastMotionTime = 0;
bool lightOn = false;

void setup() {
  Serial.begin(115200);
  pinMode(PIR_PIN,   INPUT);
  pinMode(RELAY_PIN, OUTPUT);

  // Start with relay off (light off)
  // Most relay modules are active-HIGH: HIGH = relay energized = light ON
  digitalWrite(RELAY_PIN, LOW);

  Serial.println("PIR + Relay system ready. Waiting for motion...");
}

void loop() {
  int motionDetected = digitalRead(PIR_PIN);

  if (motionDetected == HIGH) {
    lastMotionTime = millis();

    if (!lightOn) {
      digitalWrite(RELAY_PIN, HIGH);  // Turn light ON
      lightOn = true;
      Serial.println("Motion detected! Light ON.");
    }
  }

  // Turn light off after timeout with no new motion
  if (lightOn && (millis() - lastMotionTime >= LIGHT_ON_DURATION_MS)) {
    digitalWrite(RELAY_PIN, LOW);  // Turn light OFF
    lightOn = false;
    Serial.println("No motion timeout. Light OFF.");
  }
}
```

**How it works:** The code uses a timestamp (`lastMotionTime`) updated on every HIGH reading from the PIR, combined with `millis()` for a non-blocking timeout — this keeps the light on for `LIGHT_ON_DURATION_MS` milliseconds after the *last* detected motion rather than cutting off the instant the PIR signal drops, which prevents annoying flicker during sustained activity. The `lightOn` flag prevents redundant `digitalWrite` calls on every loop iteration while motion is continuously detected.
